-- Generate random hex identifier
local function _0xRandHex(len)
    local c = "0123456789abcdef"
    local r = "_0x"
    for i = 1, (len or 4) do
        r = r .. c:sub(math.random(1, 16), math.random(1, 16))
    end
    return r
end

-- Generate random alphanumeric identifier
local function _0xRandAlpha(len)
    local c = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
    local r = "_"
    for i = 1, (len or 8) do
        local idx = math.random(1, #c)
        r = r .. c:sub(idx, idx)
    end
    return r
end

