-- ====================== ENVIRONMENT AUTHENTICITY ======================
-- Refuses to run inside an environment logger / emulated Roblox state.
--
-- These are NOT the public getgold/wYn snippets. Those are all predefined by
-- now - a logger only has to special-case the exact literals - and most work
-- by hanging the thread in a `while` loop on a crafted error, which in a real
-- client that happens to trip is an unkillable freeze rather than a clean
-- exit. Every check below instead asserts an ENGINE INVARIANT that a logger
-- has to reimplement correctly to pass, and returns a plain boolean.
--
-- All fifteen were run against the real client before shipping, so none of
-- them false-positive on a genuine environment. Deliberately engine-level
-- rather than executor-level (no getgc / no custom globals beyond
-- getrawmetatable), because executors differ from each other and a customer
-- on a different one must not be kicked.
--
-- WHY A THRESHOLD, and this is a deliberate departure worth knowing about:
-- the ask was "if one trips, kick". One is risky - these are verified on
-- Volt, and a single quirk on some other executor would kick a paying
-- customer for nothing. A logger breaks MANY invariants at once because it is
-- emulating the whole datamodel, so two is enough to catch one while a lone
-- oddity stays harmless. Set _0xENVNeed = 1 for the literal behaviour.
--
-- An ERRORING check counts as inconclusive, not as a trip, for the same
-- reason.
--
-- The kick names the failing check INDEXES so a customer can quote the
-- number and it points at one check instead of "it did not work". That is a
-- support-vs-secrecy trade made on purpose: it does tell someone probing
-- this which invariant they tripped, but the indexes are countable from the
-- source anyway, so it gives away little that reading the file would not.
local _0xENVNeed = 2

do
    local RS = game:GetService("RunService")
    local checks = {
        -- Services are cached singletons and resolve identically by both routes.
        function()
            local k = "Pla" .. "yers"
            -- rawequal, so this is a true identity test rather than
            -- anything a proxy could fake through __eq.
            return rawequal(game:GetService(k), game[k])
               and rawequal(game:GetService(k), game:GetService(k))
               and workspace == game:GetService("Work" .. "space")
        end,
        -- Every Instance shares ONE metatable. Proxy objects almost never do.
        function()
            local m = getrawmetatable(game)
            return m ~= nil and m == getrawmetatable(workspace)
               and m == getrawmetatable(Instance.new("Part"))
        end,
        -- typeof on userdata. A table-based fake reports "table".
        function()
            return typeof(game) == "Instance" and typeof(Vector3.new()) == "Vector3"
               and typeof(CFrame.new()) == "CFrame" and typeof(Enum.KeyCode) == "Enum"
               and typeof(Enum.KeyCode.Space) == "EnumItem"
        end,
        -- IsA walks the real class tree, including negatives.
        function()
            return workspace:IsA("Model") and workspace:IsA("Instance")
               and not workspace:IsA("Part") and Instance.new("Part"):IsA("BasePart")
        end,
        -- EnumItem identity, numeric value and tostring form.
        function()
            return tostring(Enum.KeyCode.Space) == "Enum.KeyCode.Space"
               and Enum.KeyCode.Space.Value == 32
               and Enum.KeyCode.Space == Enum.KeyCode.Space
               and Enum.KeyCode.Space.Name == "Space"
        end,
        -- Real Luau error text, not a stubbed message.
        function()
            local _, m = pcall(function() local x = nil; return x.Parent end)
            return type(m) == "string" and m:find("attempt to index nil") ~= nil
        end,
        -- debug.info separates C functions from Lua ones.
        function()
            return debug.info(print, "s") == "[C]"
               and debug.info(function() end, "s") ~= "[C]"
        end,
        -- Task scheduler ordering: spawn is immediate, defer waits for the
        -- current thread to yield. A hand-rolled scheduler gets this wrong.
        function()
            local seq = {}
            task.defer(function() table.insert(seq, 3) end)
            task.spawn(function() table.insert(seq, 1) end)
            table.insert(seq, 2)
            RS.Heartbeat:Wait()
            return seq[1] == 1 and seq[2] == 2 and seq[3] == 3
        end,
        -- Destroy() permanently LOCKS the Parent property.
        function()
            local x = Instance.new("Part"); x.Parent = workspace; x:Destroy()
            local ok, m = pcall(function() x.Parent = workspace end)
            return (not ok) and tostring(m):lower():find("locked") ~= nil
        end,
        -- Signal:Wait resumes with the real arguments.
        function()
            local host = Instance.new("Part"); host.Parent = workspace
            local got
            task.spawn(function() got = host.ChildAdded:Wait() end)
            RS.Heartbeat:Wait()
            local kid = Instance.new("IntValue"); kid.Name = "p"; kid.Parent = host
            RS.Heartbeat:Wait(); RS.Heartbeat:Wait()
            local ok = got ~= nil and typeof(got) == "Instance" and got.Name == "p"
            host:Destroy()
            return ok
        end,
        -- A property change actually raises its signal.
        function()
            local x = Instance.new("Part"); x.Parent = workspace
            local fired = false
            local c = x:GetPropertyChangedSignal("Name"):Connect(function() fired = true end)
            x.Name = "p" .. tostring(math.random())
            RS.Heartbeat:Wait()
            c:Disconnect(); x:Destroy()
            return fired
        end,
        -- Ancestry, and Parent going nil on destroy.
        function()
            local x = Instance.new("Part"); x.Parent = workspace
            local r = x:IsDescendantOf(game) and x.Parent == workspace
                  and workspace.Parent == game
            x:Destroy()
            return r and x.Parent == nil
        end,
        -- Vector / CFrame maths actually computes.
        function()
            local c = CFrame.new(1, 2, 3) * CFrame.new(0, 0, -5)
            return (c.Position - Vector3.new(1, 2, -2)).Magnitude < 1e-4
               and Vector3.new(1,0,0):Cross(Vector3.new(0,1,0)).Z > 0.99
               and Vector3.new(3,4,0).Magnitude == 5
        end,
        -- table.freeze is enforced, and binary packing round-trips.
        function()
            local tb = table.freeze({ a = 1 })
            local b = buffer.create(8); buffer.writeu32(b, 0, 3735928559)
            return table.isfrozen(tb) and not pcall(function() tb.a = 2 end)
               and buffer.readu32(b, 0) == 3735928559
               and select(1, string.unpack("<i4", string.pack("<i4", -1337))) == -1337
        end,
        -- A nonexistent service raises; a missing child returns nil.
        function()
            local bogus = "Nz" .. tostring(math.random(1e6)) .. "Service"
            return not pcall(function() return game:GetService(bogus) end)
               and game:FindFirstChild("ZzNopeNotHere") == nil
               and #game:GetChildren() > 8
        end,
    }

    -- Which ones tripped, by index, so a customer can quote the number and
    -- it points straight at a check rather than "it did not work".
    local failed = {}
    for i, fn in ipairs(checks) do
        local ok, res = pcall(fn)
        -- Only an explicit false counts. An error is inconclusive.
        if ok and res == false then
            failed[#failed + 1] = i
            if #failed >= _0xENVNeed then break end
        end
    end

    if #failed >= _0xENVNeed then
        pcall(function()
            game:GetService("Players").LocalPlayer:Kick(
                "failed to startup, err : " .. table.concat(failed, ",")
                .. ". Contact Admin.")
        end)
        return
    end
end
