-- ==================== ENCRYPTED CREDENTIALS ====================
-- Credentials are XOR encrypted and only decrypted with valid session
_0xa299._0xEncKey = nil -- Session encryption key (set after validation)
_0xa299._0xSessionValid = false -- Session validation flag
_0xa299._0xSessionToken = nil -- Current session token

-- XOR encryption/decryption function
_0xa299._0xXorCrypt = function(data, key)
    if not data or not key or key == "" then return nil end
    local result = {}
    local keyLen = #key
    for i = 1, #data do
        local dataChar = string.byte(data, i)
        local keyChar = string.byte(key, ((i - 1) % keyLen) + 1)
        table.insert(result, string.char(bit32 and bit32.bxor(dataChar, keyChar) or ((dataChar + keyChar) % 256)))
    end
    return table.concat(result)
end

-- Base64 decode function
_0xa299._0xB64Decode = function(data)
    local b = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    data = string.gsub(data, '[^'..b..'=]', '')
    return (data:gsub('.', function(x)
        if (x == '=') then return '' end
        local r, f = '', (b:find(x) - 1)
        for i = 6, 1, -1 do r = r .. (f % 2^i - f % 2^(i-1) > 0 and '1' or '0') end
        return r
    end):gsub('%d%d%d?%d?%d?%d?%d?%d?', function(x)
        if (#x ~= 8) then return '' end
        local c = 0
        for i = 1, 8 do c = c + (x:sub(i, i) == '1' and 2^(8-i) or 0) end
        return string.char(c)
    end))
end

