-- Load a custom (non-Roblox) font from a hosted .ttf. Falls back to a heavy
-- built-in face if no URL is set or the executor can't write files.
function _0xa299._0xWMFont()
    local font = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Heavy)
    pcall(function()
        local url = _0xa299._0xWM.fontUrl
        if not url or url == "" then return end
        if not (writefile and isfile and getcustomasset) then return end
        local ttf = _0xa299._0xWM.fontFile
        if not isfile(ttf) then
            writefile(ttf, game:HttpGet(url))
        end
        local fam     = _0xa299._0xWM.fontFamily
        local famFile = fam .. ".font"
        writefile(famFile, _0xa299._0x5f86:JSONEncode({
            name  = fam,
            faces = {{ name = "Regular", weight = 400, style = "normal", assetId = getcustomasset(ttf) }}
        }))
        font = Font.new(getcustomasset(famFile))
    end)
    return font
end

