-- Looping shine sweep. One band travels across, then a short pause.
function _0xa299._0xWMShine()
    if _0xa299._0xWM.shineActive then return end
    _0xa299._0xWM.shineActive = true
    task.spawn(function()
        local TweenService = game:GetService("TweenService")
        while _0xa299._0xWM.visible do
            local g = _0xa299._0xWM.gradient
            if g then
                g.Offset = Vector2.new(-1.1, 0)
                local tw = TweenService:Create(
                    g,
                    TweenInfo.new(6, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut),
                    { Offset = Vector2.new(1.1, 0) }
                )
                tw:Play()
                tw.Completed:Wait()
            end
            task.wait(4) -- gap between shine waves
        end
        _0xa299._0xWM.shineActive = false
    end)
end

