        end
        
        -- Track W key state
        local UIS = game:GetService("UserInputService")
        
        _0xa299._0x7c3aInputBegan = UIS.InputBegan:Connect(function(input, gameProcessed)
            if input.KeyCode == Enum.KeyCode.W then
                _0xa299._0x7c3aWHeld = true
            end
        end)
        
        _0xa299._0x7c3aInputEnded = UIS.InputEnded:Connect(function(input)
            if input.KeyCode == Enum.KeyCode.W then
                _0xa299._0x7c3aWHeld = false
            end
        end)
        
        _0xa299._0x7c3a = game:GetService("RunService").Heartbeat:Connect(function()
            pcall(function()
                local character = _0xa299._0x396d.Character
                if not character then return end
                
                local humanoid = character:FindFirstChildOfClass("Humanoid")
                if not humanoid then return end
                
                local animator = humanoid:FindFirstChildOfClass("Animator")
                if not animator then return end

                -- Mid-dash: hands off entirely. The dash owns WalkSpeed and
                -- its own animation for 0.4-0.5 s, and the game restores the
                -- speed when it clears FlickerStep. Returning rather than
                -- just skipping the speed write also leaves the dash
                -- animation alone. See _0xa299._0xDashActive.
                if _0xa299._0xDashActive() then return end

                -- If W is held, constantly enforce walkspeed 28 and run animation
                if _0xa299._0x7c3aWHeld then
                    -- Always enforce walkspeed 28 while holding W
                    if humanoid.WalkSpeed ~= 28 then
                        humanoid.WalkSpeed = 28
                    end
                    
                    -- Set running BoolValue to true
                    local runningVal = _0xa299._0x396d.Backpack:FindFirstChild("running")
                    if runningVal and not runningVal.Value then
                        runningVal.Value = true
                    end
                    
                    -- Stop walk animation if playing
                    for _, track in pairs(animator:GetPlayingAnimationTracks()) do
                        if track.Animation and track.Animation.AnimationId == "rbxassetid://6256500765" then
                            track:Stop()
                            break
                        end
                    end
                    
                    -- Ensure run animation is playing
                    if not _0xa299._0x7c3aRunTrack or not _0xa299._0x7c3aRunTrack.IsPlaying then
                        local runAnim = Instance.new("Animation")
                        runAnim.AnimationId = "rbxassetid://5571412330"
                        _0xa299._0x7c3aRunTrack = animator:LoadAnimation(runAnim)
                        _0xa299._0x7c3aRunTrack:Play()
                    end
                end
                
                -- If W is not held and run animation is playing, stop it and clear tracks
                if not _0xa299._0x7c3aWHeld and _0xa299._0x7c3aRunTrack and _0xa299._0x7c3aRunTrack.IsPlaying then
                    _0xa299._0x7c3aRunTrack:Stop()
                    _0xa299._0x7c3aRunTrack = nil
                    humanoid.WalkSpeed = 16
                    
                    -- Set running BoolValue to false
                    local runningVal = _0xa299._0x396d.Backpack:FindFirstChild("running")
                    if runningVal and runningVal.Value then
                        runningVal.Value = false
                    end
                end
            end)
        end)
        
        _0xa299._0x8545:Notify("Player", "Auto Run enabled", 3, "check")
    else
        if _0xa299._0x7c3a then
            _0xa299._0x7c3a:Disconnect()
            _0xa299._0x7c3a = nil
        end
        if _0xa299._0x7c3aInputBegan then
            _0xa299._0x7c3aInputBegan:Disconnect()
            _0xa299._0x7c3aInputBegan = nil
        end
        if _0xa299._0x7c3aInputEnded then
            _0xa299._0x7c3aInputEnded:Disconnect()
            _0xa299._0x7c3aInputEnded = nil
        end
        
        -- Stop run animation and walk animation - don't play new animations
        pcall(function()
            local character = _0xa299._0x396d.Character
            if character then
                local humanoid = character:FindFirstChildOfClass("Humanoid")
                if humanoid then
                    humanoid.WalkSpeed = 16
                    
                    -- Stop run track if playing
                    if _0xa299._0x7c3aRunTrack then
                        pcall(function() _0xa299._0x7c3aRunTrack:Stop() end)
                    end
                    
                    -- Stop walk track if playing
                    if _0xa299._0x7c3aWalkTrack then
                        pcall(function() _0xa299._0x7c3aWalkTrack:Stop() end)
                    end
                end
            end
            
            -- Set running BoolValue to false when disabling auto run
            local runningVal = _0xa299._0x396d.Backpack:FindFirstChild("running")
            if runningVal and runningVal.Value then
                runningVal.Value = false
            end
        end)
        
        _0xa299._0x7c3aRunTrack = nil
        _0xa299._0x7c3aWalkTrack = nil
        _0xa299._0x7c3aWHeld = false
        
        if not _0xa299._0x8545._isLoadingConfig then
            _0xa299._0x8545:Notify("Player", "Auto Run disabled", 3, "info")
        end
    end
end)

---------------------------------------------------------------------
-- BACKWARDS RUN (omnidirectional sprint)
--
-- The game only ever enters its run state from a double-tap of W, and
-- onKeyUp calls disableRun() the moment W is released - so strafing or
-- backpedalling always drops you to walk speed.
--
-- Rather than fight that state machine, this simply enforces the run speed
-- and the run animation whenever you are moving in ANY direction, and keeps
-- Backpack.running true so the character reads as running. Movement direction
-- is taken from Humanoid.MoveDirection, so it covers S, A, D and diagonals
-- without caring which keys produced them (works with controller too).
--
-- Deliberately yields to the game in states where running is not legal
-- (blocking, stunned, knocked, ragdolled) so it cannot fight those systems.
---------------------------------------------------------------------
_0xa299._0xBRUN = {
    enabled = false,
    speed = 28,
    conn = nil,
    track = nil,
    animId = "rbxassetid://5571412330",  -- same run anim Auto Run uses
    walkAnimId = "rbxassetid://6256500765",
}

-- True when the game would refuse to let us run anyway.
function _0xa299._0xBRUNBlocked()
    local blocked = false
    pcall(function()
        local char = _0xa299._0x396d.Character
        if not char then blocked = true return end
        if char:FindFirstChild("ragdolled") then blocked = true return end

        local s = _0xa299._0xe08d:FindFirstChild("Settings")
        s = s and s:FindFirstChild(_0xa299._0x396d.Name)
        if s then
            local blockingV = s:FindFirstChild("Blocking")
            local stunnedV = s:FindFirstChild("Stunned")
            if blockingV and blockingV.Value == true then blocked = true end
            if stunnedV and stunnedV.Value == true then blocked = true end
        end
    end)
    return blocked
end

function _0xa299._0xBRUNStop()
    if _0xa299._0xBRUN.conn then
        _0xa299._0xBRUN.conn:Disconnect()
        _0xa299._0xBRUN.conn = nil
    end
    if _0xa299._0xBRUN.track then
        pcall(function() _0xa299._0xBRUN.track:Stop() end)
        _0xa299._0xBRUN.track = nil
    end
    pcall(function()
        local runningVal = _0xa299._0x396d.Backpack:FindFirstChild("running")
        if runningVal and runningVal.Value then runningVal.Value = false end
    end)
end

function _0xa299._0xBRUNStart()
    if _0xa299._0xBRUN.conn then _0xa299._0xBRUN.conn:Disconnect() end

    _0xa299._0xBRUN.conn = _0xa299._0x64b8.Heartbeat:Connect(function()
        if not _0xa299._0xBRUN.enabled then return end
        pcall(function()
            local char = _0xa299._0x396d.Character
            if not char then return end
            local humanoid = char:FindFirstChildOfClass("Humanoid")
            if not humanoid or humanoid.Health <= 0 then return end

            -- Mid-dash: hands off entirely, before the MoveDirection test.
            --
            -- Deliberately NOT folded into _0xBRUNBlocked: that path stops
            -- the run track and clears Backpack.running, which would fight
            -- the dash's own animation and state. A dash is a handover, not a
            -- state we are locked out of, so the correct response is to touch
            -- nothing and let the game put the speed back when it clears
            -- FlickerStep. See _0xa299._0xDashActive.
            if _0xa299._0xDashActive() then return end

            local moving = humanoid.MoveDirection.Magnitude > 0.1

            if moving and not _0xa299._0xBRUNBlocked() then
                if humanoid.WalkSpeed ~= _0xa299._0xBRUN.speed then
                    humanoid.WalkSpeed = _0xa299._0xBRUN.speed
                end

                local runningVal = _0xa299._0x396d.Backpack:FindFirstChild("running")
                if runningVal and not runningVal.Value then runningVal.Value = true end

                local animator = humanoid:FindFirstChildOfClass("Animator")
                if animator then
                    -- Drop the walk cycle so it does not fight the run anim.
                    for _, track in pairs(animator:GetPlayingAnimationTracks()) do
                        if track.Animation and track.Animation.AnimationId == _0xa299._0xBRUN.walkAnimId then
                            track:Stop()
                            break
                        end
                    end
                    if not _0xa299._0xBRUN.track or not _0xa299._0xBRUN.track.IsPlaying then
                        local anim = Instance.new("Animation")
                        anim.AnimationId = _0xa299._0xBRUN.animId
                        _0xa299._0xBRUN.track = animator:LoadAnimation(anim)
                        _0xa299._0xBRUN.track:Play()
                    end
                end
            elseif _0xa299._0xBRUN.track and _0xa299._0xBRUN.track.IsPlaying then
                -- Standing still (or blocked): hand control back to the game.
                _0xa299._0xBRUN.track:Stop()
                _0xa299._0xBRUN.track = nil
                local runningVal = _0xa299._0x396d.Backpack:FindFirstChild("running")
                if runningVal and runningVal.Value then runningVal.Value = false end
            end
        end)
    end)
end

do
    local t = _0xa299._0xPMOV:AddToggle("Omnimovement", false, function(Value)
        _0xa299._0xBRUN.enabled = Value
        if Value then
            _0xa299._0xBRUNStart()
            _0xa299._0x8545:Notify("Player", "omni enabled", 3, "check")
        else
            _0xa299._0xBRUNStop()
            if not _0xa299._0x8545._isLoadingConfig then
                _0xa299._0x8545:Notify("Player", "omni disabled", 3, "info")
            end
        end
    end, {Type = "info", Text = "Sprint in any direction"})

    -- Kept well under the server's WalkSpeed >= 110 auto-report.
    t:AddSettings("Omnimovement"):AddSlider("Omni run speed", 16, 60, 28, function(Value)
        _0xa299._0xBRUN.speed = Value
    end)
end

---------------------------------------------------------------------
-- INFINITE JUMP
--
-- Goes through the GAME's own jump, not Roblox's. One call to
-- GameManager:jump(char, "DoubleJump") (GameManager 4045) does everything a
-- real extra jump does:
--   * clears any existing DashBV / JumpBV off the HRP and the Torso
--   * Emit(HumanoidRootPart.JumpVFXAttachment)  - the jump VFX
--   * createBodyVelocity(Torso, up, 60, 0.1, "JumpBV", Vector3.new(0,1,0))
--   * stopAnimation then getAnimation(type):Play() at Action4
--
-- So it looks like the game's own extra jump because it IS one. No
-- ChangeState(Jumping), no CFrame nudging, no mover of our own - which is
-- what the usual "infinite jump" does and what makes it read as fake.
--
-- Two reasons this shape is the safe one, both checked rather than assumed:
--
--   * "JumpBV" is in the client's OWN allowlist (v.ABV, client 385-410).
--     Any BodyVelocity on our HRP whose name is not in that list self-reports
--     BanMe "Offense 1E" (client 23635), so borrowing the game's own mover
--     name is what keeps this quiet. Rolling our own would not.
--
--   * Its MaxForce is vertical-only (0,1,0), which is exactly the shape our
--     Anti Knockback neutraliser skips (it only eats movers that push on
--     every axis), so the two features do not fight.
--
-- Deliberately does NOT touch Settings.JumpCounters. That is the replicated
-- counter the game gates its own double/triple jump on; writing it locally
-- would desync the HUD pips from what the server believes and buys nothing,
-- because calling jump() directly bypasses the gate anyway.
---------------------------------------------------------------------
