-- Resolve a skill name to its cooldown.
--
-- Two passes rather than one: an exact (case-insensitive) match always wins,
-- and only if nothing matches exactly do we fall back to a substring match.
-- The old single-pass version returned whichever entry happened to be listed
-- first, so "Multi Kunai Throw" could resolve to "Kunai Throw" purely on table
-- order, and an empty-name entry in the list matched literally everything
-- (string.find(x, "", 1, true) always succeeds) - which silently swallowed the
-- tailed-beast cooldowns listed after it.
--
-- PERF: this is called for every cooldown of every visible player, so it is
-- memoised and the table is pre-lowercased once. Previously each call walked
-- all ~87 entries twice, calling string.lower on both sides of every
-- comparison - roughly 170 string allocations per cooldown per frame, which
-- is what made the ESP cooldown tag so expensive.
_0xa299._0x54f1Cache = {}
_0xa299._0x54f1Index = nil

local function _0xBuildCooldownIndex()
    local idx = {exact = {}, subs = {}}
    for _, cd in ipairs(_0xa299._0x2787.cooldowns) do
        if cd.name and cd.name ~= "" then
            local lower = string.lower(cd.name)
            if idx.exact[lower] == nil then idx.exact[lower] = cd.cooldown end
            table.insert(idx.subs, {name = lower, len = #lower, cooldown = cd.cooldown})
        end
    end
    -- Longest first so the first substring hit is already the best one.
    table.sort(idx.subs, function(a, b) return a.len > b.len end)
    _0xa299._0x54f1Index = idx
    return idx
end

function _0xa299._0x54f1(skillName)
    if type(skillName) ~= "string" or skillName == "" then return 10 end

    local cached = _0xa299._0x54f1Cache[skillName]
    if cached then return cached end

    local idx = _0xa299._0x54f1Index or _0xBuildCooldownIndex()
    local target = string.lower(skillName)
    local result = idx.exact[target]

    if not result then
        -- Substring fallback; the list is pre-sorted longest-first so the more
        -- specific skill wins regardless of table order.
        for _, e in ipairs(idx.subs) do
            if string.find(target, e.name, 1, true) then
                result = e.cooldown
                break
            end
        end
    end

    result = result or 10 -- Default fallback
    _0xa299._0x54f1Cache[skillName] = result
    return result
end

