-- Enable: turn on noclip + no stun (tracking what we changed), then run the loop
function _0xa299._0xDestroyStart()
    if _0xa299._0xDP.enabled or _0xa299._0xDP.starting then
        -- print("[Destroy] start IGNORED (enabled=" .. tostring(_0xa299._0xDP.enabled) .. " starting=" .. tostring(_0xa299._0xDP.starting) .. ")")
        return
    end
    _0xa299._0xDP.starting = true

    -- If a config is auto-loading, WAIT for it to finish first. The SaveManager applies
    -- flags in arbitrary order, so "Enable" can fire BEFORE "Auto Continue" / "Minimum
    -- Rank" - reading them now would see autoContinue=false and bail. _0x6905 is true
    -- during autoload and set false ~1s after it completes.
    do
        local waited = 0
        while _0xa299._0x6905 and waited < 20 do
            task.wait(0.3)
            waited += 0.3
        end
    end

    --[[ print("[Destroy] START target=" .. tostring(_0xa299._0xDP.targetPlayer)
        .. " autoContinue=" .. tostring(_0xa299._0xDP.autoContinue)
        .. " hasRanks=" .. tostring(next(_0xa299._0xDP.minRanks or {}) ~= nil)
        .. " autoloading=" .. tostring(_0xa299._0x6905)
        .. " camType=" .. tostring(workspace.CurrentCamera and workspace.CurrentCamera.CameraType)
        .. " loadedIn=" .. tostring(_0xa299._0xe08d:FindFirstChild("Loaded") and _0xa299._0xe08d.Loaded:FindFirstChild(_0xa299._0x396d.Name) ~= nil)) ]]

    -- Force load into game if not loaded - FIRST thing, regardless of camera type.
    if not (_0xa299._0xe08d:FindFirstChild("Loaded") and _0xa299._0xe08d.Loaded:FindFirstChild(_0xa299._0x396d.Name)) then
            _0xa299._0x8545:Notify("Destroy Player", "Force loading into game", 3, "info")
            task.spawn(function()
                pcall(function()
                    _0xa299._0xe08d:WaitForChild("Events"):WaitForChild("DataFunction"):InvokeServer("LoadedIn")
                end)
            end)
            pcall(function()
                _0xa299._0xe08d:WaitForChild("Events"):WaitForChild("DataEvent"):FireServer("LoadedIn")
            end)
            task.wait()
            if _0xa299._0x396d.PlayerGui and _0xa299._0x396d.PlayerGui:FindFirstChild("ClientGui") then
                local menuScreen = _0xa299._0x396d.PlayerGui.ClientGui:FindFirstChild("MenuScreen")
                if menuScreen then menuScreen.Visible = false end
            end
            if _0xa299._0x396d:FindFirstChild("SoundPlaylist") then
                local menuTrack = _0xa299._0x396d.SoundPlaylist:FindFirstChild("MenuTrack")
                if menuTrack then menuTrack.Playing = false end
            end
            -- Gets past the v1551 loading screen first, then waits for the
            -- function to exist. See _0xa299._0xLoadIntoGame.
            _0xa299._0xLoadIntoGame()
    end

    -- Drop a stale saved target (e.g. the player we picked in a PREVIOUS server, which
    -- the config restored) - if they're not in this server, ignore it and auto-pick.
    if _0xa299._0xDP.targetPlayer and not _0xa299._0x71bb:FindFirstChild(_0xa299._0xDP.targetPlayer) then
        _0xa299._0xDP.targetPlayer = nil
    end

    local canAuto = _0xa299._0xDP.autoContinue and next(_0xa299._0xDP.minRanks or {}) ~= nil

    -- Nothing to farm and no auto-continue -> nothing we can do.
    if not _0xa299._0xDP.targetPlayer and not canAuto then
        -- print("[Destroy] BAIL: no target + no auto-continue/rank")
        _0xa299._0xDP.starting = false
        _0xa299._0x8545:Notify("Destroy Player", "Select a player first (or enable Auto Continue + a rank)", 4, "error")
        pcall(function() _0xa299._0xDPToggle:SetValue(false) end)
        return
    end

    -- Quick head-start pick. If nothing yet, we STILL enable - the loop keeps trying
    -- and never turns itself off (that was the autoload bug).
    if not _0xa299._0xDP.targetPlayer and canAuto then
        local tries = 0
        repeat
            local n = _0xa299._0xDestroyPickTarget()
            if n then _0xa299._0xDP.targetPlayer = n; break end
            tries += 1
            task.wait(0.4)
