    _0xa299._0xe9b0 = _0xa299._0x64b8.Heartbeat:Connect(function()
        pcall(function()
            local char = _0xa299._0x396d.Character
            if not char then return end
            
            local humanoid = char:FindFirstChildOfClass("Humanoid")
            if not humanoid then return end
            
            local currentHP = humanoid.Health
            local panicHP = _0xa299._0xa6f6.antiDiePanicHP or 100
            
            if not _0xa299._0xa6f6.antiDie then return end
            
            if currentHP <= panicHP and currentHP > 0 then
