                local villageMatName = playerTeam .. " VillageMat1"
                local villageMat = workspace:FindFirstChild(villageMatName, true)
                
                if villageMat then
                    local hrp = char:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        local targetCFrame = villageMat:IsA("BasePart") and villageMat.CFrame or (villageMat:FindFirstChildWhichIsA("BasePart") and villageMat:FindFirstChildWhichIsA("BasePart").CFrame)
                        if targetCFrame then
                            hrp.CFrame = targetCFrame + Vector3.new(0, 5, 0)
                            _0xa299._0xVelSettle(hrp)
                            _0xa299._0x9d4c = currentTime
                            _0xa299._0x8545:Notify("Security", "Anti Die triggered, went to " .. playerTeam, 3, "shield")
                        end
                    end
                else
                    _0xa299._0x8545:Notify("Security", "Village mat not found: " .. villageMatName, 3, "error")
                end
            end
        end)
    end)
end

