_0xa299._0x26cc.playerHitboxConnection = nil

function _0xa299._0xCreatePlayerHitbox(player)
    if player == _0xa299._0x396d then return end
    if table.find(_0xa299._0x26cc.whitelist, player.Name) then return end
    
    local char = player.Character
    if not char then return end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    
    -- Remove existing hitbox for this player
    if _0xa299._0x26cc.playerHitboxFolders[player.Name] then
        pcall(function() _0xa299._0x26cc.playerHitboxFolders[player.Name]:Destroy() end)
    end
    
    local hbSize = _0xa299._0x26cc.size * 2
    local radius = hbSize / 2
    
    local wireframeFolder = Instance.new("Folder")
    wireframeFolder.Name = "PlayerHitbox_" .. player.Name
    wireframeFolder.Parent = game:GetService("CoreGui")
    
    local purpleColor = Color3.fromRGB(170, 85, 255)
    local segments = 24
    local rings = 3
    
    local function createCircle(axis, offset)
        for i = 0, segments - 1 do
            local angle1 = (i / segments) * math.pi * 2
            local angle2 = ((i + 1) / segments) * math.pi * 2
            
            local p1, p2
            if axis == "XY" then
                p1 = Vector3.new(math.cos(angle1) * radius, math.sin(angle1) * radius, offset)
                p2 = Vector3.new(math.cos(angle2) * radius, math.sin(angle2) * radius, offset)
            elseif axis == "XZ" then
                p1 = Vector3.new(math.cos(angle1) * radius, offset, math.sin(angle1) * radius)
                p2 = Vector3.new(math.cos(angle2) * radius, offset, math.sin(angle2) * radius)
            elseif axis == "YZ" then
                p1 = Vector3.new(offset, math.cos(angle1) * radius, math.sin(angle1) * radius)
                p2 = Vector3.new(offset, math.cos(angle2) * radius, math.sin(angle2) * radius)
            end
            
            local line = Instance.new("LineHandleAdornment")
            line.Adornee = hrp
            line.Length = (p2 - p1).Magnitude
            line.CFrame = CFrame.lookAt(p1, p2)
            line.Thickness = 2
            line.Color3 = purpleColor
            line.AlwaysOnTop = false
            line.ZIndex = 1
            line.Parent = wireframeFolder
        end
    end
    
    -- Create 3 main circles (equator lines)
    createCircle("XY", 0)
    createCircle("XZ", 0)
    createCircle("YZ", 0)
    
    -- Create latitude lines
    for i = 1, rings do
        local latOffset = (i / (rings + 1)) * radius
        local latRadius = math.sqrt(radius * radius - latOffset * latOffset)
        
        -- Upper and lower latitude circles on XZ plane
        for j = 0, segments - 1 do
            local angle1 = (j / segments) * math.pi * 2
            local angle2 = ((j + 1) / segments) * math.pi * 2
            
            -- Upper
            local p1 = Vector3.new(math.cos(angle1) * latRadius, latOffset, math.sin(angle1) * latRadius)
            local p2 = Vector3.new(math.cos(angle2) * latRadius, latOffset, math.sin(angle2) * latRadius)
            
            local line = Instance.new("LineHandleAdornment")
            line.Adornee = hrp
            line.Length = (p2 - p1).Magnitude
            line.CFrame = CFrame.lookAt(p1, p2)
            line.Thickness = 2
            line.Color3 = purpleColor
            line.AlwaysOnTop = false
            line.ZIndex = 1
            line.Parent = wireframeFolder
            
            -- Lower
            local p3 = Vector3.new(math.cos(angle1) * latRadius, -latOffset, math.sin(angle1) * latRadius)
            local p4 = Vector3.new(math.cos(angle2) * latRadius, -latOffset, math.sin(angle2) * latRadius)
            
            local line2 = Instance.new("LineHandleAdornment")
            line2.Adornee = hrp
            line2.Length = (p4 - p3).Magnitude
            line2.CFrame = CFrame.lookAt(p3, p4)
            line2.Thickness = 2
            line2.Color3 = purpleColor
            line2.AlwaysOnTop = false
            line2.ZIndex = 1
            line2.Parent = wireframeFolder
        end
    end
    
    _0xa299._0x26cc.playerHitboxFolders[player.Name] = wireframeFolder
end

function _0xa299._0xClearAllPlayerHitboxes()
    for name, folder in pairs(_0xa299._0x26cc.playerHitboxFolders) do
        pcall(function() folder:Destroy() end)
    end
    _0xa299._0x26cc.playerHitboxFolders = {}
end

function _0xa299._0xUpdateAllPlayerHitboxes()
    _0xa299._0xClearAllPlayerHitboxes()
    if not _0xa299._0x26cc.showOnPlayers then return end
    
    for _, player in ipairs(_0xa299._0x71bb:GetPlayers()) do
        _0xa299._0xCreatePlayerHitbox(player)
    end
end

