-- Record that <child> just went on cooldown for <playerName>.
function _0xa299._0xESPCDMark(playerName, child)
    local active = _0xa299._0xESPCD.active[playerName]
    if not active then
        active = {}
        _0xa299._0xESPCD.active[playerName] = active
    end

    local duration = _0xa299._0x54f1(child.Name)

    -- The server publishes the real start time as an attribute, and the game's
    -- own HUD reads exactly this (gamescript.txt:14962). Use it when it is
    -- there so the timer is exact rather than estimated from when we noticed.
    local usedAt = child:GetAttribute("CustomUsedAt")
    if usedAt then
        active[child.Name] = tick() + (duration - (workspace:GetServerTimeNow() - usedAt))
    else
        active[child.Name] = tick() + duration
    end
end

function _0xa299._0xESPCDWatch(playerName)
    local root = _0xa299._0xESPCD.root or _0xa299._0xe08d:FindFirstChild("Cooldowns")
    _0xa299._0xESPCD.root = root
    local folder = root and root:FindFirstChild(playerName)
    if not folder then return end

    -- Cache the folder so the render path never calls FindFirstChild.
    _0xa299._0xESPCD.folders[playerName] = folder
    _0xa299._0xESPCD.active[playerName] = _0xa299._0xESPCD.active[playerName] or {}

    local function hook(c)
        -- A value change is the game signalling a fresh use of that skill.
        table.insert(_0xa299._0xESPCD.conns, c.Changed:Connect(function()
            _0xa299._0xESPCDMark(playerName, c)
        end))
        -- The exact start time arrives as an attribute, which .Changed does
        -- not cover.
        table.insert(_0xa299._0xESPCD.conns, c:GetAttributeChangedSignal("CustomUsedAt"):Connect(function()
            _0xa299._0xESPCDMark(playerName, c)
        end))
    end

    for _, c in ipairs(folder:GetChildren()) do
        -- Seed ONLY from a published start time. Children already sitting in
        -- the folder are the player's known moves, not running cooldowns, so
        -- stamping them all on sight is what previously showed a target's
        -- entire moveset as though everything were on cooldown.
        if c:GetAttribute("CustomUsedAt") then
            _0xa299._0xESPCDMark(playerName, c)
        end
        hook(c)
    end

    table.insert(_0xa299._0xESPCD.conns, folder.ChildAdded:Connect(function(c)
        -- First ever use of a skill creates the child, so this IS a use.
        _0xa299._0xESPCDMark(playerName, c)
        hook(c)
    end))

    table.insert(_0xa299._0xESPCD.conns, folder.ChildRemoved:Connect(function(c)
        local active = _0xa299._0xESPCD.active[playerName]
        if active then active[c.Name] = nil end
    end))
end

function _0xa299._0xESPCDStart()
    if _0xa299._0xESPCD.hooked then return end

    local root = _0xa299._0xe08d:FindFirstChild("Cooldowns")
    -- Bail WITHOUT latching hooked, so a later toggle can retry. Setting the
    -- flag before this check meant that enabling the ESP before Cooldowns had
    -- replicated killed the registry for the rest of the session.
    if not root then return end

    _0xa299._0xESPCD.hooked = true

    for _, plr in ipairs(_0xa299._0x71bb:GetPlayers()) do
        if plr ~= _0xa299._0x396d then
            pcall(function() _0xa299._0xESPCDWatch(plr.Name) end)
        end
    end

    -- Folders appear when a player first uses a skill, so watch the root too.
    table.insert(_0xa299._0xESPCD.conns, root.ChildAdded:Connect(function(f)
        if f.Name ~= _0xa299._0x396d.Name then
            pcall(function() _0xa299._0xESPCDWatch(f.Name) end)
        end
    end))
end

function _0xa299._0xESPCDStop()
    for _, c in ipairs(_0xa299._0xESPCD.conns) do
        pcall(function() c:Disconnect() end)
    end
    _0xa299._0xESPCD.conns = {}
    _0xa299._0xESPCD.active = {}
    _0xa299._0xESPCD.folders = {}
    _0xa299._0xESPCD.textCache = {}
    _0xa299._0xESPCD.root = nil
    _0xa299._0xESPCD.hooked = false
end

-- The ESP tag and the hotbar both feed off this registry, so it has to stay
-- alive while either one wants it. Without this, switching one off tore the
-- watchers out from under the other and its timers silently went blank.
function _0xa299._0xESPCDSync()
    if _0xa299._0x7676.showCooldowns or _0xa299._0x7676.cooldownHotbar then
        _0xa299._0xESPCDStart()
    else
        _0xa299._0xESPCDStop()
    end
end

function _0xa299._0xESPCDSort(a, b)
    return (a.remaining or math.huge) < (b.remaining or math.huge)
end

-- Resolve one player's live cooldowns into a sorted {name, remaining} array.
-- Shared by the ESP text tag and the hotbar overlay so the two can never
-- disagree about what is actually running. Empty table when nothing is up.
function _0xa299._0xESPCDEntries(playerName, now)
    now = now or tick()

    -- Only skills we have actually observed being used; see the note on
    -- _0xESPCD.active for why the folder's children are not a usable source.
    local active = _0xa299._0xESPCD.active[playerName]
    if not active then return {} end

    local entries = {}

    -- At or under this the timer would render as a dead "0.0", so the cooldown
    -- counts as finished.
    local EXPIRED = 0.05

    for skill, endTime in pairs(active) do
        local remaining = endTime - now
        if remaining > EXPIRED then
            table.insert(entries, {name = skill, remaining = remaining})
        else
            -- Self-pruning. The folder child outlives the cooldown, so
            -- ChildRemoved cannot be relied on to clear these.
            active[skill] = nil
        end
    end

    -- Soonest-ready first. Comparator is hoisted so we do not allocate a
    -- closure on every rebuild.
    table.sort(entries, _0xa299._0xESPCDSort)
    return entries
end

-- Build the one-line summary shown on the ESP, e.g. "Chidori 4.2 | Fireball 1.8"
-- Returns nil when the player has nothing on cooldown, so the tag can be hidden.
function _0xa299._0xESPCDText(playerName)
    local now = tick()

    -- PERF: serve from cache between refreshes. This is called once per visible
    -- player per frame from RenderStepped, so at 60fps with a full server the
    -- uncached path ran ~1200 times a second.
    local cache = _0xa299._0xESPCD.textCache[playerName]
    if cache and (now - cache.at) < _0xa299._0xESPCD.refresh then
        return cache.text or nil
    end

    local function store(v)
        _0xa299._0xESPCD.textCache[playerName] = {text = v or false, at = now}
        return v
    end

    local entries = _0xa299._0xESPCDEntries(playerName, now)
    if #entries == 0 then return store(nil) end

    local parts = {}
    for i = 1, math.min(#entries, _0xa299._0x7676.cooldownMax) do
        local e = entries[i]
        if _0xa299._0x7676.cooldownShowTime and e.remaining then
            table.insert(parts, ("%s %.1f"):format(e.name, e.remaining))
        else
            table.insert(parts, e.name)
        end
    end

    local extra = #entries - #parts
    if extra > 0 then
        table.insert(parts, ("+%d"):format(extra))
    end

    return store(table.concat(parts, " | "))
end

---------------------------------------------------------------------
-- COOLDOWN HOTBAR
--
-- Renders the cooldowns of whoever you are facing as a row of skill slots
-- under the Chakra Sense notifier - icon per skill, remaining seconds in the
-- bottom-right corner, same shape as the game's own bar.
--
-- Built on a ScreenGui rather than the Drawing library: Drawing has no image
-- primitive, and this is a fixed HUD element with no tie to either ESP
-- renderer, so it behaves identically under V1 and V2.
---------------------------------------------------------------------
_0xa299._0xHotbar = {
    gui = nil,
    frame = nil,
    row = nil,
    name = nil,
    slots = {},    -- pooled: index -> {frame, icon, fallback, timer, sep}
    conn = nil,
    target = nil,
    lastPick = 0,
    lastDraw = 0,
    SLOT = 46,
    PAD = 6,
}

-- Who the bar is describing: the living player nearest the centre of where the
-- camera points. Measured by angle rather than screen distance so the pick is
-- unaffected by FOV changes or resolution.
function _0xa299._0xHotbarTarget()
    local cam = _0xa299._0x2f65 or workspace.CurrentCamera
    if not cam then return nil end

    local origin = cam.CFrame.Position
    local look = cam.CFrame.LookVector
    local maxDist = _0xa299._0x7676.maxDistance or 2000

    -- 0.90 ~= a 25 degree cone; anything looser starts grabbing players you
    -- are clearly not looking at.
    local best, bestDot = nil, 0.90

    for _, plr in ipairs(_0xa299._0x71bb:GetPlayers()) do
        if plr ~= _0xa299._0x396d and plr.Character then
            local hrp = plr.Character:FindFirstChild("HumanoidRootPart")
            local hum = plr.Character:FindFirstChildOfClass("Humanoid")
            if hrp and hum and hum.Health > 0 then
                local delta = hrp.Position - origin
                local dist = delta.Magnitude
                if dist > 0 and dist <= maxDist then
                    local dot = look:Dot(delta.Unit)
                    if dot > bestDot then
                        bestDot = dot
                        best = plr
                    end
                end
            end
        end
    end

    return best
end

function _0xa299._0xHotbarBuild()
    local hb = _0xa299._0xHotbar
    if hb.gui then return end

    local gui = Instance.new("ScreenGui")
    gui.Name = _0xa299._0x5f86:GenerateGUID(false)
    gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    gui.IgnoreGuiInset = true
    gui.ResetOnSpawn = false
    gui.DisplayOrder = 100
    gui.Parent = game:GetService("CoreGui")

    -- Sits below the Chakra Sense notifier so the two stack cleanly when both
    -- are enabled. That bar is 40 px tall at y 20, so it ends at y 60 and this
    -- clears it. See _0xa299._0xCSBarH if that height changes again - anything
    -- over 58 starts to collide with this.
    local frame = Instance.new("Frame")
    frame.Position = UDim2.new(0, 0, 0, 78)
    frame.Size = UDim2.new(1, 0, 0, hb.SLOT + 20)
    frame.BackgroundTransparency = 1
    frame.Visible = false
    frame.Parent = gui

    local nameLabel = Instance.new("TextLabel")
    nameLabel.Size = UDim2.new(1, 0, 0, 16)
    nameLabel.BackgroundTransparency = 1
    nameLabel.Font = Enum.Font.GothamBold
    nameLabel.TextSize = 14
    nameLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
    nameLabel.TextStrokeTransparency = 0.4
    nameLabel.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    nameLabel.Parent = frame

    -- One solid grey slab rather than a row of separate cards. AutomaticSize
    -- lets it hug however many slots are live, and it stays centred because of
    -- the 0.5 anchor rather than by being stretched full-width.
    local row = Instance.new("Frame")
    row.AnchorPoint = Vector2.new(0.5, 0)
    row.Position = UDim2.new(0.5, 0, 0, 20)
    row.Size = UDim2.new(0, 0, 0, hb.SLOT)
    row.AutomaticSize = Enum.AutomaticSize.X
    row.BackgroundColor3 = Color3.fromRGB(38, 40, 44)
    row.BackgroundTransparency = 0.2
    row.BorderSizePixel = 0
    row.Parent = frame

    -- Keeps the outer icons off the slab's edges. Deliberately no UICorner:
    -- square corners are the look being asked for.
    local pad = Instance.new("UIPadding")
    pad.PaddingLeft = UDim.new(0, hb.PAD)
    pad.PaddingRight = UDim.new(0, hb.PAD)
    pad.Parent = row

    local layout = Instance.new("UIListLayout")
    layout.FillDirection = Enum.FillDirection.Horizontal
    layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
    layout.VerticalAlignment = Enum.VerticalAlignment.Center
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Padding = UDim.new(0, 0)
    layout.Parent = row

    hb.gui = gui
    hb.frame = frame
    hb.row = row
    hb.name = nameLabel
end

-- Slots are pooled and hidden rather than destroyed; the set of skills on
-- cooldown churns constantly and rebuilding Instances at 60Hz is exactly the
-- kind of thing that cost FPS on the ESP tag before it was cached.
function _0xa299._0xHotbarSlot(i)
    local hb = _0xa299._0xHotbar
    if hb.slots[i] then return hb.slots[i] end

    local S = hb.SLOT

    -- Transparent: the slab behind supplies the background, so slots are just
    -- invisible cells sitting on top of it.
    local slot = Instance.new("Frame")
    slot.Size = UDim2.new(0, S, 0, S)
    slot.BackgroundTransparency = 1
    slot.BorderSizePixel = 0
    slot.LayoutOrder = i
    slot.Parent = hb.row

    -- Hairline divider on the left edge of every slot except the first, so the
    -- dividers land only between icons and never against the slab's edges.
    -- Inset vertically and mostly transparent - meant to be barely there.
    local sep = Instance.new("Frame")
    sep.AnchorPoint = Vector2.new(0, 0.5)
    sep.Position = UDim2.new(0, 0, 0.5, 0)
    sep.Size = UDim2.new(0, 1, 1, -14)
    sep.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    sep.BackgroundTransparency = 0.85
    sep.BorderSizePixel = 0
    sep.Visible = (i > 1)
    sep.Parent = slot

    local icon = Instance.new("ImageLabel")
    icon.Size = UDim2.new(1, -8, 1, -8)
    icon.Position = UDim2.new(0, 4, 0, 4)
    icon.BackgroundTransparency = 1
    icon.ScaleType = Enum.ScaleType.Fit
    icon.Parent = slot

    -- Stand-in for the ~150 bloodline and awakening moves the game ships no
    -- art for. Mirrors what the game's own hotbar does when ID is empty.
    --
    -- Shows the full skill name wrapped over as many lines as it takes.
    -- TextScaled shrinks it to fit rather than the slot growing to suit it, so
    -- a long name never widens the slab. The bottom strip is left clear for
    -- the timer, which would otherwise print straight over the text.
    local fallback = Instance.new("TextLabel")
    fallback.Position = UDim2.new(0, 2, 0, 1)
    fallback.Size = UDim2.new(1, -4, 1, -15)
    fallback.BackgroundTransparency = 1
    fallback.Font = Enum.Font.GothamBold
    fallback.TextColor3 = Color3.fromRGB(255, 255, 255)
    fallback.TextWrapped = true
    fallback.TextScaled = true
    fallback.Visible = false
    fallback.Parent = slot

    -- Ceiling stops short names ballooning to fill the cell; floor keeps long
    -- ones from shrinking into illegibility.
    local fit = Instance.new("UITextSizeConstraint")
    fit.MaxTextSize = 12
    fit.MinTextSize = 5
    fit.Parent = fallback

    local timer = Instance.new("TextLabel")
    timer.AnchorPoint = Vector2.new(1, 1)
    timer.Position = UDim2.new(1, -3, 1, -1)
    timer.Size = UDim2.new(0, 28, 0, 15)
    timer.BackgroundTransparency = 1
    timer.Font = Enum.Font.GothamBold
    timer.TextSize = 13
    timer.TextColor3 = Color3.fromRGB(255, 255, 255)
    timer.TextXAlignment = Enum.TextXAlignment.Right
    timer.TextStrokeTransparency = 0
    timer.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    timer.Parent = slot

    hb.slots[i] = {frame = slot, icon = icon, fallback = fallback, timer = timer, sep = sep}
    return hb.slots[i]
end

function _0xa299._0xHotbarUpdate()
    local hb = _0xa299._0xHotbar
    if not hb.frame then return end

    local now = tick()

    -- The timers print one decimal, so the bar can only visibly change 10x a
    -- second. Redrawing every frame is wasted work at any framerate above that
    -- - the same reason the ESP tag caches its text.
    if now - hb.lastDraw < _0xa299._0xESPCD.refresh then return end
    hb.lastDraw = now

    -- Re-picking every frame makes the bar flicker between two players stood
    -- close together. 5Hz is well inside reaction time.
    if now - hb.lastPick > 0.2 then
        hb.lastPick = now
        hb.target = _0xa299._0xHotbarTarget()
    end

    local target = hb.target
    if target and not target.Parent then target = nil end
    if not target then
        hb.frame.Visible = false
        return
    end

    local entries = _0xa299._0xESPCDEntries(target.Name, now)
    if #entries == 0 then
        hb.frame.Visible = false
        return
    end

    local shown = math.min(#entries, _0xa299._0x7676.cooldownMax)

    -- Name and timers are fixed white; both are set once at build time, so
    -- nothing repaints them here.
    hb.name.Text = target.Name

    for i = 1, shown do
        local e = entries[i]
        local s = _0xa299._0xHotbarSlot(i)
        local id = _0xa299._0xSkillIcon[e.name]

        if id then
            s.icon.Image = "rbxassetid://" .. id
            s.icon.Visible = true
            s.fallback.Visible = false
        else
            s.icon.Visible = false
            s.fallback.Text = e.name
            s.fallback.Visible = true
        end

        -- Blank rather than "0.0" for cooldowns that predate the watcher and
        -- therefore have no known duration.
