function _0xa299._0xApplySkybox(assetId)
    if not assetId or assetId == "" then return end
    
    -- Store original sky if not already stored
    if not _0xa299._0xSkyboxConfig.originalSky then
        local existingSky = game.Lighting:FindFirstChildOfClass("Sky")
        if existingSky then
            _0xa299._0xSkyboxConfig.originalSky = existingSky:Clone()
        end
    end
    
    -- Remove any existing custom sky
    for _, child in ipairs(game.Lighting:GetChildren()) do
        if child:IsA("Sky") then
            child:Destroy()
        end
    end
    
    local url = "http://www.roblox.com/asset/?id=" .. tostring(assetId)
    local sky = Instance.new("Sky")
    sky.Name = "CustomSkybox"
    sky.SkyboxBk = url
    sky.SkyboxDn = url
    sky.SkyboxFt = url
    sky.SkyboxLf = url
    sky.SkyboxRt = url
    sky.SkyboxUp = url
    sky.Parent = game.Lighting
    _0xa299._0xSkyboxConfig.currentSky = sky
    
    _0xa299._0x8545:Notify("Skybox", "Custom skybox applied", 2, "check")
end

function _0xa299._0xRemoveSkybox()
    -- Remove custom sky
    for _, child in ipairs(game.Lighting:GetChildren()) do
        if child:IsA("Sky") then
            child:Destroy()
        end
    end
    
    -- Restore original sky if we had one
    if _0xa299._0xSkyboxConfig.originalSky then
        _0xa299._0xSkyboxConfig.originalSky:Clone().Parent = game.Lighting
    end
    
    _0xa299._0xSkyboxConfig.currentSky = nil
    _0xa299._0x8545:Notify("Skybox", "Skybox removed", 2, "info")
end

