    watchdogConn = nil,
    boneMap = {},
    initialBoneCFs = {},
    textRingParts = {},
    textRingAngle = 0
}

-- Motor6D -> list of possible bone name aliases
-- Supports English (Carti), Japanese/MMD (Spongebob), and bip001 (Thanos) naming conventions
-- First match found wins for each joint
-- Includes both R6 joints (6) and R15 joints (15+) - unmapped ones are harmlessly skipped
_0xa299._0xMotorToBoneAliases = {
    -- R6 core joints
    ["RootJoint"]      = {"pelvis", "bip001 pelvis", "bip001 spine", "全ての親", "センター"},
    ["Neck"]           = {"head", "bip001 head", "頭"},
    ["Left Shoulder"]  = {"upperarm_l", "bip001 l upperarm", "bip001 l clavicle", "腕.L", "肩.L"},
    ["Right Shoulder"] = {"upperarm_r", "bip001 r upperarm", "bip001 r clavicle", "腕.R", "肩.R"},
    ["Left Hip"]       = {"thigh_l", "bip001 l thigh", "足.L"},
    ["Right Hip"]      = {"thigh_r", "bip001 r thigh", "足.R"},
    -- R15 extra joints (used if character has R15 rig)
    ["Waist"]          = {"spine1", "bip001 spine1", "bip001 spine2", "上半身"},
    ["Left Elbow"]     = {"forearm_l", "bip001 l forearm", "ひじ.L"},
    ["Right Elbow"]    = {"forearm_r", "bip001 r forearm", "ひじ.R"},
    ["Left Wrist"]     = {"hand_l", "bip001 l hand", "手首.L"},
    ["Right Wrist"]    = {"hand_r", "bip001 r hand", "手首.R"},
    ["Left Knee"]      = {"calf_l", "bip001 l calf", "ひざ.L"},
    ["Right Knee"]     = {"calf_r", "bip001 r calf", "ひざ.R"},
    ["Left Ankle"]     = {"foot_l", "bip001 l foot", "足首.L"},
    ["Right Ankle"]    = {"foot_r", "bip001 r foot", "足首.R"},
}

-- Find a Motor6D in character by its Name
function _0xa299._0xFindMotor6D(char, motorName)
    for _, desc in ipairs(char:GetDescendants()) do
        if desc:IsA("Motor6D") and desc.Name == motorName then
            return desc
        end
    end
    return nil
end

-- Find a bone by name inside a MeshPart (recursive search)
function _0xa299._0xFindBone(parent, boneName)
    for _, desc in ipairs(parent:GetDescendants()) do
        if desc:IsA("Bone") and desc.Name == boneName then
            return desc
        end
    end
    return nil
end

function _0xa299._0xApplyModel()
