    end
    
    -- For bone-less multi-part models, assign each piece to the nearest R6 body part
    -- so parts follow limb animations naturally.
    -- Core/body parts go to Torso (which tilts/leans) rather than HRP (completely rigid).
    local function getTargetBodyPart(charRef, normalizedY, normalizedX, partName)
        local ln = string.lower(partName)
        
        -- Only arm parts animate with limbs: sword, glove, hand, armring
        if string.find(ln, "sword") or string.find(ln, "glove") or string.find(ln, "hand")
            or string.find(ln, "armring") then
            if normalizedX < -0.1 then
                return charRef:FindFirstChild("Left Arm")
            else
                return charRef:FindFirstChild("Right Arm")
            end
        end
        -- Everything else (body, hair, boots, cloth, etc.) → Torso
        return charRef:FindFirstChild("Torso") or charRef:FindFirstChild("HumanoidRootPart")
    end
    
    -- Clone each MeshPart, scale, and weld preserving resolved offsets
    for _, mp in ipairs(meshParts) do
        local cloned = mp:Clone()
        cloned.Anchored = false
        cloned.CanCollide = false
        cloned.Size = mp.Size * scaleFactor
        
        -- Scale bone positions and clean up stale Motor6Ds from the original model
        for _, desc in ipairs(cloned:GetDescendants()) do
