    if _0xa299._0xWFS.descConn then pcall(function() _0xa299._0xWFS.descConn:Disconnect() end) end
    _0xa299._0xWFS.descConn = char.DescendantAdded:Connect(function(inst)
        if not _0xa299._0xWFS.enabled then return end
        task.wait() -- let it initialize
        if inst:IsA("BasePart") then
            _0xa299._0xWFSPart(inst)
        elseif inst:IsA("Decal") or inst:IsA("Texture") then
            _0xa299._0xWFSDecal(inst)
        end
    end)
end

function _0xa299._0xWFSRemove()
