        end)
        row.MouseButton2Click:Connect(function()
            if _0xa299._0xf947.enabled then _0xa299._0x6e0c() end
        end)
        row.Destroying:Connect(function()
            _0xa299._0xf947.rows[row] = nil
        end)
    end

    local function assignButtons()
        pcall(function()
            local clientGui = _0xa299._0x396d.PlayerGui:WaitForChild("ClientGui", 10)
            if not clientGui then return end

            local mainframe = clientGui:WaitForChild("Mainframe", 10)
            if not mainframe then return end

            local playerList = mainframe:FindFirstChild("PlayerList")
            if not playerList then return end

            local list = playerList:FindFirstChild("List")
            if not list then return end

            for _, plrButton in pairs(list:GetChildren()) do
                hookRow(plrButton)
            end

            if _0xa299._0xf947.connection then
                _0xa299._0xf947.connection:Disconnect()
            end
            _0xa299._0xf947.connection = list.ChildAdded:Connect(hookRow)
        end)
    end

    assignButtons()
    _0xa299._0xLBRefresh(true)

    -- Re-assign when ClientGui is removed/added (respawn). Connect once.
    if not _0xa299._0xf947.guiConnection then
        _0xa299._0xf947.guiConnection = _0xa299._0x396d.PlayerGui.ChildRemoved:Connect(function(removed)
            if removed.Name == "ClientGui" then
                _0xa299._0xf947.rows = {}
                task.wait(1)
                if _0xa299._0xf947.enabled then assignButtons() end
            end
        end)
    end
end

