-- UNLOCK PAID EMOTES
--
-- 18 of the 27 emotes are gated behind three gamepasses (Emote Pack 7,
-- Taunt Emote Pack 6, Dance Emote Pack 5). The gate is PURELY CLIENT-SIDE
-- UI: updateEmotes() (client ~14946) checks
-- `GameManager:hasGamepass(...)` and, if you own the pass, binds a click
-- handler that just does
--     GameManager:getAnimation(name, Humanoid, Action3):Play()
-- otherwise it shows the lock ImageLabel and binds a "buyGamepass" handler
-- instead. Nothing server-side validates ownership when the animation plays,
-- and `getAnimation` resolves locked emotes fine (verified live:
-- handstand -> rbxassetid://10115188659).
--
-- So: hide the lock, unbind the game's buy-handler with getconnections, and
-- bind the same play behaviour the owned path uses.
--
-- The emote list is rebuilt from scratch (clones destroyed and re-cloned)
-- whenever the game fires "updateEmotes" or you respawn, so a ChildAdded
-- watcher re-applies to the new buttons.
---------------------------------------------------------------------
_0xa299._0xEmoteUnlock = { enabled = false, conn = nil, patched = {}, disabled = {} }

function _0xa299._0xEmoteFrame()
    local pg = _0xa299._0x396d:FindFirstChild("PlayerGui")
    local gui = pg and pg:FindFirstChild("ClientGui")
    local mf = gui and gui:FindFirstChild("Mainframe")
    return mf and mf:FindFirstChild("EmoteFrame") or nil
end

-- Mirror of the owned-emote click handler.
function _0xa299._0xPlayEmote(name)
    local char = _0xa299._0x396d.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not (hum and hrp) then return end

    local GM = require(_0xa299._0xe08d:WaitForChild("GameManager"))

    -- The game's own state table, so its "cancel the emote when you move"
    -- logic knows what is playing.
    local v
    pcall(function()
        local env = getsenv(_0xa299._0x396d.PlayerGui.ClientGui.LocalScript)
        v = env and env.v
    end)

    if v then
        if v.Knocked or (v.Settings and v.Settings.Stunned and v.Settings.Stunned.Value) then return end
        if char:FindFirstChild("ragdolled") then return end
    end

    local frame = _0xa299._0xEmoteFrame()
    if frame then frame.Visible = false end
    if v then v.emoteFrameVisible = false end

    if v and v.CurrentEmote then
        pcall(function() GM:stopAnimation(v.CurrentEmote, hum) end)
    end
    if v then
        v.CurrentEmote = name
        v.EmotePosition = hrp.Position
    end

    -- NOTE: deliberately NOT firing playEmoteSounds/stopEmoteSounds here.
    -- Those remotes name the emote to the server, which would be us
    -- announcing a gamepass emote we do not own. The animation itself needs
    -- no remote - it replicates off our own Animator - so we trade the emote
    -- sound for not reporting ourselves.
    pcall(function()
        local track = GM:getAnimation(name, hum, Enum.AnimationPriority.Action3)
        if track then track:Play() end
    end)
end

function _0xa299._0xEmoteUnlockApply()
    if not _0xa299._0xEmoteUnlock.enabled then return end
    local frame = _0xa299._0xEmoteFrame()
    local scroll = frame and frame:FindFirstChild("ScrollingFrame")
    if not scroll then return end

    local GM = require(_0xa299._0xe08d:WaitForChild("GameManager"))
    local st = _0xa299._0xEmoteUnlock

    for _, btn in ipairs(scroll:GetChildren()) do
        local def = btn:IsA("GuiButton") and GM.Emotes and GM.Emotes[btn.Name]
        if def and def.GamepassID and not st.patched[btn] then
            st.patched[btn] = true

            -- Hide the padlock overlay.
            local lock = btn:FindFirstChild("ImageLabel")
            if lock then lock.Visible = false end

            -- Silence the game's "buy this gamepass" handler. Disable rather
            -- than Disconnect so toggling the feature off can restore it.
            local saved = {}
            pcall(function()
                for _, c in ipairs(getconnections(btn.MouseButton1Down)) do
                    pcall(function() c:Disable() end)
                    table.insert(saved, c)
                end
            end)
            st.disabled[btn] = saved

            local emoteName = btn.Name
            btn.MouseButton1Down:Connect(function()
                if not _0xa299._0xEmoteUnlock.enabled then return end
                _0xa299._0xPlayEmote(emoteName)
            end)
        end
    end
end

function _0xa299._0xEmoteUnlockStart()
    _0xa299._0xEmoteUnlock.enabled = true
    _0xa299._0xEmoteUnlockApply()

    -- The list is destroyed and re-cloned on "updateEmotes"/respawn.
    if not _0xa299._0xEmoteUnlock.conn then
        local frame = _0xa299._0xEmoteFrame()
        local scroll = frame and frame:FindFirstChild("ScrollingFrame")
        if scroll then
            _0xa299._0xEmoteUnlock.conn = scroll.ChildAdded:Connect(function()
                task.defer(_0xa299._0xEmoteUnlockApply)
            end)
        end
    end
end

function _0xa299._0xEmoteUnlockStop()
    _0xa299._0xEmoteUnlock.enabled = false
    if _0xa299._0xEmoteUnlock.conn then
        pcall(function() _0xa299._0xEmoteUnlock.conn:Disconnect() end)
        _0xa299._0xEmoteUnlock.conn = nil
    end
    -- Put the padlocks and the game's own buy-handlers back.
    for btn, saved in pairs(_0xa299._0xEmoteUnlock.disabled) do
        pcall(function()
            if btn and btn.Parent then
                local lock = btn:FindFirstChild("ImageLabel")
                if lock then lock.Visible = true end
            end
            for _, c in ipairs(saved) do pcall(function() c:Enable() end) end
        end)
    end
    _0xa299._0xEmoteUnlock.disabled = {}
    _0xa299._0xEmoteUnlock.patched = {}
end

_0xa299._0xEMOT:AddToggle("Unlock Paid Emotes", false, function(Value)
    _0xa299._0xWM.set("UnlockEmotes", Value)
    if Value then
        _0xa299._0xEmoteUnlockStart()
        _0xa299._0x8545:Notify("Emotes", "Paid emotes unlocked - open the emote menu", 4, "check")
    else
        _0xa299._0xEmoteUnlockStop()
        _0xa299._0x8545:Notify("Emotes", "Paid emotes re-locked", 3, "info")
    end
end, {Type = "info", Text = "Unlocks the paid emotes"})

