---------------------------------------------------------------------
-- ACCURATE PLAYER COUNTS
--
-- `ReplicatedStorage.ServerList`'s `Players` attribute is what the game's own
-- UI shows, and it is not close enough to reality to pick a hop target - a
-- server it reports as half empty can already be full, which is why hops kept
-- being refused.
--
-- The Roblox web API gives `playing` AND `maxPlayers` per server, so "is
-- there room" becomes a real subtraction instead of a guess against a
-- hardcoded 20. Only the placeId is sent, to Roblox's own endpoint.
--
-- Paginated deliberately: a page is 100 servers and this game runs hundreds
-- (225 were counted on v1551), so a single page is a biased sample.
---------------------------------------------------------------------
function _0xa299._0xSLApiServers(roomNeeded, maxPages)
    local out = {}
    if not _0xa299._0x0a65 then return out end
    roomNeeded = roomNeeded or 1
    maxPages = maxPages or 4

    local cursor, page = "", 0
    while page < maxPages do
        page = page + 1
        local url = "https://games.roblox.com/v1/games/" .. game.PlaceId
            .. "/servers/Public?sortOrder=Asc&limit=100"
        if cursor ~= "" then url = url .. "&cursor=" .. cursor end

        local body
        pcall(function()
            local r = _0xa299._0x0a65({ Url = url, Method = "GET" })
            body = r and r.Body or nil
        end)
        if not body then break end

        local decoded
        pcall(function() decoded = _0xa299._0x5f86:JSONDecode(body) end)
        if type(decoded) ~= "table" or type(decoded.data) ~= "table" then break end

        for _, s in ipairs(decoded.data) do
            local playing = tonumber(s.playing) or 0
            local cap = tonumber(s.maxPlayers) or 0
            -- Real room check. A full server is the thing we kept trying to
            -- hop into and being refused by.
            if type(s.id) == "string" and s.id ~= game.JobId
               and cap > 0 and (cap - playing) >= roomNeeded then
                table.insert(out, {
                    JobId = s.id,
                    Count = playing,
                    Max = cap,
                    Region = "???",
                    Code = "??",
                })
            end
        end

        cursor = tostring(decoded.nextPageCursor or "")
        if cursor == "" or cursor == "nil" then break end
    end
    return out
end

-- jobId -> region, from the in-game list. The web API carries no region data
-- at all, so this is the only place it exists; joining the two on jobId gives
-- accurate counts AND a usable region filter.
function _0xa299._0xSLRegionMap()
    local map = {}
    local folder = _0xa299._0xSLFolder()
    if not folder then return map end
    for _, entry in pairs(folder:GetChildren()) do
        map[entry.Name] = {
            Region = entry:GetAttribute("ServerRegion") or "???",
            Code   = entry:GetAttribute("CountryCode") or "??",
        }
    end
    return map
end

-- Hop candidates with TRUSTWORTHY counts, optionally region filtered.
-- Shared by the plain hop and the hop-to-lowest, which both need the same
-- API-counts-joined-to-in-game-regions treatment. Returns the list plus a
-- note when the region filter had to be dropped.
-- How much room a server must have to be worth attempting. The API result is
-- a snapshot: a server sitting at 19/20 when it was fetched is very likely
-- full by the time we get to it, and that is precisely the attempt that gets
-- accepted and then silently never teleports us. Asking for a couple of free
-- slots costs a few candidates out of 400 and buys far fewer dead attempts.
_0xa299._0xHopRoomNeeded = 3

function _0xa299._0xHopCandidates(filter)
    local candidates = _0xa299._0xSLApiServers(_0xa299._0xHopRoomNeeded, 4)

    if #candidates == 0 then
        -- API unreachable (no HTTP, rate limited): the in-game list is worse
        -- but beats refusing to hop.
        return _0xa299._0xSLOthers(filter, 20), "api-unavailable"
    end

    local regions = _0xa299._0xSLRegionMap()
    for _, cand in ipairs(candidates) do
        local r = regions[cand.JobId]
        if r then
            cand.Region = r.Region
            cand.Code = r.Code
        end
    end

    if not filter then return candidates, nil end

    local matched = {}
    for _, cand in ipairs(candidates) do
        if _0xa299._0xSLMatchRegion(cand, filter) then
            table.insert(matched, cand)
        end
    end
    if #matched > 0 then return matched, nil end

    -- The API lists servers the in-game folder does not, so a filter can match
    -- nothing simply because we have no region for those jobIds.
    return candidates, "no-region-data"
end

function _0xa299._0xSLAge(sec)
    local d = math.floor(sec / 86400)
    local h = math.floor(sec % 86400 / 3600)
    local m = math.floor(sec % 3600 / 60)
    return string.format("%dd, %dh, %dm", d, h, m)
end

