function _0xa299._0xDropAll()
    local success, playerdata = pcall(function()
        return _0xa299._0xe08d:WaitForChild("Events"):WaitForChild("DataFunction"):InvokeServer("GetData")
    end)
    
    if not success or not playerdata then
        _0xa299._0x8545:Notify("Drop", "Failed to get inventory data", 3, "error")
        return
    end
    
    local inventory = playerdata["Inventory"]
    if not inventory then
        _0xa299._0x8545:Notify("Drop", "No inventory found", 3, "error")
        return
    end
    
    local droppedCount = 0
    for _, itemData in pairs(inventory) do
        if type(itemData) == "table" and itemData.Item then
            local itemName = itemData.Item
            local shouldSkip = false
            
            if _0xa299._0xDropExcluded[itemName] then
                shouldSkip = true
            end
            
            if not shouldSkip and string.find(itemName, "Onyx") then
                shouldSkip = true
            end
            
            if not shouldSkip then
                local quantity = itemData.Quantity or 1
                for _ = 1, quantity do
                    pcall(function()
                        _0xa299._0xe08d:WaitForChild("Events"):WaitForChild("DataEvent"):FireServer("Item", "Selected", itemName)
                    end)
                    task.wait(0.1)
                    pcall(function()
                        _0xa299._0xe08d:WaitForChild("Events"):WaitForChild("DataEvent"):FireServer("DropItem")
                    end)
                    task.wait(0.1)
                end
                droppedCount = droppedCount + quantity
            end
        end
    end
    
    _0xa299._0x8545:Notify("Drop", "Dropped " .. droppedCount .. " items", 3, "check")
end

