        local chunk = table.concat(_0xa299._0xDsyncLogBuffer, "\n") .. "\n"
        if _0xa299._0xDsyncLogCount == #_0xa299._0xDsyncLogBuffer then
            writefile(_0xa299._0xDsyncLogFile, "=== DSYNC DEBUG LOG ===\nStarted: " .. os.date("%Y-%m-%d %H:%M:%S") .. "\n\n" .. chunk)
        else
