_0xa299._0xDSYN:AddButton("Sniff Packets (5s)", function()
    if _0xa299._0xDsync.snifferHook then
        _0xa299._0x8545:Notify("Dsync", "Sniffer already running", 2, "error")
        return
    end

    _0xa299._0xDsync.snifferData = {}
    _0xa299._0xDsync.snifferSub = {}
    _0xa299._0x8545:Notify("Dsync", "Sniffing packets for 5 seconds move around", 5, "info")

    _0xa299._0xDsync.snifferHook = function(packet)
        local id = packet.PacketId
        if not _0xa299._0xDsync.snifferData[id] then
            _0xa299._0xDsync.snifferData[id] = { count = 0, sizes = {} }
        end
        local entry = _0xa299._0xDsync.snifferData[id]
        entry.count = entry.count + 1
        if #entry.sizes < 5 then
            table.insert(entry.sizes, packet.Size)
        end

        if id == 0x83 then
            pcall(function()
                local buf = packet.AsBuffer
                local len = buffer.len(buf)
                if len >= 2 then
                    local subId = buffer.readu8(buf, 1)
                    local key = string.format("0x%02X", subId)
                    if not _0xa299._0xDsync.snifferSub[key] then
                        _0xa299._0xDsync.snifferSub[key] = { count = 0, sizes = {} }
                    end
                    local sub = _0xa299._0xDsync.snifferSub[key]
                    sub.count = sub.count + 1
                    if #sub.sizes < 5 then
                        table.insert(sub.sizes, len)
                    end
                end
            end)
        end
    end

    pcall(function()
        raknet.add_send_hook(_0xa299._0xDsync.snifferHook)
    end)

    task.delay(5, function()
        pcall(function()
            raknet.remove_send_hook(_0xa299._0xDsync.snifferHook)
        end)
        _0xa299._0xDsync.snifferHook = nil

        local results = {}
        for id, data in pairs(_0xa299._0xDsync.snifferData) do
            table.insert(results, {id = id, count = data.count, sizes = data.sizes})
        end
        table.sort(results, function(a, b) return a.count > b.count end)

        local lines = {"Packet IDs (sorted by frequency):"}
        for _, r in ipairs(results) do
            local sizeStr = table.concat(r.sizes, ",")
            table.insert(lines, string.format("  0x%02X -> %d pkts (sizes: %s)", r.id, r.count, sizeStr))
        end

        local subResults = {}
        for key, data in pairs(_0xa299._0xDsync.snifferSub) do
            table.insert(subResults, {id = key, count = data.count, sizes = data.sizes})
        end
        table.sort(subResults, function(a, b) return a.count > b.count end)

        table.insert(lines, "")
        table.insert(lines, "0x83 sub-packet IDs (byte at offset 1):")
        for _, r in ipairs(subResults) do
            local sizeStr = table.concat(r.sizes, ",")
            table.insert(lines, string.format("  %s -> %d pkts (sizes: %s)", r.id, r.count, sizeStr))
        end

        -- Also dump first few bytes of 0x83 packets for deeper analysis
        local output = table.concat(lines, "\n")
        print("[Dsync Sniffer]\n" .. output)
        _0xa299._0x8545:Notify("Dsync Sniffer", output, 20, "info")
    end)
end)

_0xa299._0xDSYN:AddButton("Dump 0x83 Bytes (3s)", function()
    if _0xa299._0xDsync.snifferHook then
        _0xa299._0x8545:Notify("Dsync", "Sniffer already running", 2, "error")
        return
    end

    local dumps = {}
    _0xa299._0x8545:Notify("Dsync", "Dumping 0x83 packet bytes for 3 seconds move around", 3, "info")

    _0xa299._0xDsync.snifferHook = function(packet)
        if packet.PacketId == 0x83 and #dumps < 15 then
            pcall(function()
                local buf = packet.AsBuffer
                local len = math.min(buffer.len(buf), 32)
                local bytes = {}
                for i = 0, len - 1 do
                    table.insert(bytes, string.format("%02X", buffer.readu8(buf, i)))
                end
                table.insert(dumps, {
                    size = buffer.len(buf),
                    hex = table.concat(bytes, " ")
                })
            end)
        end
    end

    pcall(function()
        raknet.add_send_hook(_0xa299._0xDsync.snifferHook)
    end)

    task.delay(3, function()
        pcall(function()
            raknet.remove_send_hook(_0xa299._0xDsync.snifferHook)
        end)
        _0xa299._0xDsync.snifferHook = nil

        local lines = {"0x83 packet hex dumps (first 32 bytes each):"}
        for i, d in ipairs(dumps) do
            table.insert(lines, string.format("#%d [%d bytes]: %s", i, d.size, d.hex))
        end
        local output = table.concat(lines, "\n")
        print("[Dsync Dump]\n" .. output)
        _0xa299._0x8545:Notify("Dsync Dump", output, 20, "info")
    end)
end)
