function _0xa299._0x6790(playerdata, itemName)
    local function checkLocation(location)
        if not location then return false end
        for _, itemData in pairs(location) do
            if type(itemData) == "table" and itemData.Item == itemName then
                return true
            end
        end
        return false
    end

    if not playerdata then return false end
    if checkLocation(playerdata["Inventory"]) then return true end
    if checkLocation(playerdata["Loadout"]) then return true end
    return false
end

function _0xa299._0x2f0f(playerdata, itemNames)
    for _, name in ipairs(itemNames) do
        if _0xa299._0x6790(playerdata, name) then
            return true
        end
    end
    return false
end

function _0xa299._0xd689(playerdata, eyeType)
    if not playerdata then return nil end

    local function getFromData(d)
        if not d then return nil end
        if eyeType == "Mangekyo" then
            return d.MangekyoName or d["Mangekyo Name"] or d["MangekyoName"]
        else
            return d.RinneganName or d["Rinnegan Name"] or d["RinneganName"]
        end
    end

    local function deepFind(tbl, depth)
        if type(tbl) ~= "table" then return nil end
        if depth and depth <= 0 then return nil end

        local direct = getFromData(tbl)
        if direct ~= nil then
            return direct
        end

        for _, v in pairs(tbl) do
            if type(v) == "table" then
                local found = deepFind(v, depth and (depth - 1) or nil)
                if found ~= nil then
                    return found
                end
            end
        end
        return nil
    end

    local sources = {playerdata.Inventory, playerdata.Loadout}
    for _, src in ipairs(sources) do
        if type(src) == "table" then
            local slotNum = eyeType == "Mangekyo" and 3 or 28
            local entry = src[slotNum] or src[tostring(slotNum)]
            local direct = deepFind(entry, 6)
            if direct ~= nil then
                return direct
            end

            local found = deepFind(src, 6)
            if found ~= nil then
                return found
            end
        end
    end

    return nil
end

