_0xa299._0x30f0:AddButton("Purchase Item", function()
    if _0xa299._0x96d0 == "" then
        _0xa299._0x8545:Notify("Purchase", "Enter an item name", 3, "error")
        return
    end
    
    -- Just fire it. No vendor resolution, no "shop not loaded" gate.
    --
    -- This went through _0xDialogPart("TorchMesh") - stream our surroundings,
    -- pick the nearest copy, bounded wait, refuse if nothing turned up - and
    -- refusing is the part that was wrong. User-confirmed: the plain call works,
    -- so the gate was only ever stopping purchases that would have gone through.
    --
    -- workspace["TorchMesh"] is an INDEX, so it raises rather than returning nil
    -- when the stall is not replicated, and it sits inside the pcall below. That
    -- is deliberate and is the reason there is no nil check: a nil 5th argument
    -- would be a malformed remote call, which is its own problem, whereas the
    -- raise is caught and reported as a failed purchase. Price stays 0 and the
    -- server works out the real figure.
    local item = _0xa299._0x96d0
    local before = _0xa299._0xCountItem(_0xa299._0xLocalData(), item)

    local ok = pcall(function()
        local args = {
            [1] = "Pay",
            [2] = 0,
            [3] = item,
            [4] = _0xa299._0x4e25,
            [5] = workspace["TorchMesh"]
        }
        _0xa299._0xe08d:WaitForChild("Events"):WaitForChild("DataFunction"):InvokeServer(unpack(args, 1, 5))
    end)
    if not ok then
        _0xa299._0x8545:Notify("Purchase", "Purchase call failed", 3, "error")
        return
    end

    for _ = 1, 30 do
        task.wait(0.1)
        if _0xa299._0xCountItem(_0xa299._0xLocalData(), item) > before then
            _0xa299._0x8545:Notify("Purchase", "Purchased " .. _0xa299._0x4e25 .. "x " .. item, 3, "check")
            return
        end
    end
    _0xa299._0x8545:Notify("Purchase", "No item received - check Ryo / vendor stocks '" .. item .. "'", 4, "warning")
end)

