                        local npcName = model.Name
                        if not addedNPCs[npcName] and not _0xa299._0x71bb:FindFirstChild(npcName) then
                            table.insert(NPCs, npcName)
                            addedNPCs[npcName] = true
                        end
                    end
                end
            end
        end
    end
    
    table.sort(NPCs)
    return NPCs
end

