_0xa299._0xb8d0:AddButton("Teleport to Corrupted Point", function()
    local char = _0xa299._0x396d.Character
    if not char or not char:FindFirstChild("HumanoidRootPart") then
        _0xa299._0x8545:Notify("Teleport", "Character not found", 3, "error")
        return
    end
    
    local hrp = char.HumanoidRootPart
    local closestPoint = nil
    local closestDist = math.huge
    
    local corruptedPoint = workspace:FindFirstChild("CorruptedPoint")
    if corruptedPoint then
        local destroyed = corruptedPoint:FindFirstChild("Destroyed")
        if not (destroyed and destroyed:IsA("BoolValue") and destroyed.Value == true) then
            local pos
            if corruptedPoint:IsA("BasePart") then
                pos = corruptedPoint.Position
            elseif corruptedPoint:IsA("Model") then
                local primary = corruptedPoint.PrimaryPart or corruptedPoint:FindFirstChildWhichIsA("BasePart")
                if primary then
                    pos = primary.Position
                end
            end
            if pos then
                closestDist = (pos - hrp.Position).Magnitude
                closestPoint = pos
            end
        end
    end
    
    if closestPoint then
        hrp.CFrame = CFrame.new(closestPoint + Vector3.new(0, 3, 0))
        _0xa299._0x8545:Notify("Teleport", string.format("Teleported to Corrupted Point (%.0f studs away)", closestDist), 3, "check")
    else
        _0xa299._0x8545:Notify("Teleport", "No Corrupted Points found", 3, "error")
    end
end)

_0xa299._0xb8d0:AddButton("Collect All Relics", function()
    local char = _0xa299._0x396d.Character
    if not char or not char:FindFirstChild("HumanoidRootPart") then
        _0xa299._0x8545:Notify("Teleport", "Character not found", 3, "error")
        return
    end
    
    local hrp = char.HumanoidRootPart
    local startingPosition = hrp.CFrame
    
    local relicNames = {"Biyo Relic", "Frozen Relic", "Mello Relic"}
    local foundRelics = {}
    local collectedCount = 0
    
    for _, relicName in ipairs(relicNames) do
        local relic = workspace:FindFirstChild(relicName)
        if relic then
            table.insert(foundRelics, {name = relicName, instance = relic})
        end
    end
    
    if #foundRelics == 0 then
        _0xa299._0x8545:Notify("Teleport", "No relics found in workspace", 3, "error")
        return
    end
    
    _0xa299._0x8545:Notify("Teleport", "Found " .. #foundRelics .. " relic(s). Collecting...", 3, "info")
    
    for _, relicData in ipairs(foundRelics) do
        local relic = relicData.instance
        local relicName = relicData.name
        
        local targetPart = relic:FindFirstChild("HumanoidRootPart") or relic:FindFirstChildWhichIsA("BasePart") or relic
        if targetPart and targetPart:IsA("BasePart") then
            hrp.CFrame = targetPart.CFrame + Vector3.new(0, 3, 0)
            task.wait(0.5)
            
            local args = {"Relic", relicName}
            
            local success = pcall(function()
                _0xa299._0xe08d:WaitForChild("Events"):WaitForChild("DataEvent"):FireServer(unpack(args))
            end)
            
            if success then
                collectedCount = collectedCount + 1
            end
            
            task.wait(0.3)
        end
    end
    
    task.wait(0.3)
    hrp.CFrame = startingPosition
    
    _0xa299._0x8545:Notify("Teleport", "Collected " .. collectedCount .. "/" .. #foundRelics .. " relics", 3, "check")
end)

-- Click to Teleport
