    connection = nil
}

_0xa299._0xb8d0:AddToggle("Click to Teleport", false, function(Value)
    _0xa299._0xCTTP.enabled = Value
    
    if Value then
        if _0xa299._0xCTTP.connection then
            _0xa299._0xCTTP.connection:Disconnect()
        end
        
        _0xa299._0xCTTP.connection = _0xa299._0xb9e0.InputBegan:Connect(function(input, gameProcessed)
            if gameProcessed then return end
            if not _0xa299._0xCTTP.enabled then return end
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
            
            local char = _0xa299._0x396d.Character
            if not char or not char:FindFirstChild("HumanoidRootPart") then return end
            
            local camera = workspace.CurrentCamera
            local mousePos = _0xa299._0xb9e0:GetMouseLocation()
            local ray = camera:ViewportPointToRay(mousePos.X, mousePos.Y)
            
            local raycastParams = RaycastParams.new()
            raycastParams.FilterType = Enum.RaycastFilterType.Exclude
            raycastParams.FilterDescendantsInstances = {char}
            
            local result = workspace:Raycast(ray.Origin, ray.Direction * 5000, raycastParams)
            
            if result then
                local targetPos = result.Position + Vector3.new(0, 3, 0)
                char.HumanoidRootPart.CFrame = CFrame.new(targetPos)
            end
        end)
        
        _0xa299._0x8545:Notify("Teleport", "Click to Teleport enabled", 3, "check")
    else
        if _0xa299._0xCTTP.connection then
            _0xa299._0xCTTP.connection:Disconnect()
            _0xa299._0xCTTP.connection = nil
        end
        _0xa299._0x8545:Notify("Teleport", "Click to Teleport disabled", 3, "info")
    end
end, {Type = "info", Text = "Left click to teleport to mouse location"})

