_0xa299._0xGetNearestPlayer = function()
    local localPlayer = _0xa299._0x396d
    local localChar = localPlayer.Character
    if not localChar then return nil, 0 end
    local localRoot = localChar:FindFirstChild("HumanoidRootPart")
    if not localRoot then return nil, 0 end

    local nearestPlayer = nil
    local nearestDist = math.huge

    for _, player in ipairs(_0xa299._0x71bb:GetPlayers()) do
        if player ~= localPlayer then
            -- Check if should ignore this player
            local shouldIgnore = false
            
            -- Ignore Village (same team)
            if _0xa299._0xPROXData.ignoreVillage and _0xa299._0xProxIsSameTeam(player) then
                shouldIgnore = true
            end
            
            -- Ignore specific users
            if _0xa299._0xProxIsIgnoredUser(player.Name) then
                shouldIgnore = true
            end
            
            if not shouldIgnore then
                local char = player.Character
                if char then
                    local root = char:FindFirstChild("HumanoidRootPart")
                    if root then
                        local dist = (root.Position - localRoot.Position).Magnitude
                        if dist < nearestDist then
                            nearestDist = dist
                            nearestPlayer = player
                        end
                    end
                end
            end
        end
    end

    return nearestPlayer, nearestDist
end

