-- Lifeforce Kick Protection: 1s watchdog. Reads LifeForce like the Unwipe
-- method does (DataFunction:InvokeServer("GetData")). Only acts while a
-- farm is running, reuses the panic flag so existing farms pause, then
-- waits until the player leaves combat before kicking.
task.spawn(function()
    local function getLifeForcePercent()
        local ok, data = pcall(function()
            return _0xa299._0xe08d:WaitForChild("Events"):WaitForChild("DataFunction"):InvokeServer("GetData")
        end)
        if not ok or type(data) ~= "table" then return nil end

        local current = tonumber(data["LifeForce"])
        local maxLf   = tonumber(data["MaxLifeForce"]) or tonumber(data["LifeForceMax"])
        if not current then return nil end
        if maxLf and maxLf > 0 then
            return (current / maxLf) * 100
        end
        -- Fall back to raw value if no max is provided by the server
        return current
    end

    while true do
        task.wait(1)

        if not _0xa299._0xLFKP.enabled then
            _0xa299._0xLFKP.isKicking = false
            _0xa299._0xLFKP.notified = false
            -- Pause watchdog while disabled; nothing to do
        else
            local isFarming = false
            pcall(function() isFarming = _0xa299._0xAnyFarmRunning() end)

            if isFarming and not _0xa299._0xLFKP.isKicking then
                local pct = getLifeForcePercent()
                local threshold = _0xa299._0xLFKP.threshold or 30
                if type(threshold) ~= "number" then threshold = 30 end

                if pct and pct < threshold then
                    _0xa299._0xLFKP.isKicking = true
                    _0xa299._0xLFKP.notified = false

                    pcall(function()
                        _0xa299._0x8545:Notify(
                            "Security",
                            "Lifeforce below " .. tostring(threshold) .. "% - Pausing farm, waiting for combat to end",
                            4,
                            "warning"
                        )
                    end)
                end
            end

            -- While waiting to kick, keep the panic flag set so all farms
            -- stay paused, even if the HP-based panic path tries to clear it
            -- on a heartbeat.
            if _0xa299._0xLFKP.isKicking then
                pcall(function()
                    _0xa299._0x49e1.isPanicking = true
                end)
            end

            if _0xa299._0xLFKP.isKicking then
                local combatTimer = nil
                pcall(function()
                    combatTimer = _0xa299._0xGetCombatTimer(_0xa299._0x396d)
                end)

                -- Out of combat when timer is nil or <= 0
                local inCombat = combatTimer and combatTimer > 0

                if not inCombat then
                    if not _0xa299._0xLFKP.notified then
                        _0xa299._0xLFKP.notified = true
                        pcall(function()
                            _0xa299._0x8545:Notify(
                                "Security",
                                "Out of combat - Kicking (Lifeforce below threshold)",
                                3,
                                "error"
                            )
                        end)
                    end
                    local threshold = _0xa299._0xLFKP.threshold or 30
                    pcall(function()
                        _0xa299._0x396d:Kick("[Kyo] Lifeforce Below " .. tostring(threshold))
                    end)
                    -- Kick is a no-return path, but guard anyway
                    return
                end
            end
        end
    end
end)

-- While a lifeforce-kick is pending, actively halt the running farms and pin
