-- Scans all player entries in PlayerList.List for the selected ranks.
-- Rank text is in the format "- Jonin -" inside a TextLabel called "Rank"
-- under each player template. Returns the rank string if found, nil otherwise.
function _0xa299._0x5d82()
    local selectedRanks = _0xa299._0xRNKS and _0xa299._0xRNKS.selectedRanks or {}
    if type(selectedRanks) ~= "table" then selectedRanks = {} end

    -- Build a set of selected rank names for fast lookup
    local rankSet = {}
    for _, rankName in pairs(selectedRanks) do
        rankSet[rankName] = true
    end

    if next(rankSet) == nil then return nil end

    local playerGui = _0xa299._0x396d:FindFirstChild("PlayerGui")
    if not playerGui then return nil end

    local clientGui = playerGui:FindFirstChild("ClientGui")
    if not clientGui then return nil end

    local mainframe = clientGui:FindFirstChild("Mainframe")
    if not mainframe then return nil end

    local playerList = mainframe:FindFirstChild("PlayerList")
    if not playerList then return nil end

    local list = playerList:FindFirstChild("List")
    if not list then return nil end

    for _, template in ipairs(list:GetChildren()) do
        local rankLabel = template:FindFirstChild("Rank")
        if rankLabel then
            local text = ""
            pcall(function() text = rankLabel.Text or "" end)
            -- Extract rank from format "- Jonin -"
            local extractedRank = text:match("%-%s*(.-)%s*%-")
            if extractedRank and extractedRank ~= "" then
                if rankSet[extractedRank] then
                    return extractedRank
                end
            end
        end
    end

    return nil
end

-- Performs the server hop cycle: check current server, hop if no match,
-- then keep hopping on PlayerAdded until a matching rank is found.
function _0xa299._0x6a4f()
    if _0xa299._0xRNKS.hopping then return end
    _0xa299._0xRNKS.hopping = true

    -- Disconnect previous listener if any
    if _0xa299._0xRNKS.connection then
        pcall(function() _0xa299._0xRNKS.connection:Disconnect() end)
        _0xa299._0xRNKS.connection = nil
    end

    -- Initial check (might already be in a valid server after a hop)
    local found = _0xa299._0x5d82()
    if found then
        _0xa299._0x8545:Notify("Rank Hop", "Found " .. found .. " - Staying in this server", 4, "check")
        _0xa299._0xRNKS.enabled = false
        _0xa299._0xRNKS.hopping = false
        return
    end

    -- No match found - start server hopping
    _0xa299._0x8545:Notify("Rank Hop", "No matching ranks, server hopping", 3, "warning")
    _0xa299._0xb5ef()

    -- After hopping, listen for new players in the next server
    -- (the hop itself is async; we check on each PlayerAdded)
    _0xa299._0xRNKS.connection = _0xa299._0x71bb.PlayerAdded:Connect(function(player)
        if not _0xa299._0xRNKS.enabled then return end
        task.wait(3) -- Wait for PlayerList UI to populate

        local foundRank = _0xa299._0x5d82()
        if foundRank then
            _0xa299._0x8545:Notify("Rank Hop", "Found " .. foundRank .. " - Staying in this server", 4, "check")
            _0xa299._0xRNKS.enabled = false
            _0xa299._0xRNKS.hopping = false
            if _0xa299._0xRNKS.connection then
                pcall(function() _0xa299._0xRNKS.connection:Disconnect() end)
                _0xa299._0xRNKS.connection = nil
            end
        else
            -- Still no match after player joined, keep watching
            -- If we've waited a while with no match, hop again
            _0xa299._0x8545:Notify("Rank Hop", "No matching ranks yet, server hopping again", 3, "warning")
            _0xa299._0xRNKS.hopping = false
            task.spawn(function()
                task.wait(2)
                if _0xa299._0xRNKS.enabled then
                    _0xa299._0x6a4f()
                end
            end)
        end
    end)
end

