-- Helper function to convert user input to Enum.KeyCode
function _0xa299._0xe980(input)
    if not input or input == "" then return nil end
    
    -- Number to word mapping
    local numberMap = {
        ["0"] = "Zero", ["1"] = "One", ["2"] = "Two", ["3"] = "Three", ["4"] = "Four",
        ["5"] = "Five", ["6"] = "Six", ["7"] = "Seven", ["8"] = "Eight", ["9"] = "Nine"
    }
    
    -- Convert input
    local keyName = input
    if numberMap[input] then
        keyName = numberMap[input]
    else
        -- Capitalize first letter for single letters (t -> T)
        keyName = input:sub(1,1):upper() .. input:sub(2):lower()
    end
    
    -- Try to get the KeyCode
    local success, keyCode = pcall(function()
        return Enum.KeyCode[keyName]
    end)
    
    if success and keyCode then
        return keyCode
    end
    
    -- Fallback: try original input as-is
    success, keyCode = pcall(function()
        return Enum.KeyCode[input]
    end)
    
    return success and keyCode or nil
end

