_0xa299._0xHLWNCratosDangerAnim = "rbxassetid://6999923160"   -- Cratos Spin
_0xa299._0xHLWNCratosDangerTime = 0.3
_0xa299._0xHLWNCratosDodge = -10

-- Is this NPC on the user's "Avoid Killing" list? Checked in every place that
