        cfgKey        = "Barbarit The Rose",
        halloweenName = "Barbarit The Hallowed",
        invalidName   = "Barbarit The Rose",
        label         = "Barbarit",
        offset        = 10.5,
    },
    ["Hallowed Tairock"] = {
        cfgKey        = "Tairock",
        halloweenName = "Hallowed Tairock",
        label         = "Tairock",
    },
    ["Hallowed Chakra Knight"] = {
        cfgKey        = "Chakra Knight",
        halloweenName = "Hallowed Chakra Knight",
        label         = "Chakra Knight",
    },
    ["Hallowed Lavarossa"] = {
