    local now = _0xa299._0xHLWNCandyCount()
    local since = now - (S.candyLastSent or now)
    local session = now - (S.candyAtStart or now)

    if since <= 0 and not reason then return false end
    S.candyLastSent = now

    task.spawn(function()
        local body = "**Candy:**\n```" .. now .. " total"
        if since > 0 then body = body .. "   (+" .. since .. " since last report)" end
        if session > 0 then body = body .. "\n+" .. session .. " this session" end
        body = body .. "```\n**Account Name:**\n```" .. _0xa299._0x396d.Name .. "```"
            .. "\n\n**Status:** " .. (reason or "Farming")
            .. "\n**Time:** " .. os.date("%H:%M:%S")

