function _0xa299._0xPlayerNearPoint(point, range)
    range = range or 50
    local pointPart = point:IsA("BasePart") and point or (point:IsA("Model") and (point.PrimaryPart or point:FindFirstChildWhichIsA("BasePart")))
    if not pointPart then return false end
    
    for _, p in ipairs(_0xa299._0x71bb:GetPlayers()) do
        if p ~= _0xa299._0x396d and p.Character then
            local pHrp = p.Character:FindFirstChild("HumanoidRootPart")
