                end
            end
        end
    end
    return false
end

function _0xa299._0x052d(point, range)
    range = range or 200
    local pointPart = point:IsA("BasePart") and point or (point:IsA("Model") and (point.PrimaryPart or point:FindFirstChildWhichIsA("BasePart")))
    if not pointPart then return false end
    
    local snowstorms = workspace:FindFirstChild("Snowstorms")
    if not snowstorms then return false end
    
    for _, storm in pairs(snowstorms:GetChildren()) do
        if storm.Name == "Snowstorm" then
            local enabled = storm:GetAttribute("Enabled")
            if enabled == true then
                -- Path: Snowstorm.Storm.Model.Part
                local stormPart = nil
                local stormFolder = storm:FindFirstChild("Storm")
                if stormFolder then
                    local model = stormFolder:FindFirstChild("Model")
                    if model then
                        stormPart = model:FindFirstChild("Part") or model:FindFirstChildWhichIsA("BasePart")
                    end
                end
                
                if stormPart then
                    local distance = (stormPart.Position - pointPart.Position).Magnitude
                    if distance <= range then
                        return true
                    end
                end
            end
        end
    end
    return false
end

function _0xa299._0xd574()
