-- Find the CURRENT boss method's boss. Returns boss, humanoid, isInvalidBoss.
--
-- Driven by _0xHLWNBossMethods rather than hardcoded to Barbarit, so Tairock,
-- Chakra Knight and Lavarossa all use this same finder.
--
-- Only the HALLOWEEN name is accepted. The base boss and the other seasonal
-- variants are deliberately not farmed by these methods.
function _0xa299._0xf63f()
    local m = _0xa299._0xHLWNBossCfg()
    if not m then return nil, nil, false end

    -- Wrong boss in the arena. Only Barbarit has one: "Barbarit The Rose"
    -- spawns there when no event variant is up.
    if m.invalidName then
        local invalidBoss = workspace:FindFirstChild(m.invalidName)
        if invalidBoss then
            local humanoid = invalidBoss:FindFirstChildOfClass("Humanoid")
            if humanoid and humanoid.Health > 0 then
                return nil, nil, true -- Return invalid flag
            end
        end
    end

    local boss = workspace:FindFirstChild(m.halloweenName)
    if boss then
        local humanoid = boss:FindFirstChildOfClass("Humanoid")
        local bossHrp = boss:FindFirstChild("HumanoidRootPart") or boss:FindFirstChild("Torso")
        if humanoid and humanoid.Health > 0 and bossHrp then
            -- Within 400 studs of its spawn, same as the boss farm. Bosses with
            -- no spawnPosition in the config (Tairock, Chakra Knight) have no
            -- arena to be near, so the distance test is SKIPPED rather than
            -- measured against a nil and rejecting every boss forever.
            --
            -- _0xHLWNBossSpawn, NOT _0xHLWNBossAnchor: that one now prefers the
            -- live boss position, which would make this ask whether the boss is
            -- within 400 studs of itself.
            local anchor = _0xa299._0xHLWNBossSpawn()
            if not anchor then
                return boss, humanoid, false
            end
            if (bossHrp.Position - anchor).Magnitude <= 400 then
                return boss, humanoid, false
            end
        end
    end
    return nil, nil, false
end

function _0xa299._0xb02e(position, range)
    local npcs = {}
    -- Use tracked NPCs table if available, otherwise fall back to workspace scan
    if _0xa299._0xb81e.enabled and _0xa299._0xb81e.trackedNPCs then
        for obj, data in pairs(_0xa299._0xb81e.trackedNPCs) do
            if obj and obj:IsDescendantOf(workspace) and data.humanoid and data.hrp and data.humanoid.Health > 0 then
                local distance = (data.hrp.Position - position).Magnitude
                if distance <= range and not _0xa299._0xHLWNAvoided(obj.Name) then
                    table.insert(npcs, {npc = data.npc, humanoid = data.humanoid, hrp = data.hrp, distance = distance})
                end
            else
                _0xa299._0xb81e.trackedNPCs[obj] = nil
            end
        end
    else
        for _, obj in pairs(workspace:GetChildren()) do
            if obj:IsA("Model") and obj ~= _0xa299._0x396d.Character
               and string.find(obj.Name, "Hallowed")
               and not _0xa299._0xHLWNAvoided(obj.Name) then
                local humanoid = obj:FindFirstChildOfClass("Humanoid")
                local npcHrp = obj:FindFirstChild("HumanoidRootPart") or obj:FindFirstChild("Torso")
                if humanoid and npcHrp and humanoid.Health > 0 then
                    local isPlayer = false
                    for _, p in ipairs(_0xa299._0x71bb:GetPlayers()) do
                        if p.Character == obj then
                            isPlayer = true
                            break
                        end
                    end
                    if not isPlayer then
                        local distance = (npcHrp.Position - position).Magnitude
                        if distance <= range then
                            table.insert(npcs, {npc = obj, humanoid = humanoid, hrp = npcHrp, distance = distance})
                        end
                    end
                end
            end
        end
    end
    table.sort(npcs, function(a, b) return a.distance < b.distance end)
    return npcs
end

