function _0xa299._0xGetChakraPoints()
    local points = {}
    local chakraPoints = workspace:FindFirstChild("ChakraPoints")
    if chakraPoints then
        for _, child in pairs(chakraPoints:GetChildren()) do
            if child.Name == "ChakraPoint" then
                local pointName = child:FindFirstChild("PointName")
                if pointName and pointName:IsA("StringValue") and pointName.Value ~= "" then
                    table.insert(points, pointName.Value)
                end
            end
        end
    end
    if #points == 0 then
        table.insert(points, "None Found")
    end
    return points
end

function _0xa299._0xGetPlayerAge()
    local age = 0
    pcall(function()
        local ageGui = _0xa299._0x396d.PlayerGui:FindFirstChild("ClientGui")
        if ageGui then
            local mainframe = ageGui:FindFirstChild("Mainframe")
            if mainframe then
                local loadout = mainframe:FindFirstChild("Loadout")
                if loadout then
                    local rightFrame = loadout:FindFirstChild("RightFrame")
                    if rightFrame then
                        local ageLabel = rightFrame:FindFirstChild("Age")
                        if ageLabel and ageLabel:IsA("TextLabel") then
                            local text = ageLabel.Text
                            local numStr = text:match("%d+")
                            if numStr then
                                age = tonumber(numStr) or 0
                            end
                        end
                    end
                end
            end
        end
    end)
    return age
end

