function _0xa299._0xAutoProgFindChakraPointModel(pointName)
    local chakraPoints = workspace:FindFirstChild("ChakraPoints")
    if chakraPoints then
        for _, child in pairs(chakraPoints:GetChildren()) do
            if child.Name == "ChakraPoint" then
                local pName = child:FindFirstChild("PointName")
                if pName and pName:IsA("StringValue") and pName.Value == pointName then
                    return child
