---------------------------------------------------------------------
-- CHAKRA POINTS - destroy and leave without executor-specific calls
--
-- The old path clicked the real buttons by firing their signal connections:
--     for _, c in ipairs(getconnections(button.Activated))         do c:Fire() end
--     for _, c in ipairs(getconnections(button.MouseButton1Click))  do c:Fire() end
--     ... and MouseButton1Down / TouchTap
-- for BOTH DestroyPoint and Leave. `getconnections` is not portable: outside
-- Volt the Fire either does not invoke the handler or invokes it without its
-- upvalues. That is bad for the destroy and far worse for the LEAVE, because
-- the Leave handler is what unanchors the character, clears v.Occupied,
-- restores Humanoid.AutoRotate and hides the Rest menu - so when it silently
-- does nothing you are left anchored and stuck in the menu, which is exactly
-- the reported symptom.
--
-- Each handler's only server-side effect is one InvokeServer
-- (client LocalScript 7075 and 6561):
--     DestroyPoint -> DataFunction:InvokeServer("DestroyChakraPoint", point)
--     Leave        -> DataFunction:InvokeServer("ChakraPointStand",   point)
-- Both return a value the handler tests. Everything else those handlers do is
-- client-side presentation, reproduced here with plain Roblox APIs.
--
-- The Leave handler also fires UpdateSettings (a 22-field table) and
-- SaveSlots. Those are deliberately NOT sent: we changed neither the settings
-- panel nor the keybinds, and hand-assembling a settings payload is exactly
-- the class of remote that got this script banned before.
---------------------------------------------------------------------

-- The point the game itself thinks we are sitting at, if it knows.
function _0xa299._0xChakraPointCurrent()
    local p
    pcall(function()
        local env = getsenv(_0xa299._0x396d.PlayerGui.ClientGui.LocalScript)
        p = env and env.v and env.v.CurrentChakraPoint
    end)
    if typeof(p) == "Instance" and p.Parent then return p end
    return nil
end

function _0xa299._0xDestroyChakraPoint(pointModel)
    local point = _0xa299._0xChakraPointCurrent() or pointModel
    if not point then return false end
    local ok, result = pcall(function()
        return _0xa299._0xe08d:WaitForChild("Events"):WaitForChild("DataFunction")
            :InvokeServer("DestroyChakraPoint", point)
    end)
    -- The game treats a falsy return as "age/condition not met".
    return (ok and result) and true or false
end

-- Stand up and put the UI back. The cleanup runs even when the remote fails:
-- being left anchored inside the menu is the worst outcome here, so it must
-- not be conditional on the server answering.
function _0xa299._0xLeaveChakraPoint(pointModel)
    local point = _0xa299._0xChakraPointCurrent() or pointModel
    local sent = false
    if point then
        sent = pcall(function()
            _0xa299._0xe08d:WaitForChild("Events"):WaitForChild("DataFunction")
                :InvokeServer("ChakraPointStand", point)
        end)
    end

    pcall(function()
        local char = _0xa299._0x396d.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hrp then hrp.Anchored = false end
        if hum then
            hum.AutoRotate = true
            pcall(function()
                local GM = require(_0xa299._0xe08d:WaitForChild("GameManager"))
                GM:stopAnimation("SittingCrossLegged", hum)
            end)
        end

        local env = getsenv(_0xa299._0x396d.PlayerGui.ClientGui.LocalScript)
        local v = env and env.v
        if v then
            v.Occupied = false
            v.CurrentChakraPoint = nil
            v.ChangingPage = false
            v.CurrentPage = ""
        end

        local clientGui = _0xa299._0x396d.PlayerGui:FindFirstChild("ClientGui")
        local mf = clientGui and clientGui:FindFirstChild("Mainframe")
        if mf then
            local rest = mf:FindFirstChild("Rest")
            if rest then
                rest.Visible = false
                local bd = rest:FindFirstChild("BackDrop")
                if bd then bd.BackgroundTransparency = 1 end
            end
            for _, n in ipairs({ "Loadout", "Ryo", "Acumen" }) do
                local o = mf:FindFirstChild(n)
                if o then o.Visible = true end
            end
            local lo = mf:FindFirstChild("Loadout")
            local hud = lo and lo:FindFirstChild("HUD")
            if hud then hud.Visible = true end
            -- Embers is shown only when we have any, which is what the game does.
            local embers = mf:FindFirstChild("Embers")
            if embers then
                local data = _0xa299._0xLocalData()
                embers.Visible = (tonumber(data and data.Embers) or 0) > 0
            end
        end

        local blur = game:GetService("Lighting"):FindFirstChild("PointBlur")
        if blur then blur:Destroy() end

        -- The menu disables these on the way in.
        local cps = workspace:FindFirstChild("ChakraPoints")
        if cps then
            for _, d in ipairs(cps:GetDescendants()) do
                if d:IsA("BillboardGui") then d.Enabled = true end
            end
        end
    end)

    return sent
end

function _0xa299._0xAutoProgBreakChakraPoint(pointName, runId)
