                _0xa299._0xProgTreeChecked = 0

                -- Re-arm the wipe. It latches permanently on a CONFIRMED wipe
                -- so a successful one cannot re-fire, but the whole point is a
                -- repeating loop - build up, wipe at the age, build up again -
                -- so a new life has to be allowed to wipe in its turn.
                _0xa299._0xProgBuild.wiped = false
                _0xa299._0xProgBuild.wipeAt = 0

                _0xa299._0xAutoProgDebug("CYCLE_RESTART", "post-wipe")
                _0xa299._0x8545:Notify("Auto Prog", "New life - restarting cycle", 3, "info")
                task.wait(2)
                joinVillage()
            end

            -- Weapon and exam up FRONT, before the quests - a rebuilt life is
            -- unarmed and unranked, and plenty of the quests want a weapon.
            -- Both are rate-limited and no-op when already done.
            if _0xa299._0xProgBuild.autoWeapon then
                pcall(_0xa299._0xProgBuyWeapon)
            end
            pcall(_0xa299._0xProgGeninExam)
            
            -- Decided once per cycle, after the buy above has had its go, so
            -- it sees the Ryo as it actually stands.
            local questOrder = _0xa299._0xProgQuestOrder()

            _0xa299._0xAutoProgDebug("QUEST_LOOP", "Starting " .. #questOrder .. " quests")
            _0xa299._0xAutoProg.alreadyBrokePoint = false
            -- Fresh age cycle: anything the board was not offering last time
            -- gets a clean chance, since an age up re-rolls everything anyway.
            _0xa299._0xAutoProg.deferredQuests = {}
            _0xa299._0xAutoProg.lastDeferredRetry = tick()
            _0xa299._0xAutoProgEquipWeapon()
            for i, questName in ipairs(questOrder) do
                if not _0xa299._0xAutoProgAlive(myRun) then break end

                if not _0xa299._0xAutoProgWaitForSafety(myRun) then break end

                _0xa299._0xAutoProg.currentQuestIndex = i
                _0xa299._0xAutoProgUpdateGUI("autoprog_quest", questName, "(" .. i .. "/" .. #questOrder .. ")")

                _0xa299._0xAutoProgExecuteQuest(questName)

                -- Try the weapon again after EVERY quest, not just once at the
                -- top of the cycle. A quest is where the Ryo comes from, so
                -- this is the moment it may have become affordable - and the
                -- rest of the quests go better armed. Gated to one look every
                -- few seconds and a no-op once armed.
                if _0xa299._0xProgBuild.autoWeapon then
                    pcall(_0xa299._0xProgBuyWeapon)
                end

                -- The board was not offering this one. Do not write it off -
                -- boards re-roll, so park it and come back once the quests
                -- that CAN be done are done.
                if _0xa299._0xMissionUnavailable == questName
                   and not table.find(_0xa299._0xAutoProg.deferredQuests, questName) then
                    table.insert(_0xa299._0xAutoProg.deferredQuests, questName)
                    _0xa299._0xAutoProgDebug("DEFERRED", questName .. " not on board")
                end

                if not _0xa299._0xAutoProgAlive(myRun) then break end
                
                if i < #questOrder then
                    _0xa299._0xAutoProgDebug("COOLDOWN", "10s before next quest")

                    -- Parked at the safespot for 10 s, so let the game animate
                    -- normally rather than leaving whatever the quest left
                    -- running. This is the same restore the boss farm does.
                    _0xa299._0xAutoProgRestoreAnim()

                    if _0xa299._0x396d.Character and _0xa299._0x396d.Character:FindFirstChild("HumanoidRootPart") then
                        _0xa299._0x396d.Character.HumanoidRootPart.CFrame = _0xa299._0xdde4()
                    end
                    
                    if _0xa299._0x220a.spoofLoadingIn then
                        _0xa299._0x220a.applySpoofProtection()
                    end
                    
                    for countdown = 10, 1, -1 do
                        if not _0xa299._0xAutoProgAlive(myRun) then break end
                        _0xa299._0xAutoProgUpdateGUI("autoprog_cooldown", tostring(countdown))

                        -- Keep watching while we wait out the gap. The Ryo from
                        -- the quest that just finished can land a moment late.
                        if _0xa299._0xProgBuild.autoWeapon then
                            pcall(_0xa299._0xProgBuyWeapon)
                        end
                        
                        if _0xa299._0x396d.Character and _0xa299._0x396d.Character:FindFirstChild("HumanoidRootPart") then
                            _0xa299._0x396d.Character.HumanoidRootPart.CFrame = _0xa299._0xdde4()
                        end
                        
                        if _0xa299._0x220a.spoofLoadingIn then
                            _0xa299._0x220a.applySpoofProtection()
                        end
                        
                        task.wait(1)
                    end
                    
                    if _0xa299._0x220a.spoofLoadingIn then
                        _0xa299._0x220a.removeSpoofProtection()
                    end
                end
            end
            
            if not _0xa299._0xAutoProgAlive(myRun) then break end
            
            _0xa299._0xAutoProg.currentAge = _0xa299._0xGetPlayerAge()
            _0xa299._0xAutoProgDebug("WAITING_AGE", "Current age: " .. _0xa299._0xAutoProg.currentAge)
            _0xa299._0x8545:Notify("Auto Prog", "All quests done, waiting on age up (Current: " .. _0xa299._0xAutoProg.currentAge .. ")", 3, "check")

            -- BUILD MAXING. Done here because this is the dead window: the
            -- quests for this age are finished and we are about to sit at the
            -- safespot doing nothing until the age ticks over. Both are
            -- internally rate-limited and latched, so running them on every
            -- pass through here is cheap.
            -- Weapon and exam are handled at the TOP of the cycle now, before
            -- the quests, so they are not repeated here. The tree pass stays:
            -- this is the idle window it wants, and it needs the shards the
            -- point breaking below produces.
            pcall(_0xa299._0xProgSkillTreePass)
            if _0xa299._0xProgBuild.autoWeapon then
                pcall(_0xa299._0xProgBuyWeapon)
            end

            if _0xa299._0x396d.Character and _0xa299._0x396d.Character:FindFirstChild("HumanoidRootPart") then
                _0xa299._0x396d.Character.HumanoidRootPart.CFrame = _0xa299._0xdde4()
            end
            
            local ageChanged = false
            if _0xa299._0x220a.spoofLoadingIn then
                _0xa299._0x220a.applySpoofProtection()
            end
            
            while _0xa299._0xAutoProgAlive(myRun) and not ageChanged do
                -- A threat arriving mid-farm drops the farm FIRST, so the pin
                -- below puts us back at the safespot in the same pass instead
                -- of a second later.
                if _0xa299._0xProgRyoRunning() and not _0xa299._0xAutoProgCheckSafety() then
                    _0xa299._0xProgRyoStop()
                end

                -- Hold back the pin and the anchor while the Ryo farm has the
                -- body. Pinning here would teleport it off the crop it is
                -- standing on every second, and the spoof anchor would stop it
                -- moving at all.
                if not _0xa299._0xProgRyoRunning() then
                    if _0xa299._0x396d.Character and _0xa299._0x396d.Character:FindFirstChild("HumanoidRootPart") then
                        _0xa299._0x396d.Character.HumanoidRootPart.CFrame = _0xa299._0xdde4()
                    end

                    if _0xa299._0x220a.spoofLoadingIn then
                        _0xa299._0x220a.applySpoofProtection()
                    end
                end
                
                local ryo = _0xa299._0xAutoProgGetRyo()
                local newAge = _0xa299._0xGetPlayerAge()
                -- Say when it is farming rather than just sitting, or the
                -- status reads "Waiting for Age Up" the whole time and there is
                -- no way to tell the toggle is doing anything.
                _0xa299._0xAutoProgUpdateGUI("autoprog_waiting_age",
                    tostring(newAge) .. " | Ryo: " .. tostring(ryo)
                    .. (_0xa299._0xProgRyoRunning() and " | Farming" or ""))
                
                if ryo >= 100 and #_0xa299._0xAutoProg.selectedPoints > 0 then
                    if _0xa299._0x220a.spoofLoadingIn then
                        _0xa299._0x220a.removeSpoofProtection()
                    end
                    _0xa299._0xAutoProgCheckAndBreakPoints(myRun)
                    if _0xa299._0x220a.spoofLoadingIn then
                        _0xa299._0x220a.applySpoofProtection()
                    end

                end

                -- WIPE AT AGE, checked EVERY pass rather than only on the
                -- age-up transition.
                --
                -- That was the bug behind "I am 28 with a wipe age of 25 and
                -- nothing happens": it only ever ran inside the
                -- "newAge > currentAge" branch, so being ALREADY past it did
                -- nothing. Enabling the toggle at 28, or having a wipe refused
                -- once, meant waiting for the next age up - and if that one
                -- also got swallowed, forever. A plain >= test on every pass
                -- cannot miss, and _0xProgWipe has its own cooldown so this
                -- does not spam.
                if _0xa299._0xProgBuild.wipeAt25
                   and newAge >= _0xa299._0xProgBuild.wipeAge then
                    task.spawn(function()
                        pcall(_0xa299._0xProgWipe)
                    end)
                end

                -- TREE PASS, every time round the wait - not inside the point
                -- break above.
                --
                -- It has to be unconditional for two reasons. Breaking a point
                -- is where Chakra Shards come from and a shard gates the first
                -- skill of three of the four paths, so a shard earned in the
                -- branch above has to be spendable in the same age rather than
                -- the next. And the item fetches have a two minute retry on
                -- them, which only ever elapses if something keeps calling
                -- them - sitting inside "ryo >= 100 and points selected" meant
                -- a run with no points chosen never retried a missing bell at
                -- all.
                --
                -- Internally rate-limited to one pass per 30s, so this costs
                -- a table lookup on most iterations.
                pcall(_0xa299._0xProgSkillTreePass)

                -- Same reasoning for the weapon: breaking a point above is a
                -- Ryo sink, but quest payouts and drops land here too, and this
                -- loop is where the run spends most of its time. Its own gate
                -- keeps it to one look every few seconds.
                if _0xa299._0xProgBuild.autoWeapon then
                    pcall(_0xa299._0xProgBuyWeapon)
                end

                -- Go back for the missions the board was not offering.
                --
                -- Everything that COULD be done this cycle has been, so this
                -- is the right point to retry: boards re-roll their tiles
                -- (verified - the same village's board went from no Cratos at
                -- all to three Cratos tiles within minutes), so one that had
                -- nothing for us may well have it now. An age up resets the
                -- list, since the whole cycle starts over.
                if #_0xa299._0xAutoProg.deferredQuests > 0
                   and (tick() - _0xa299._0xAutoProg.lastDeferredRetry) >= _0xa299._0xAutoProgRetryEvery then
                    _0xa299._0xAutoProg.lastDeferredRetry = tick()
                    _0xa299._0xProgRyoStop()
                    _0xa299._0xAutoProgDebug("RETRY_DEFERRED",
                        table.concat(_0xa299._0xAutoProg.deferredQuests, ", "))

                    if _0xa299._0x220a.spoofLoadingIn then
                        _0xa299._0x220a.removeSpoofProtection()
                    end

                    local stillMissing = {}
                    for _, deferredName in ipairs(_0xa299._0xAutoProg.deferredQuests) do
                        if not _0xa299._0xAutoProgAlive(myRun) then break end
                        if not _0xa299._0xAutoProgWaitForSafety(myRun) then break end
                        _0xa299._0xAutoProgUpdateGUI("autoprog_quest", deferredName, "(retry)")
                        _0xa299._0xAutoProgExecuteQuest(deferredName)
                        if _0xa299._0xMissionUnavailable == deferredName then
                            table.insert(stillMissing, deferredName)
                        end
                    end
                    _0xa299._0xAutoProg.deferredQuests = stillMissing

                    -- Back to the safespot and normal animations afterwards;
                    -- the retry ran real quests.
                    _0xa299._0xAutoProgRestoreAnim()
                    if _0xa299._0x396d.Character and _0xa299._0x396d.Character:FindFirstChild("HumanoidRootPart") then
                        _0xa299._0x396d.Character.HumanoidRootPart.CFrame = _0xa299._0xdde4()
                    end

                    if _0xa299._0x220a.spoofLoadingIn then
                        _0xa299._0x220a.applySpoofProtection()
                    end
                end
                
                -- Restart requested (a confirmed wipe), or the age went
                -- BACKWARDS - which only happens on a reincarnation. Either
                -- way this life is over, so leave the wait loop; the cycle
                -- restart at the top of the outer loop handles the rest.
                --
                -- The age-drop test is a backstop: if a wipe ever happens
                -- without restartCycle being set (a manual wipe, Auto Wipe
                -- running alongside this), the loop would otherwise spin here
                -- forever waiting for an age it already passed.
                if _0xa299._0xAutoProg.restartCycle
                   or (newAge and newAge < _0xa299._0xAutoProg.currentAge) then
                    _0xa299._0xAutoProg.restartCycle = true
                    _0xa299._0xAutoProgDebug("WIPE_DETECTED",
                        tostring(_0xa299._0xAutoProg.currentAge) .. " -> " .. tostring(newAge))
                    ageChanged = true
                    break
                end

                if newAge > _0xa299._0xAutoProg.currentAge then
                    ageChanged = true
                    _0xa299._0xAutoProgDebug("AGE_UP", _0xa299._0xAutoProg.currentAge .. " -> " .. newAge)

                    -- A new age is a fresh shot at the exam.
                    _0xa299._0xProgBuild.examTried = false
                    _0xa299._0xAutoProgUpdateGUI("autoprog_age_up", tostring(_0xa299._0xAutoProg.currentAge), tostring(newAge))
                    _0xa299._0x8545:Notify("Auto Prog", "Aged up " .. _0xa299._0xAutoProg.currentAge .. " -> " .. newAge, 3, "check")
                    
                    _0xa299._0xProgHook("Age Up", {
                        "**Aged:**\n```" .. _0xa299._0xAutoProg.currentAge
                            .. " -> " .. newAge .. "```",
                    })
                    
                    _0xa299._0xAutoProg.currentAge = newAge
                    task.wait(2)
                end

                -- Everything that wanted the body has had it. Whatever is left
                -- of this age goes into farming Ryo. No-ops when the toggle is
                -- off, when a farm is already running, or when it is not safe.
                _0xa299._0xProgRyoStart()

                task.wait(1)
            end

            -- Age ticked over, or the life ended. Either way the next pass has
            -- quests to run, so hand the body back.
            _0xa299._0xProgRyoStop()
            
            if _0xa299._0x220a.spoofLoadingIn then
                _0xa299._0x220a.removeSpoofProtection()
            end
        end
        
        _0xa299._0xAutoProgDebug("LOOP_END", nil)
        _0xa299._0xAutoProgUpdateGUI("disable")
    end)
end

function _0xa299._0xStopAutoProg()
    _0xa299._0xAutoProgDebug("STOPPING", nil)
    _0xa299._0xAutoProg.enabled = false
    
    -- Stop any running quest by setting the quest stop flag
    _0xa299._0x62f5 = true
    
    -- Don't task.cancel - let the quest exit naturally via _0x62f5 so its cleanup code runs
    -- (disconnects noclip, stops animations, etc.)
    -- The auto prog loop will also exit since .enabled = false
    --
    -- The connection slot is released IMMEDIATELY, and the delayed cancel
    -- captures the thread it belongs to rather than re-reading the field.
    --
    -- Both halves of that were bugs. _0xStartAutoProg opens with
    -- "if connection then return end", and this used to leave the field set
    -- for five seconds - so toggling Auto Prog off and straight back on
    -- returned instantly and started NOTHING, while .enabled was true and the
    -- GUI sat frozen on whatever it last showed (the quest cooldown counter,
    -- typically). And re-reading the field five seconds later meant that if a
    -- restart HAD got through, the stale timer would cancel the new thread
    -- instead of the old one.
    -- The in-flight quest, if any. _0x62f5 above already told it to unwind; this
    -- is the backstop for one that will not, and it has to be explicit because
    -- the quest no longer shares the loop thread.
    local quest = _0xa299._0xAutoProg.questThread
    _0xa299._0xAutoProg.questThread = nil
    if quest then
        task.delay(8, function()
            if coroutine.status(quest) ~= "dead" then
                pcall(function() task.cancel(quest) end)
            end
        end)
    end

    local stopping = _0xa299._0xAutoProg.connection
    _0xa299._0xAutoProg.connection = nil
    -- Kept where a restart can see it, so _0xStartAutoProg waits this thread
    -- out instead of racing it over _0x62f5 and the status label.
    _0xa299._0xAutoProg.dying = stopping
    task.delay(5, function()
        if stopping then
            pcall(function() task.cancel(stopping) end)
        end
        if _0xa299._0xAutoProg.dying == stopping then
            _0xa299._0xAutoProg.dying = nil
        end
    end)
    
    if _0xa299._0xAutoProg.originalNoFallDamage ~= nil then
        _0xa299._0xa6f6.noFallDamage = _0xa299._0xAutoProg.originalNoFallDamage
        _0xa299._0xAutoProg.originalNoFallDamage = nil
    end
    
    -- Any farm WE started goes with us; one the user turned on stays.
    --
    -- Spawned, not awaited: _0xProgRyoStop blocks until the farm lets go of the
    -- character, and this runs from the toggle callback where that would read as
    -- the UI hanging. Nothing of ours is about to move the body on the way out,
    -- so there is nothing to wait for.
    task.spawn(_0xa299._0xProgRyoStop)

    _0xa299._0xAutoProg.isPanicking = false
    _0xa299._0xAutoProg.lastDebugState = ""
    _0xa299._0xAutoProg.lastDebugReason = ""
    
    if _0xa299._0x220a.spoofLoadingIn then
        _0xa299._0x220a.removeSpoofProtection()
    end
    
    _0xa299._0xAutoProgUpdateGUI("disable")
    if _0xa299._0xdc0f then
        _0xa299._0xdc0f("disable", "", "")
    end
end

_0xa299._0xAutoProg.toggle = _0xa299._0xAPRG:AddToggle("Enable Auto Prog", false, function(Value)
    _0xa299._0xWM.set("FarmProg", Value)
    _0xa299._0xAutoProg.enabled = Value
    if Value then
        -- Fresh run: let the wipe, the exam and every item fetch fire again.
        _0xa299._0xProgBuild.wiped = false
        _0xa299._0xProgBuild.examTried = false
        _0xa299._0xProgItemRetry = {}
        _0xa299._0xProgBuild.lastTreeRun = 0
        _0xa299._0xProgTreeChecked = 0
        _0xa299._0xProgBuild.wipeAt = 0
        _0xa299._0xProgWeaponAt = 0
        _0xa299._0xStartAutoProg()
