function _0xa299._0xLavaFarmStart()
    if _0xa299._0xLAVAF.farming then return end
    
    -- Weapon check first (unless using infinite M1)
    if not _0xa299._0xLAVAF.infiniteM1 then
        if not _0xa299._0x1c3b() then
            _0xa299._0x8545:Notify("Farm", "You need a Weapon for Lava NPC Farm", 3, "error")
            _0xa299._0xLAVAF.enabled = false
            return
