    end

    local function adopt(m)
        S.bossReference = m
        S.bossHrpReference = m:FindFirstChild("HumanoidRootPart") or m:FindFirstChild("Torso")
        S.bossMissingSince = nil
        return m, false
    end

    local found = look()
    if found then return adopt(found) end

    -- Decide WHY it vanished from WHERE WE ARE, not from its last health.
    -- Health was the wrong test: the last reading taken while it was alive is
    -- always above zero, so every kill looked like a streaming hiccup and the
    -- boss was reported alive forever.
    --
    -- If it died under us we are still hovering over its last position (the
    -- farm sits 4-35 studs above the boss). The streaming case only arises
    -- because WE teleported away, and the safespot is thousands of studs from
    -- every arena - so the two are trivially separable by distance.
    local char = _0xa299._0x396d.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local weMovedAway = false
    if hrp and S.bossLastPos then
        weMovedAway = (hrp.Position - S.bossLastPos).Magnitude > _0xa299._0xBossFarAway
    end

    if weMovedAway then
        S.bossMissingSince = S.bossMissingSince or tick()

