end

local function _0xGaaraPos(inst)
    local p
    pcall(function()
        if inst:IsA("BasePart") then p = inst.Position
        elseif inst:IsA("Model") then p = inst:GetPivot().Position end
    end)
    return p
end

-- Name of the boss model we are actually farming, for the exact-match test
-- below. The game renames bosses (`"Farming <name>"`), so this is read off the
-- live model rather than assumed to be "Gaara".
local function _0xGaaraBossName()
    local bossHrp = _0xa299._0x1915 and _0xa299._0x1915.bossHrpReference
    local model = bossHrp and bossHrp.Parent
    return model and model.Name or nil
