        local bossHrp = _0xa299._0x1915 and _0xa299._0x1915.bossHrpReference
        local p = _0xGaaraPos(inst)
        -- Must be in our arena: these names are generic enough that another
        -- player's copy on the far side of the map would otherwise count.
        if p and bossHrp and bossHrp.Parent
           and (p - bossHrp.Position).Magnitude <= _0xa299._0xGaaraNear then
