    -- a roam spot unsafe after it had gone.
    S.storms[inst] = nil
    S.indicators[inst] = nil

    if S.pyramid == inst then
        S.pyramid = nil
        -- Keep the height for a second after it vanishes, as asked.
        S.pyramidUntil = tick() + 1
    elseif S.storm == inst then
        S.storm = nil
        S.storms[inst] = nil
    elseif S.shield == inst then
        -- The shield going away is the real end of the move, so come down
        -- rather than sitting out the rest of the 5 s timer.
        S.shield = nil
        S.shieldUntil = math.min(S.shieldUntil, tick() + 0.4)
    elseif S.coffin == inst then
        S.coffin = nil
        S.coffinUntil = math.min(S.coffinUntil, tick() + 0.4)
