        -- straight to the handler keeps this from drifting out of sync with
        -- the detection rules, and costs nothing: the handler rejects on a
        -- name test before it ever reads a position.
        for _, c in ipairs(container:GetChildren()) do _0xGaaraOnAdded(c) end
    end

    hook(workspace)
    hook(workspace:FindFirstChild("Debris"))

    -- SAND SUSPENSION - the red ring on the ground.
    --
    -- This one cannot be caught by watching for an instance, because the ring
    -- is announced over a remote 0.5 s BEFORE anything spawns. GameManager
    -- ~8613 does, for every player within 500 studs:
    --
    --     DataEvent:FireClient(plr, "circleWarning", groundPos, 0.5, 60)
    --     task.wait(0.5)
    --     t4:startSkill(boss, "Gaara Storm", target, {
    --         ["Sand Suspension"] = true, SpawnCF = groundPos + (0,3.6,0),
    --         Duration = 10 })
    --
