        -- ring cannot stretch the roam out indefinitely.
        local moved = _0xa299._0xGaaraRoamPick(bossHrp)
        if moved then
            R.spot = moved
            R.target = aim(moved)
            R.hpAtSpot = hp          -- fresh baseline at the new spot
            return R.target
        end

        -- Nowhere left to stand. Hovering over the boss beats standing in a
        -- ring, so end the roam and let the farm take positioning back.
        R.doneAt = 0
        R.spot = nil
        R.target = nil
