function _0xa299._0xa382(position, range)
    local nearbyPlayers = {}
    for _, otherPlayer in ipairs(_0xa299._0x71bb:GetPlayers()) do
        if otherPlayer ~= _0xa299._0x396d and otherPlayer.Character then
            local otherHrp = otherPlayer.Character:FindFirstChild("HumanoidRootPart")
            if otherHrp then
                local distance = (otherHrp.Position - position).Magnitude
                if distance <= range then
                    table.insert(nearbyPlayers, {name = otherPlayer.Name, distance = math.floor(distance)})
                end
            end
        end
    end
    return nearbyPlayers
end

