_0xa299._0xf02e:AddToggle("Auto Infuse Weapons", false, function(Value)
    _0xa299._0x1915.autoInfuseWeapons = Value
    
    if Value then
        -- Start auto infuse loop
        if _0xa299._0x1915.autoInfuseConnection then
            task.cancel(_0xa299._0x1915.autoInfuseConnection)
        end
        
        _0xa299._0x1915.autoInfuseConnection = task.spawn(function()
            local gemTypes = {"Ice Gem", "Fire Gem", "Lightning Gem", "Water Gem", "Earth Gem", "Poison Gem", "Black Flame Gem", "Wind Gem"}
            
            while _0xa299._0x1915.autoInfuseWeapons do
                pcall(function()
                    -- Get player data to check inventory
                    local success, playerdata = pcall(function()
                        return _0xa299._0xe08d:WaitForChild("Events"):WaitForChild("DataFunction"):InvokeServer("GetData")
                    end)
                    
                    if success and playerdata then
                        local foundGem = nil
                        
                        -- Check for gems in inventory and loadout
                        local function checkForGems(location)
                            if not location or foundGem then return end
                            for _, itemData in pairs(location) do
                                if type(itemData) == "table" and itemData.Item then
                                    for _, gemName in ipairs(gemTypes) do
                                        if itemData.Item == gemName then
                                            foundGem = gemName
                                            return
                                        end
                                    end
                                end
                            end
                        end
                        
                        checkForGems(playerdata["Inventory"])
                        if not foundGem then
                            checkForGems(playerdata["Loadout"])
                        end
                        
                        -- If we found a gem, fire the infuse request
                        if foundGem then
                            local args = {
                                "RequestToInfuse",
                                foundGem
                            }
                            _0xa299._0xe08d:WaitForChild("Events"):WaitForChild("DataFunction"):InvokeServer(unpack(args))
                        end
                    end
                end)
                task.wait(5)
            end
        end)
    else
        -- Stop auto infuse loop
        if _0xa299._0x1915.autoInfuseConnection then
            task.cancel(_0xa299._0x1915.autoInfuseConnection)
            _0xa299._0x1915.autoInfuseConnection = nil
        end
    end
end)

