--[[DUAL_FARM_REMOVED
function _0xa299._0xDualFarmLog(message)
    if _0xa299._0xDualFarmDebug then
        print("[DualFarm] " .. tostring(message))
    end
end

-- Save Dual Farm link state to file
function _0xa299._0xSaveDualFarmLink()
    _0xa299._0xDualFarmLog("Saving link state...")
    local success, err = pcall(function()
        if not isfolder("_0xa49c") then
            makefolder("_0xa49c")
        end
        
        -- Sync linkedAccount and partnerUsername before saving
        local partnerToSave = _0xa299._0xDualFarm.partnerUsername
        if (not partnerToSave or partnerToSave == "") and _0xa299._0xDualFarm.linkedAccount and _0xa299._0xDualFarm.linkedAccount ~= "" then
            partnerToSave = _0xa299._0xDualFarm.linkedAccount
            _0xa299._0xDualFarm.partnerUsername = partnerToSave
        elseif partnerToSave and partnerToSave ~= "" and (not _0xa299._0xDualFarm.linkedAccount or _0xa299._0xDualFarm.linkedAccount == "") then
            _0xa299._0xDualFarm.linkedAccount = partnerToSave
        end
        
        -- CRITICAL: Never save self as partner
        local myUsername = _0xa299._0x396d.Name
        if partnerToSave == myUsername then
            _0xa299._0xDualFarmLog("Save ERROR: partnerUsername equals self! Clearing invalid data.")
            partnerToSave = nil
            _0xa299._0xDualFarm.partnerUsername = nil
            _0xa299._0xDualFarm.linkedAccount = ""
            _0xa299._0xDualFarm.isLinked = false
        end
        
        -- CRITICAL: Don't overwrite good saved data with nil values
        -- If we're trying to save nil partner, check if file has good data first
        if (not partnerToSave or partnerToSave == "") and isfile(_0xa299._0xDualFarmFile) then
            local existingContent = readfile(_0xa299._0xDualFarmFile)
            local existingData = _0xa299._0x5f86:JSONDecode(existingContent)
            if existingData then
                local existingPartner = existingData.partnerUsername or existingData.linkedAccount
                if existingPartner and existingPartner ~= "" and existingPartner ~= myUsername then
                    _0xa299._0xDualFarmLog("Save: Preserving existing partner from file: " .. existingPartner)
                    partnerToSave = existingPartner
                    _0xa299._0xDualFarm.partnerUsername = existingPartner
                    _0xa299._0xDualFarm.linkedAccount = existingPartner
                    -- Also preserve isLinked and role if they were set
                    if existingData.isLinked then
                        _0xa299._0xDualFarm.isLinked = true
                    end
                    if existingData.role then
                        _0xa299._0xDualFarm.role = existingData.role
                    end
                end
            end
        end
        
        local data = {
            linkedAccount = _0xa299._0xDualFarm.linkedAccount,
            partnerUsername = partnerToSave,
            linkCode = _0xa299._0xDualFarm.linkCode,
            isLinked = _0xa299._0xDualFarm.isLinked,
            role = _0xa299._0xDualFarm.role,
            enabled = _0xa299._0xDualFarm.enabled
        }
        writefile(_0xa299._0xDualFarmFile, _0xa299._0x5f86:JSONEncode(data))
        _0xa299._0xDualFarmLog("Saved: isLinked=" .. tostring(data.isLinked) .. ", partner=" .. tostring(data.partnerUsername) .. ", enabled=" .. tostring(data.enabled))
    end)
    if not success then
        _0xa299._0xDualFarmLog("Save failed: " .. tostring(err))
    end
end

-- Load Dual Farm link state from file
function _0xa299._0xLoadDualFarmLink()
    _0xa299._0xDualFarmLog("Loading link state...")
    local success, err = pcall(function()
        if not isfile(_0xa299._0xDualFarmFile) then
            _0xa299._0xDualFarmLog("No saved file found")
            return
        end
        
        local content = readfile(_0xa299._0xDualFarmFile)
        local data = _0xa299._0x5f86:JSONDecode(content)
        if not data then
            _0xa299._0xDualFarmLog("No data in file")
            return
        end
        
        local myUsername = _0xa299._0x396d.Name
        
        -- Get partner from file - prefer partnerUsername, fallback to linkedAccount
        local filePartner = data.partnerUsername
        if (not filePartner or filePartner == "") and data.linkedAccount and data.linkedAccount ~= "" then
            filePartner = data.linkedAccount
        end
        
        -- Validate file partner is not self
        if filePartner == myUsername then
            _0xa299._0xDualFarmLog("Load ERROR: Saved partner equals self! Ignoring.")
            filePartner = nil
        end
        
        -- Get current runtime partner (may have been set by UI before load)
        local runtimePartner = _0xa299._0xDualFarm.partnerUsername
        if (not runtimePartner or runtimePartner == "") then
            runtimePartner = _0xa299._0xDualFarm.linkedAccount
        end
        
        -- Decide which partner to use: prefer runtime if set, else use file
        local finalPartner = nil
        if runtimePartner and runtimePartner ~= "" and runtimePartner ~= myUsername then
            finalPartner = runtimePartner
            _0xa299._0xDualFarmLog("Load: Using runtime partner: " .. finalPartner)
        elseif filePartner and filePartner ~= "" then
            finalPartner = filePartner
            _0xa299._0xDualFarmLog("Load: Using file partner: " .. finalPartner)
        end
        
        -- Set both variables to the final partner
        _0xa299._0xDualFarm.linkedAccount = finalPartner or ""
        _0xa299._0xDualFarm.partnerUsername = finalPartner
        
        -- Only load link state from file if we have a valid partner
        if finalPartner and finalPartner ~= "" then
            _0xa299._0xDualFarm.linkCode = data.linkCode
            _0xa299._0xDualFarm.isLinked = data.isLinked or false
            _0xa299._0xDualFarm.role = data.role or "Farmer"
        end
        
        _0xa299._0xDualFarmLog("Loaded: isLinked=" .. tostring(_0xa299._0xDualFarm.isLinked) .. ", partner=" .. tostring(_0xa299._0xDualFarm.partnerUsername) .. ", linkedAccount=" .. tostring(_0xa299._0xDualFarm.linkedAccount) .. ", role=" .. tostring(_0xa299._0xDualFarm.role))
        
        -- NOTE: Auto-resume DISABLED - Dual farm should only start from Linoria config toggle
        _0xa299._0xDualFarm.enabled = false
        _0xa299._0xDualFarmLog("Load complete - enabled=false (waiting for config toggle)")
    end)
    if not success then
        _0xa299._0xDualFarmLog("Load failed: " .. tostring(err))
    end
end

