-- Poll for incoming link requests
function _0xa299._0xPollForLinkRequests()
    local success, err = pcall(function()
        if not _0xa299._0xSessionValid then 
            _0xa299._0xDualFarmLog("PollLinkRequests: Session not valid")
            return 
        end
        if not _0xa299._0x0a65 then 
            _0xa299._0xDualFarmLog("PollLinkRequests: Not authenticated")
            return 
        end
        if _0xa299._0xDualFarm.isLinked then 
            return -- Already linked, no need to log
        end
        if _0xa299._0xDualFarm.linkPopupGui then 
            return -- Popup already showing
        end
        
        local baseUrl = _0xa299._0xGetUrl()
        local apiKey = _0xa299._0xGetApiKey()
        if not baseUrl or not apiKey then 
            _0xa299._0xDualFarmLog("PollLinkRequests: No baseUrl or apiKey")
            return 
        end
        
        local myUsername = _0xa299._0x396d.Name
        local url = baseUrl .. "/rest/v1/dual_farm?partner_username=eq." .. myUsername .. "&status=eq.linking&select=*"
        
        local response = _0xa299._0xSecureRequest({
            Url = url,
            Method = "GET",
            Headers = {
                ["apikey"] = apiKey,
                ["Authorization"] = "Bearer " .. apiKey
            }
        })
        
        if response and response.Body then
            local data = _0xa299._0x5f86:JSONDecode(response.Body)
            _0xa299._0xDualFarmLog("PollLinkRequests: Got " .. #data .. " pending requests")
            if data and #data > 0 then
                local request = data[1]
                local requesterName = request.username
                _0xa299._0xDualFarmLog("PollLinkRequests: Link request from " .. requesterName)
                
                -- Validate requester is not self
                local myUsername = _0xa299._0x396d.Name
                if requesterName == myUsername then
                    _0xa299._0xDualFarmLog("PollLinkRequests: ERROR - Link request from self, ignoring")
                    return
                end
                
                -- Show popup
                _0xa299._0xShowLinkRequestPopup(requesterName, function()
                    -- On Accept - CRITICAL: Set BOTH variables to ensure sync
                    _0xa299._0xDualFarmLog("PollLinkRequests: Accepted link from " .. requesterName)
                    
                    -- Double-check we're not linking to self
                    if requesterName == _0xa299._0x396d.Name then
                        _0xa299._0xDualFarmLog("PollLinkRequests: ERROR - Cannot accept link from self!")
                        _0xa299._0x8545:Notify("Dual Farm", "Error: Cannot link to yourself", 3, "error")
                        return
                    end
                    
                    _0xa299._0xDualFarm.partnerUsername = requesterName
                    _0xa299._0xDualFarm.linkedAccount = requesterName
                    _0xa299._0xDualFarm.linkCode = request.link_code
                    _0xa299._0xDualFarm.isLinked = true
                    
                    -- Log the values to confirm they're correct
                    _0xa299._0xDualFarmLog("PollLinkRequests: Set partnerUsername=" .. tostring(_0xa299._0xDualFarm.partnerUsername))
                    _0xa299._0xDualFarmLog("PollLinkRequests: Set linkedAccount=" .. tostring(_0xa299._0xDualFarm.linkedAccount))
                    
                    _0xa299._0xDualFarmUpdate("linked", nil)
                    _0xa299._0xSaveDualFarmLink() -- Save link state
                    _0xa299._0x8545:Notify("Dual Farm", "Linked with " .. requesterName .. "!", 3, "check")
                end, function()
                    -- On Decline
                    _0xa299._0xDualFarmLog("PollLinkRequests: Declined link from " .. requesterName)
                    _0xa299._0x8545:Notify("Dual Farm", "Declined link request from " .. requesterName, 3, "info")
                    -- Update status to declined
                    pcall(function()
                        _0xa299._0xSecureRequest({
                            Url = baseUrl .. "/rest/v1/dual_farm?username=eq." .. requesterName,
                            Method = "PATCH",
                            Headers = {
                                ["Content-Type"] = "application/json",
                                ["apikey"] = apiKey,
                                ["Authorization"] = "Bearer " .. apiKey
                            },
                            Body = _0xa299._0x5f86:JSONEncode({status = "declined"})
                        })
                    end)
                end)
            end
        else
            _0xa299._0xDualFarmLog("PollLinkRequests: No response or empty body")
        end
    end)
    
    if not success then
        _0xa299._0xDualFarmLog("PollLinkRequests: Error - " .. tostring(err))
    end
end

-- Start polling for link requests
task.spawn(function()
    while task.wait(3) do
        _0xa299._0xPollForLinkRequests()
    end
end)

-- Send dual farm status to Supabase
function _0xa299._0xDualFarmUpdate(status, data)
    _0xa299._0xDualFarmLog("DualFarmUpdate: status=" .. tostring(status))
    local success, err = pcall(function()
        if not _0xa299._0xSessionValid then 
            _0xa299._0xDualFarmLog("DualFarmUpdate: Session not valid")
            return 
        end
        if not _0xa299._0x0a65 then 
            _0xa299._0xDualFarmLog("DualFarmUpdate: Not authenticated")
            return 
        end
        
        local baseUrl = _0xa299._0xGetUrl()
        local apiKey = _0xa299._0xGetApiKey()
        if not baseUrl or not apiKey then 
            _0xa299._0xDualFarmLog("DualFarmUpdate: Missing URL or API key")
            return 
        end
        
        local username = _0xa299._0x396d.Name
        
        -- CRITICAL: Validate partnerUsername before saving
        local partnerToSave = _0xa299._0xDualFarm.partnerUsername
        
        -- If partnerUsername is nil, try to use linkedAccount as fallback
        if not partnerToSave or partnerToSave == "" then
            partnerToSave = _0xa299._0xDualFarm.linkedAccount
            if partnerToSave and partnerToSave ~= "" then
                _0xa299._0xDualFarmLog("DualFarmUpdate: Using linkedAccount as fallback: " .. partnerToSave)
                _0xa299._0xDualFarm.partnerUsername = partnerToSave -- Sync the values
            end
        end
        
        -- CRITICAL: Never save self as partner - this is the bug fix
        if partnerToSave == username then
            _0xa299._0xDualFarmLog("DualFarmUpdate: ERROR - partner_username equals self! Aborting save.")
            return
        end
        
        -- Don't save if we don't have a valid partner (except for certain statuses)
        if (not partnerToSave or partnerToSave == "") and status ~= "searching" and status ~= "stopped" then
            _0xa299._0xDualFarmLog("DualFarmUpdate: WARNING - No valid partner_username, skipping save for status: " .. status)
            return
        end
        
        local body = _0xa299._0x5f86:JSONEncode({
            username = username,
            link_code = _0xa299._0xDualFarm.linkCode,
            partner_username = partnerToSave,
            role = _0xa299._0xDualFarm.role,
            status = status,
            job_id = game.JobId,
            beast_found = data and data.beast or nil,
            beast_knocked = data and data.knocked or false,
            partner_ready = _0xa299._0xDualFarm.partnerReady,
            updated_at = os.date("!%Y-%m-%dT%H:%M:%SZ")
        })
        
        _0xa299._0xDualFarmLog("DualFarmUpdate: Sending to Supabase - partner=" .. tostring(partnerToSave))
        local response = _0xa299._0xSecureRequest({
            Url = baseUrl .. "/rest/v1/dual_farm?on_conflict=username",
            Method = "POST",
            Headers = {
                ["Content-Type"] = "application/json",
                ["apikey"] = apiKey,
                ["Authorization"] = "Bearer " .. apiKey,
                ["Prefer"] = "resolution=merge-duplicates"
            },
            Body = body
        })
        _0xa299._0xDualFarmLog("DualFarmUpdate: Response=" .. tostring(response and response.StatusCode))
    end)
    if not success then
        _0xa299._0xDualFarmLog("DualFarmUpdate: Error - " .. tostring(err))
    end
end

-- Poll for partner status
function _0xa299._0xDualFarmPoll()
    local result = nil
    local success, err = pcall(function()
        if not _0xa299._0xSessionValid then return end
        if not _0xa299._0x0a65 then return end
        
        -- Get partner username, with fallback to linkedAccount
        local partnerToQuery = _0xa299._0xDualFarm.partnerUsername
        if not partnerToQuery or partnerToQuery == "" then
            partnerToQuery = _0xa299._0xDualFarm.linkedAccount
            if partnerToQuery and partnerToQuery ~= "" then
                _0xa299._0xDualFarm.partnerUsername = partnerToQuery -- Sync
            end
        end
        
        if not partnerToQuery or partnerToQuery == "" then
            _0xa299._0xDualFarmLog("DualFarmPoll: No partner username set")
            return 
        end
        
        -- Validate we're not polling self
        if partnerToQuery == _0xa299._0x396d.Name then
            _0xa299._0xDualFarmLog("DualFarmPoll: ERROR - trying to poll self!")
            return
        end
        
        local baseUrl = _0xa299._0xGetUrl()
        local apiKey = _0xa299._0xGetApiKey()
        if not baseUrl or not apiKey then return end
        
        local url = baseUrl .. "/rest/v1/dual_farm?username=eq." .. partnerToQuery .. "&select=*"
        
        local response = _0xa299._0xSecureRequest({
            Url = url,
            Method = "GET",
            Headers = {
                ["apikey"] = apiKey,
                ["Authorization"] = "Bearer " .. apiKey
            }
        })
        
        if response and response.Body then
            local data = _0xa299._0x5f86:JSONDecode(response.Body)
            if data and #data > 0 then
                result = data[1]
                _0xa299._0xDualFarmLog("DualFarmPoll: Got partner data - status=" .. tostring(result.status) .. ", job_id=" .. tostring(result.job_id))
            else
                _0xa299._0xDualFarmLog("DualFarmPoll: No data for partner")
            end
        end
    end)
    if not success then
        _0xa299._0xDualFarmLog("DualFarmPoll: Error - " .. tostring(err))
    end
    return result
end

-- Link accounts via Supabase
function _0xa299._0xLinkAccount(partnerName)
    _0xa299._0xDualFarmLog("LinkAccount: Attempting to link with " .. tostring(partnerName))
    
    -- Trim whitespace from partner name
    if partnerName then
        partnerName = partnerName:match("^%s*(.-)%s*$")
    end
    
    if not partnerName or partnerName == "" then
        _0xa299._0xDualFarmLog("LinkAccount: No partner name provided")
        _0xa299._0x8545:Notify("Dual Farm", "Enter a partner username", 3, "error")
        return false
    end
    
    local myUsername = _0xa299._0x396d.Name
    if partnerName == myUsername then
        _0xa299._0xDualFarmLog("LinkAccount: Cannot link to self")
        _0xa299._0x8545:Notify("Dual Farm", "Cannot link to yourself", 3, "error")
        return false
    end
    
    -- Generate link code and SET BOTH variables to ensure sync
    _0xa299._0xDualFarm.linkCode = _0xa299._0xGenerateLinkCode()
    _0xa299._0xDualFarm.partnerUsername = partnerName
    _0xa299._0xDualFarm.linkedAccount = partnerName
    
    -- Double-check the values are correct before proceeding
    _0xa299._0xDualFarmLog("LinkAccount: Set partnerUsername=" .. tostring(_0xa299._0xDualFarm.partnerUsername) .. ", linkedAccount=" .. tostring(_0xa299._0xDualFarm.linkedAccount))
    _0xa299._0xDualFarmLog("LinkAccount: Generated link code " .. tostring(_0xa299._0xDualFarm.linkCode))
    
    -- Send initial link request
    _0xa299._0xDualFarmUpdate("linking", nil)
    
    _0xa299._0x8545:Notify("Dual Farm", "Linking to " .. partnerName .. "...", 3, "info")
    
    -- Wait for partner to also link (poll for 30 seconds)
    local startTime = tick()
    local linked = false
    
    task.spawn(function()
        while tick() - startTime < 30 and not linked do
            task.wait(2)
            
            -- Check if our request was declined
            local baseUrl = _0xa299._0xGetUrl()
            local apiKey = _0xa299._0xGetApiKey()
            if baseUrl and apiKey then
                local myData = nil
                pcall(function()
                    local response = _0xa299._0xSecureRequest({
                        Url = baseUrl .. "/rest/v1/dual_farm?username=eq." .. _0xa299._0x396d.Name .. "&select=*",
                        Method = "GET",
                        Headers = {
                            ["apikey"] = apiKey,
                            ["Authorization"] = "Bearer " .. apiKey
                        }
                    })
                    if response and response.Body then
                        local data = _0xa299._0x5f86:JSONDecode(response.Body)
                        if data and #data > 0 then
                            myData = data[1]
                        end
                    end
                end)
                
                if myData and myData.status == "declined" then
                    _0xa299._0x8545:Notify("Dual Farm", partnerName .. " declined your link request", 3, "error")
                    _0xa299._0xDualFarm.partnerUsername = nil
                    _0xa299._0xDualFarm.linkedAccount = ""
                    return
                end
            end
            
            local partnerData = _0xa299._0xDualFarmPoll()
            _0xa299._0xDualFarmLog("LinkAccount: Polling... partnerData=" .. tostring(partnerData ~= nil))
            if partnerData then
                _0xa299._0xDualFarmLog("LinkAccount: Partner status=" .. tostring(partnerData.status) .. ", partner_username=" .. tostring(partnerData.partner_username))
            end
            if partnerData and partnerData.status == "linked" and partnerData.partner_username == _0xa299._0x396d.Name then
                linked = true
                _0xa299._0xDualFarm.isLinked = true
                _0xa299._0xDualFarmUpdate("linked", nil)
                _0xa299._0xSaveDualFarmLink() -- Save link state
                _0xa299._0xDualFarmLog("LinkAccount: Successfully linked!")
                _0xa299._0x8545:Notify("Dual Farm", "Linked with " .. partnerName .. "!", 3, "check")
            end
        end
        
        if not linked then
