    return true
end

-- Find tailed beast in current server
function _0xa299._0xFindTailedBeast()
    _0xa299._0xDualFarmLog("FindTailedBeast: Searching...")
    for _, beastName in ipairs({"Matatabi", "Shukaku"}) do
        local beast = workspace:FindFirstChild(beastName)
        if beast then
            local hrp = beast:FindFirstChild("HumanoidRootPart")
            local humanoid = beast:FindFirstChild("Humanoid")
            _0xa299._0xDualFarmLog("FindTailedBeast: Found " .. beastName .. " - HRP=" .. tostring(hrp ~= nil) .. ", Humanoid=" .. tostring(humanoid ~= nil) .. ", Health=" .. tostring(humanoid and humanoid.Health or 0))
            if hrp and humanoid and humanoid.Health > 0 then
                _0xa299._0xDualFarmLog("FindTailedBeast: Returning " .. beastName)
                return beastName, beast
            end
        end
    end
    _0xa299._0xDualFarmLog("FindTailedBeast: No beast found")
    return nil, nil
end

-- Check if beast is knocked (same as tailed beast farm)
function _0xa299._0xIsBeastKnocked(beast)
    if not beast then 
        _0xa299._0xDualFarmLog("IsBeastKnocked: No beast provided")
        return false 
    end
    
    -- Check Settings.Knocked.Value (exactly like tailed beast farm)
    local settings = beast:FindFirstChild("Settings")
    if not settings then
        _0xa299._0xDualFarmLog("IsBeastKnocked: No Settings folder found on " .. beast.Name)
        return false
    end
    
    local knockedValue = settings:FindFirstChild("Knocked")
    if not knockedValue then
        _0xa299._0xDualFarmLog("IsBeastKnocked: No Knocked value found in Settings for " .. beast.Name)
        return false
    end
    
    local isKnocked = knockedValue.Value
    _0xa299._0xDualFarmLog("IsBeastKnocked: " .. beast.Name .. " Knocked.Value = " .. tostring(isKnocked))
    
    return isKnocked == true
end

