-- Start Farmer sub-loops (auto M1, auto dodge, auto weapon equip)
function _0xa299._0xStartFarmerSubLoops()
    _0xa299._0xDualFarmLog("StartFarmerSubLoops: Starting sub-loops")
    local RS = _0xa299._0xe08d
    
    -- Auto M1 connection
    _0xa299._0xDualFarm.m1Connection = task.spawn(function()
        while _0xa299._0xDualFarm.farming do
            task.wait(0.15)
            if not _0xa299._0xDualFarm.enabled or not _0xa299._0xDualFarm.farming then break end
            
            pcall(function()
                local userSettings = RS.Settings:FindFirstChild(_0xa299._0x396d.Name)
                if userSettings then
                    local args = {"CheckMeleeHit", nil, "NormalAttack", false, _0xa299._0xTags.CheckMeleeHit}
                    RS.Events.DataEvent:FireServer(unpack(args, 1, 5))
                end
            end)
        end
        _0xa299._0xDualFarmLog("StartFarmerSubLoops: M1 loop ended")
    end)
    
    -- Auto dash/sub spam and blocking/charging loop
    _0xa299._0xDualFarm.dashConnection = task.spawn(function()
        local lastSubChangeTime = 0
        local cooldown = 0.5
        local DataEvent = RS:WaitForChild("Events"):WaitForChild("DataEvent")
        
        while _0xa299._0xDualFarm.farming do
            task.wait(0.2)
            if not _0xa299._0xDualFarm.enabled or not _0xa299._0xDualFarm.farming then break end
            
            -- Sub-dash spam to reset stun
            if tick() - lastSubChangeTime >= cooldown then
                if _0xa299._0x396d.Character and _0xa299._0x396d.Character:FindFirstChild("HumanoidRootPart") then
                    lastSubChangeTime = tick()
                    DataEvent:FireServer("TakeDamage", 0.000000001)
                    DataEvent:FireServer("Dash", "Sub", _0xa299._0x396d.Character.HumanoidRootPart.Position)
                end
            end
            
            -- Auto blocking
            pcall(function()
                if RS.Settings:FindFirstChild(_0xa299._0x396d.Name) and RS.Settings[_0xa299._0x396d.Name]:FindFirstChild("Blocking") then
                    if RS.Settings[_0xa299._0x396d.Name]:FindFirstChild("Blocking").Value == false then
                        RS:WaitForChild("Events"):WaitForChild("DataFunction"):InvokeServer("Block", _0xa299._0xTags.Block)
                    end
                end
            end)
            
            -- Charging (chakra charge)
            DataEvent:FireServer("Charging")
        end
        _0xa299._0xDualFarmLog("StartFarmerSubLoops: Dash loop ended")
    end)
    
    -- Auto weapon re-equip loop
    _0xa299._0xDualFarm.weaponConnection = task.spawn(function()
        while _0xa299._0xDualFarm.farming do
            task.wait(0.4)
            if not _0xa299._0xDualFarm.enabled or not _0xa299._0xDualFarm.farming then break end
            
            pcall(function()
                if _0xa299._0x396d.Character and _0xa299._0x396d.Character:FindFirstChild("FakeHead") then
                    local fakeHead = _0xa299._0x396d.Character.FakeHead
                    if fakeHead:FindFirstChild("skillGUI") then
                        local skillGUI = fakeHead.skillGUI
                        
                        local remote = RS:WaitForChild("Events"):WaitForChild("DataFunction")
                        local playerdata = remote:InvokeServer("GetData")
                        
                        if playerdata then
                            local currentWeapon = playerdata["CurrentWeapon"]
                            local possibleWeapons = {"Golden Zabunagi", "Silver Zabunagi", "Onyx Zabunagi", "Samehada", "Executioner's Blade", "Gunbai", "Silver Kunai", "Golden Kunai", "Onyx Kunai", "Raijin Kunai", "Silver Resanagi", "Golden Resanagi", "Onyx Resanagi", "Kusanagi", "Silver Halberd", "Golden Halberd", "Onyx Halberd", "Adamantine Staff", "Silver Asumai", "Golden Asumai", "Onyx Asumai", "Frozen Executioner's Blade", "Jingle Bell Staff", "Candy Cane Kusanagi", "Nutcracker Raijin", "Tree Samehada", "Gingerbread Gunbai", "Metallic Bow", "Chakra Bow"}
                            
                            local weaponToEquip = nil
                            if currentWeapon then
                                for _, weaponName in pairs(possibleWeapons) do
                                    if currentWeapon == weaponName then
                                        weaponToEquip = currentWeapon
                                        break
                                    end
                                end
                            end
                            
                            -- Re-equip if not currently equipped
                            if weaponToEquip and skillGUI:FindFirstChild("skillName") and skillGUI.skillName.Text ~= weaponToEquip then
                                task.wait(0.4)
                                RS.Events.DataEvent:FireServer("Item", "Unselected", skillGUI.skillName.Text)
                                RS.Events.DataEvent:FireServer("Item", "Selected", weaponToEquip)
                            end
                        end
                    end
                end
            end)
        end
        _0xa299._0xDualFarmLog("StartFarmerSubLoops: Weapon loop ended")
    end)
end

-- Stop Farmer sub-loops
function _0xa299._0xStopFarmerSubLoops()
    _0xa299._0xDualFarmLog("StopFarmerSubLoops: Stopping sub-loops")
    if _0xa299._0xDualFarm.m1Connection then
        task.cancel(_0xa299._0xDualFarm.m1Connection)
