-- Main Dual Farm loop for Farmer role
function _0xa299._0xDualFarmFarmerLoop()
    _0xa299._0xDualFarmLog("FarmerLoop: Starting iteration")
    
    -- Force load into game first
    _0xa299._0xDualFarmForceLoad()
    task.wait(0.5)
    
    local hrp = _0xa299._0x396d.Character and _0xa299._0x396d.Character:FindFirstChild("HumanoidRootPart")
    if not hrp then 
        _0xa299._0xDualFarmLog("FarmerLoop: No HRP, waiting...")
        return 
    end
    
    -- Find beast
    _0xa299._0xDualFarmLog("FarmerLoop: Searching for beast...")
    local beastName, beast = _0xa299._0xFindTailedBeast()
    if not beast then
        -- No beast, server hop
        _0xa299._0xDualFarmLog("FarmerLoop: No beast found, checking if should hop...")
        if _0xa299._0xDualFarm.enabled then
            _0xa299._0xDualFarmLog("FarmerLoop: Initiating server hop NOW")
            _0xa299._0x8545:Notify("Dual Farm", "No tailed beast found, server hopping", 3, "info")
            _0xa299._0xDualFarmUpdate("searching", nil)
            -- Save state before hopping so it auto-resumes
            _0xa299._0xSaveDualFarmLink()
            -- Immediate server hop - no delay
            task.spawn(function()
                _0xa299._0xDualFarmLog("FarmerLoop: Calling _0xb5ef")
                _0xa299._0xb5ef()
            end)
            -- Prevent loop from continuing
            _0xa299._0xDualFarm.farming = false
        end
        return
    end
    
    _0xa299._0xDualFarm.currentBeast = beastName
    
    -- Beast found! Signal partner
    _0xa299._0xTeleportPartnerToServer()
    
    -- Wait for partner to join (wait indefinitely until partner joins or farm stops)
    _0xa299._0xDualFarm.waitingForPartner = true
    _0xa299._0x8545:Notify("Dual Farm", "Waiting for partner (Sealer) to join", 5, "info")
    
    while _0xa299._0xDualFarm.enabled and _0xa299._0xDualFarm.farming do
        task.wait(2)
        local partnerData = _0xa299._0xDualFarmPoll()
        if partnerData and partnerData.job_id == game.JobId and partnerData.status == "ready" then
            _0xa299._0xDualFarm.partnerReady = true
            _0xa299._0x8545:Notify("Dual Farm", "Partner joined, starting farm", 3, "check")
            break
        end
        
        -- Re-signal partner every 10 seconds
        _0xa299._0xTeleportPartnerToServer()
    end
    
    _0xa299._0xDualFarm.waitingForPartner = false
    
    -- Start sub-loops for auto M1, dodge, weapon equip
    _0xa299._0xStartFarmerSubLoops()
    
    -- Start farming (similar to regular tailed beast farm)
    local config = _0xa299._0x5ecb[beastName]
    local offset = (config and config.offset) or 30
    
    local bossHrp = beast:FindFirstChild("HumanoidRootPart")
    if not bossHrp then 
        _0xa299._0xStopFarmerSubLoops()
        return 
    end
    
    -- Get beast config for danger animations
    local beastConfig = _0xa299._0x4686[beastName]
    local dangerTime = (beastConfig and beastConfig.dangerTime) or 0.1
    
    -- Danger hold tracking
    local fourthDangerHoldUntil = 0
    
    -- Farm loop
    while _0xa299._0xDualFarm.enabled and _0xa299._0xDualFarm.farming do
        hrp = _0xa299._0x396d.Character and _0xa299._0x396d.Character:FindFirstChild("HumanoidRootPart")
        if not hrp then task.wait(0.1) continue end
        
        beast = workspace:FindFirstChild(beastName)
        if not beast then
            _0xa299._0x8545:Notify("Dual Farm", "Beast defeated/sealed, looking for the next", 3, "check")
            _0xa299._0xDualFarmUpdate("searching", nil)
            task.wait(3)
            break
        end
        
        bossHrp = beast:FindFirstChild("HumanoidRootPart")
        if not bossHrp then task.wait(0.1) continue end
        
        local bossHumanoid = beast:FindFirstChildOfClass("Humanoid")
        
        -- Check if beast is knocked
        if _0xa299._0xIsBeastKnocked(beast) then
            _0xa299._0xDualFarm.beastKnocked = true
            _0xa299._0xDualFarmUpdate("knocked", {beast = beastName, knocked = true})
            _0xa299._0x8545:Notify("Dual Farm", beastName .. " knocked! Sealer should seal now...", 3, "check")
            
            -- Wait for beast to be sealed (disappear)
            while beast and beast.Parent and _0xa299._0xDualFarm.enabled do
                task.wait(0.5)
                beast = workspace:FindFirstChild(beastName)
            end
            
            _0xa299._0xDualFarm.beastKnocked = false
            break
        end
        
        -- Animation-based dodging (like tailed beast farm)
        local extraOffset = 0
        if beastConfig and bossHumanoid then
            local animator = bossHumanoid:FindFirstChildOfClass("Animator")
            if animator then
                -- Check primary danger animation
                if beastConfig.dangerAnim then
                    for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                        if track.Animation.AnimationId == beastConfig.dangerAnim then
                            if track.TimePosition > dangerTime and track.TimePosition < 2.7 then
                                extraOffset = 100
                                break
                            end
                        end
                    end
                end
                
                -- Check second danger animation
                if extraOffset == 0 and beastConfig.secondDangerAnim then
                    for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                        if track.Animation.AnimationId == beastConfig.secondDangerAnim then
                            if track.TimePosition > dangerTime and track.TimePosition < 2.7 then
                                extraOffset = 100
                                break
                            end
                        end
                    end
                end
                
                -- Check third danger animation
                if extraOffset == 0 and beastConfig.thirdDangerAnim then
                    for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                        if track.Animation.AnimationId == beastConfig.thirdDangerAnim then
                            if track.TimePosition > dangerTime and track.TimePosition < 2.7 then
                                extraOffset = 100
                                break
                            end
                        end
                    end
                end
                
                -- Check fourth danger animation (big attack - needs longer hold)
                if extraOffset == 0 and beastConfig.fourthDangerAnim then
                    for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                        if track.Animation.AnimationId == beastConfig.fourthDangerAnim then
                            if track.TimePosition > dangerTime and track.TimePosition < 2.7 then
                                extraOffset = 300
                                fourthDangerHoldUntil = tick() + 9
                                break
                            end
                        end
                    end
                end
                
                -- Keep offset if still within fourth danger hold period
                if extraOffset == 0 and tick() < fourthDangerHoldUntil then
                    extraOffset = 300
                end
                
                -- Check fifth danger animation (Shukaku)
                if extraOffset == 0 and beastConfig.fifthDangerAnim then
                    for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                        if track.Animation.AnimationId == beastConfig.fifthDangerAnim then
                            if track.TimePosition > dangerTime and track.TimePosition < 2.7 then
                                extraOffset = 100
                                break
                            end
                        end
                    end
                end
            end
        end
        
        -- Rotate around boss (same as regular farm)
        local angle = tick() * (_0xa299._0xf9c2.rotationSpeed or 25) * 0.1
        local radius = _0xa299._0xf9c2.rotationRadius or 15
        local vertOffset = _0xa299._0xf9c2.verticalOffset or 5
        
        local targetPos = bossHrp.Position + Vector3.new(
            math.cos(angle) * radius,
            offset + vertOffset + extraOffset,
            math.sin(angle) * radius
        )
        
        hrp.CFrame = CFrame.new(targetPos, bossHrp.Position)
        
        task.wait()
    end
    
    -- Stop sub-loops when done
    _0xa299._0xStopFarmerSubLoops()
end

-- Get farthest dodge position from beast (excluding last used index)
function _0xa299._0xGetFarthestDodgePosition(beastName, beastPos)
    local positions = _0xa299._0xDualFarm.sealerDodgePositions[beastName]
    if not positions then return nil, 0 end
    
    local farthestDist = 0
    local farthestIndex = 1
    
    for i, pos in ipairs(positions) do
        -- Skip the last used position
        if i ~= _0xa299._0xDualFarm.lastDodgeIndex then
            local dist = (pos.Position - beastPos).Magnitude
            if dist > farthestDist then
                farthestDist = dist
                farthestIndex = i
            end
        end
    end
    
    return positions[farthestIndex], farthestIndex
end

-- Main Dual Farm loop for Sealer role
function _0xa299._0xDualFarmSealerLoop()
    _0xa299._0xDualFarmLog("SealerLoop: Starting iteration")
    
    -- Force load into game first
    _0xa299._0xDualFarmForceLoad()
    task.wait(0.5)
    
    local hrp = _0xa299._0x396d.Character and _0xa299._0x396d.Character:FindFirstChild("HumanoidRootPart")
    if not hrp then 
        _0xa299._0xDualFarmLog("SealerLoop: No HRP, waiting...")
        return 
    end
    
    -- Check if we need to join partner's server
    _0xa299._0xDualFarmLog("SealerLoop: Polling partner data...")
    local partnerData = _0xa299._0xDualFarmPoll()
    if partnerData then
        _0xa299._0xDualFarmLog("SealerLoop: Partner status=" .. tostring(partnerData.status) .. ", job_id=" .. tostring(partnerData.job_id))
    end
    if partnerData and partnerData.status == "beast_found" and partnerData.job_id ~= game.JobId then
        _0xa299._0xDualFarmLog("SealerLoop: Partner found beast, joining their server")
        _0xa299._0xJoinPartnerServer(partnerData.job_id)
        return
    end
    
    -- Find beast
    _0xa299._0xDualFarmLog("SealerLoop: Searching for beast locally...")
    local beastName, beast = _0xa299._0xFindTailedBeast()
    if not beast then
        _0xa299._0xDualFarmLog("SealerLoop: No beast found locally, waiting for partner (10s max)...")
        -- No beast, wait for partner to find one (reduced from 30s to 10s)
        _0xa299._0xDualFarmUpdate("waiting", nil)
        
        -- Poll for partner finding beast - reduced time
        local pollStart = tick()
        while _0xa299._0xDualFarm.enabled and tick() - pollStart < 10 do
            task.wait(2)
            partnerData = _0xa299._0xDualFarmPoll()
            if partnerData then
                _0xa299._0xDualFarmLog("SealerLoop: Poll - Partner status=" .. tostring(partnerData.status))
            end
            if partnerData and partnerData.status == "beast_found" and partnerData.job_id and partnerData.job_id ~= game.JobId then
                _0xa299._0xDualFarmLog("SealerLoop: Partner found beast during poll, joining")
                _0xa299._0xJoinPartnerServer(partnerData.job_id)
                return
            end
        end
        
        -- No beast found by partner either, server hop immediately
        if _0xa299._0xDualFarm.enabled then
            _0xa299._0xDualFarmLog("SealerLoop: Timeout, initiating server hop NOW")
            _0xa299._0x8545:Notify("Dual Farm", "No beast found, server hopping", 3, "info")
            -- Save state before hopping so it auto-resumes
            _0xa299._0xSaveDualFarmLink()
            task.spawn(function()
                _0xa299._0xDualFarmLog("SealerLoop: Calling _0xb5ef")
                _0xa299._0xb5ef()
            end)
            _0xa299._0xDualFarm.farming = false
        end
        return
    end
    
    _0xa299._0xDualFarm.currentBeast = beastName
    _0xa299._0xDualFarmLog("SealerLoop: Beast found - " .. beastName)
    
    -- Initial teleport to first dodge position
    local dodgePositions = _0xa299._0xDualFarm.sealerDodgePositions[beastName]
    if dodgePositions and #dodgePositions > 0 then
        _0xa299._0xDualFarm.lastDodgeIndex = 1
        hrp.CFrame = dodgePositions[1]
        _0xa299._0xDualFarm.lastDodgeTime = tick()
        _0xa299._0xDualFarmLog("SealerLoop: Teleported to initial dodge position 1")
    end
    
    -- Signal ready
    _0xa299._0xDualFarmUpdate("ready", {beast = beastName})
    _0xa299._0x8545:Notify("Dual Farm", "Ready, dodging while waiting for " .. beastName .. " to be knocked...", 3, "check")
    
    -- Wait for beast to be knocked - with 4-position dodge system
    while _0xa299._0xDualFarm.enabled and _0xa299._0xDualFarm.farming do
        hrp = _0xa299._0x396d.Character and _0xa299._0x396d.Character:FindFirstChild("HumanoidRootPart")
        if not hrp then task.wait(0.1) continue end
        
        beast = workspace:FindFirstChild(beastName)
        if not beast then
            _0xa299._0x8545:Notify("Dual Farm", "Beast gone, looking for the next", 3, "info")
            break
        end
        
        local bossHrp = beast:FindFirstChild("HumanoidRootPart")
        
        -- Check partner status for knocked signal
        local partnerData = _0xa299._0xDualFarmPoll()
        local beastKnocked = (partnerData and partnerData.beast_knocked) or _0xa299._0xIsBeastKnocked(beast)
        
        if beastKnocked then
            _0xa299._0xDualFarmLog("SealerLoop: Beast knocked! Starting seal sequence")
            _0xa299._0x8545:Notify("Dual Farm", beastName .. " knocked! Sealing...", 3, "check")
            
            -- Teleport to beast and seal
            if bossHrp then
                hrp.CFrame = bossHrp.CFrame + Vector3.new(0, 5, 0)
            end
            
            -- Spam Binding Seal for 12 seconds
            local sealStartTime = tick()
            while tick() - sealStartTime < 12 and _0xa299._0xDualFarm.farming do
                -- Stay near the beast
                beast = workspace:FindFirstChild(beastName)
                if not beast then break end
                
                bossHrp = beast:FindFirstChild("HumanoidRootPart")
                if bossHrp and hrp and hrp.Parent then
                    local distance = (hrp.Position - bossHrp.Position).Magnitude
                    if distance > 60 then
                        hrp.CFrame = bossHrp.CFrame + Vector3.new(0, 5, 0)
                    end
                end
                
                pcall(function()
                    _0xa299._0xCastSkill("Binding Seal", hrp.Position)
                    task.wait()
                    _0xa299._0xe08d.Events.DataEvent:FireServer("ReleaseSkill")
                end)
                
                task.wait(0.1)
            end
            
            _0xa299._0x8545:Notify("Dual Farm", "Seal complete, resetting", 3, "check")
            _0xa299._0xDualFarmUpdate("sealed", {beast = beastName})
            
            -- Reset character
            pcall(function()
                _0xa299._0x396d.Character:FindFirstChild("Humanoid").Health = 0
            end)
            
            task.wait(3)
            break
        end
        
        -- 4-position dodge teleport system (1 second cooldown)
        if bossHrp and tick() - _0xa299._0xDualFarm.lastDodgeTime >= 1 then
            local newPos, newIndex = _0xa299._0xGetFarthestDodgePosition(beastName, bossHrp.Position)
            if newPos then
                hrp.CFrame = newPos
                _0xa299._0xDualFarm.lastDodgeIndex = newIndex
                _0xa299._0xDualFarm.lastDodgeTime = tick()
                _0xa299._0xDualFarmLog("SealerLoop: Dodged to position " .. newIndex)
            end
        end
        
        task.wait(0.1)
    end
end

-- Start Dual Farm
function _0xa299._0xStartDualFarm()
    _0xa299._0xDualFarmLog("StartDualFarm called")
    _0xa299._0xDualFarmLog("  farming=" .. tostring(_0xa299._0xDualFarm.farming) .. ", isLinked=" .. tostring(_0xa299._0xDualFarm.isLinked) .. ", enabled=" .. tostring(_0xa299._0xDualFarm.enabled))
    _0xa299._0xDualFarmLog("  partnerUsername=" .. tostring(_0xa299._0xDualFarm.partnerUsername) .. ", linkedAccount=" .. tostring(_0xa299._0xDualFarm.linkedAccount))
    
    if _0xa299._0xDualFarm.farming then 
        _0xa299._0xDualFarmLog("Already farming, skipping")
        return 
    end
    
    if not _0xa299._0xDualFarm.isLinked then
        _0xa299._0xDualFarmLog("Not linked, cannot start")
        _0xa299._0x8545:Notify("Dual Farm", "Link an account first", 3, "error")
        return
    end
    
    -- CRITICAL: Validate we have a valid partner username
    local partner = _0xa299._0xDualFarm.partnerUsername
    if not partner or partner == "" then
        -- Try to use linkedAccount as fallback
        partner = _0xa299._0xDualFarm.linkedAccount
        if partner and partner ~= "" then
            _0xa299._0xDualFarm.partnerUsername = partner
            _0xa299._0xDualFarmLog("StartDualFarm: Using linkedAccount as fallback partner: " .. partner)
        end
    end
    
    if not partner or partner == "" then
        _0xa299._0xDualFarmLog("StartDualFarm: No valid partner username!")
        _0xa299._0x8545:Notify("Dual Farm", "Error: No partner username set", 3, "error")
        _0xa299._0xDualFarm.isLinked = false
        return
    end
    
    -- Validate partner is not self
    if partner == _0xa299._0x396d.Name then
        _0xa299._0xDualFarmLog("StartDualFarm: ERROR - partner equals self!")
        _0xa299._0x8545:Notify("Dual Farm", "Error: Invalid partner (self)", 3, "error")
        _0xa299._0xDualFarm.isLinked = false
        _0xa299._0xDualFarm.partnerUsername = nil
        _0xa299._0xDualFarm.linkedAccount = ""
        return
    end
    
    _0xa299._0xDualFarm.farming = true
    _0xa299._0xDualFarm.enabled = true -- Ensure enabled is set
    _0xa299._0xDualFarmUpdate("starting", nil)
    _0xa299._0x8545:Notify("Dual Farm", "Starting Dual Farm as " .. _0xa299._0xDualFarm.role .. " with partner: " .. partner, 3, "check")
    _0xa299._0xDualFarmLog("Starting main loop as " .. _0xa299._0xDualFarm.role .. " with partner: " .. partner)
    
    _0xa299._0xDualFarm.connection = task.spawn(function()
        _0xa299._0xDualFarmLog("Main loop thread started")
        while _0xa299._0xDualFarm.enabled and _0xa299._0xDualFarm.farming do
            _0xa299._0xDualFarmLog("Loop iteration: enabled=" .. tostring(_0xa299._0xDualFarm.enabled) .. ", farming=" .. tostring(_0xa299._0xDualFarm.farming))
            if _0xa299._0xDualFarm.role == "Farmer" then
                _0xa299._0xDualFarmFarmerLoop()
            else
                _0xa299._0xDualFarmSealerLoop()
            end
            task.wait(0.5) -- Reduced from 1s to 0.5s for faster response
        end
        _0xa299._0xDualFarmLog("Main loop ended: enabled=" .. tostring(_0xa299._0xDualFarm.enabled) .. ", farming=" .. tostring(_0xa299._0xDualFarm.farming))
    end)
end

-- Stop Dual Farm
function _0xa299._0xStopDualFarm()
    _0xa299._0xDualFarmLog("StopDualFarm called")
    _0xa299._0xDualFarm.farming = false
    _0xa299._0xDualFarm.enabled = false
    
    -- Stop main connection
