-- EXPLOITER DETECTION
--
-- Looks for the movement signature our own boss farm produces, because that is
-- the thing we can actually recognise: repeated instant relocation between a
-- small set of fixed points, and standing perfectly motionless in between.
-- A legitimate player is walkspeed-bound and never stops fidgeting.
--
-- Designed around avoiding false positives, since a wrong hop costs a farm run:
--   * No single behaviour can flag anyone. A player must trip the teleport
--     count AND at least one independent second signal.
--   * The game's own travel system (chakra points, mission warps) produces real
--     teleports, so one or two are expected and ignored - it takes five inside
--     a rolling 90s window.
--   * Every player gets a full observation period before they are eligible at
--     all, so someone who joins mid-farm and warps once is never judged.
--   * Death resets a player's record completely. Respawning is a legitimate
--     instant relocation and would otherwise read as a teleport.
---------------------------------------------------------------------
_0xa299._0xEXD = {
    enabled = false,
    conn = nil,
    lastSample = 0,
    lastNpcScan = 0,
    npcs = {},
    players = {},

    SAMPLE = 0.25,       -- seconds between samples
    NPC_RESCAN = 2,      -- how often the NPC list is rebuilt

    -- FAST SIGNALS. Both are physically impossible by hand, so neither needs an
    -- observation period - they flag on their own the moment they are proven.

    -- Offset lock: the player holds the exact same relative position to an NPC
    -- while that NPC walks around. A human tracking a moving target drifts
    -- constantly; a scripted CFrame write does not drift at all. Requiring the
    -- NPC to have actually covered ground is what makes this safe - two players
    -- standing still near each other never trigger it.
    LOCK_RANGE = 40,     -- only track an NPC this close to the player
    LOCK_DEV = 2.5,      -- max drift from the initial offset, in studs
    LOCK_NPC_MOVED = 15, -- NPC must cover this much ground while locked

    -- Hover: sitting above an NPC. Nothing in normal play holds a player
    -- several studs off the ground directly over something for seconds.
    HOVER_Y = 3,         -- studs above the NPC
    HOVER_XZ = 8,        -- horizontal distance to count as "over" it
    HOVER_SAMPLES = 12,  -- consecutive samples (~3s) before it counts

    -- SLOW SIGNALS. These genuinely need time, because the game's own travel
    -- system produces real teleports and one or two are perfectly normal.
    OBSERVE_MIN = 60,    -- applies to the teleport signals ONLY
    WINDOW = 90,         -- rolling window teleports are counted in
    -- 100 studs in a quarter second. The fastest legitimate movement in this
    -- game (dashes, chakra tree jump) does not come close, so this only ever
    -- catches genuine relocation rather than fast running.
    TELEPORT_MIN = 100,
    TELEPORTS_NEEDED = 5,
    STILL_EPS = 0.35,    -- under this counts as not having moved at all
    STILL_RATIO = 0.9,   -- share of samples motionless to count as a statue
    ANCHOR_RADIUS = 12,  -- how close two teleport destinations count as the same spot
    ANCHOR_HITS = 3,     -- returning to one spot this often is the safespot cycle
}

-- Top-level workspace models with a Humanoid that are not player characters.
-- Rebuilt on a timer rather than per sample; the set barely changes.
function _0xa299._0xEXDScanNpcs()
    local list = {}
    local isPlayerChar = {}
    for _, p in ipairs(_0xa299._0x71bb:GetPlayers()) do
        if p.Character then isPlayerChar[p.Character] = true end
    end
    for _, obj in ipairs(workspace:GetChildren()) do
        if obj:IsA("Model") and not isPlayerChar[obj] then
            local hrp = obj:FindFirstChild("HumanoidRootPart") or obj:FindFirstChild("Torso")
            local hum = obj:FindFirstChildOfClass("Humanoid")
            if hrp and hum and hum.Health > 0 then
                list[#list + 1] = {model = obj, root = hrp}
            end
        end
    end
    _0xa299._0xEXD.npcs = list
end

-- Squared distances only: this is the innermost loop (every player against
-- every NPC, four times a second) and the actual distance is never needed, so
-- there is no reason to pay for a square root per comparison.
function _0xa299._0xEXDNearestNpc(pos)
    local npcs = _0xa299._0xEXD.npcs
    local best = nil
    local bestSq = _0xa299._0xEXD.LOCK_RANGE * _0xa299._0xEXD.LOCK_RANGE
    local px, py, pz = pos.X, pos.Y, pos.Z

    for i = 1, #npcs do
        local n = npcs[i]
        local root = n.root
        if root.Parent then
            local rp = root.Position
            local dx, dy, dz = rp.X - px, rp.Y - py, rp.Z - pz
            local sq = dx*dx + dy*dy + dz*dz
            if sq < bestSq then
                bestSq = sq
                best = n
            end
        end
    end
    return best
end

function _0xa299._0xEXDReset(name)
    _0xa299._0xEXD.players[name] = nil
end

function _0xa299._0xEXDSample()
    local S = _0xa299._0xEXD
    local now = tick()

    for _, plr in ipairs(_0xa299._0x71bb:GetPlayers()) do
        if plr ~= _0xa299._0x396d then
            local char = plr.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChildOfClass("Humanoid")

            if not (hrp and hum and hum.Health > 0) then
                -- Dead, streamed out or still loading. Wipe rather than pause:
                -- the position on return is unrelated to the one before.
                S.players[plr.Name] = nil
            else
                local rec = S.players[plr.Name]
                if not rec then
                    rec = {
                        firstSeen = now, lastPos = hrp.Position,
                        tps = {}, anchors = {},
                        still = 0, total = 0,
                        hover = 0, lock = nil,
                    }
                    S.players[plr.Name] = rec
                end

                -- FAST SIGNAL 1: offset lock against the nearest NPC.
                local npc = _0xa299._0xEXDNearestNpc(hrp.Position)
                if not npc then
                    rec.lock = nil
                else
                    local rel = hrp.Position - npc.root.Position
                    local L = rec.lock
                    if not L or L.model ~= npc.model then
                        rec.lock = {model = npc.model, ref = rel, moved = 0, last = npc.root.Position}
                    else
                        L.moved = L.moved + (npc.root.Position - L.last).Magnitude
                        L.last = npc.root.Position
                        -- Drifting past the tolerance restarts the measurement
                        -- rather than poisoning it, so only a genuinely
                        -- sustained lock ever accumulates distance.
                        if (rel - L.ref).Magnitude > S.LOCK_DEV then
                            L.ref = rel
                            L.moved = 0
                        end
                    end

                    -- FAST SIGNAL 2: hovering above it. Compared squared and
                    -- component-wise so the check allocates no Vector3s - it
                    -- runs for every player on every sample.
                    local pp, np = hrp.Position, npc.root.Position
                    local dy = pp.Y - np.Y
                    local hx, hz = pp.X - np.X, pp.Z - np.Z
                    local hSq = hx*hx + hz*hz
                    if dy >= S.HOVER_Y and hSq <= (S.HOVER_XZ * S.HOVER_XZ) then
                        rec.hover = rec.hover + 1
                    else
                        rec.hover = 0
                    end
                end

                do
                    local moved = (hrp.Position - rec.lastPos).Magnitude
                    rec.lastPos = hrp.Position
                    rec.total = rec.total + 1

                    if moved >= S.TELEPORT_MIN then
                        table.insert(rec.tps, now)

                        -- Record where they landed. Coming back to the same
                        -- handful of coordinates over and over is the farm
                        -- loop; wandering travel lands somewhere new each time.
                        local hit = false
                        for _, a in ipairs(rec.anchors) do
                            if (a.pos - hrp.Position).Magnitude <= S.ANCHOR_RADIUS then
                                a.hits = a.hits + 1
                                hit = true
                                break
                            end
                        end
                        if not hit then
                            table.insert(rec.anchors, {pos = hrp.Position, hits = 1})
                        end
                    elseif moved <= S.STILL_EPS then
                        rec.still = rec.still + 1
                    end

                    -- Drop teleports that fell out of the rolling window.
                    for i = #rec.tps, 1, -1 do
                        if now - rec.tps[i] > S.WINDOW then table.remove(rec.tps, i) end
                    end
                end
            end
        end
    end
end

-- Returns the offender's name plus the reasons, or nil.
function _0xa299._0xEXDJudge()
    local S = _0xa299._0xEXD
    local now = tick()

    for name, rec in pairs(S.players) do
        -- Fast signals first. No observation minimum: holding a fixed offset to
        -- a walking NPC, or floating above one, cannot be done by hand, so
        -- there is nothing to corroborate and nothing to wait for.
        local L = rec.lock
        if L and L.moved >= S.LOCK_NPC_MOVED then
            return name, ("locked to %s while it moved %d studs"):format(
                tostring(L.model and L.model.Name or "an NPC"), math.floor(L.moved))
        end

        if rec.hover >= S.HOVER_SAMPLES then
            return name, ("hovering above an NPC for %.1fs"):format(rec.hover * S.SAMPLE)
        end

        if (now - rec.firstSeen) >= S.OBSERVE_MIN and rec.total > 0 then
            local teleports = #rec.tps
            if teleports >= S.TELEPORTS_NEEDED then
                local topAnchor = 0
                for _, a in ipairs(rec.anchors) do
                    if a.hits > topAnchor then topAnchor = a.hits end
                end
                local stillRatio = rec.still / rec.total

                local reasons = {}
                if topAnchor >= S.ANCHOR_HITS then
                    table.insert(reasons, ("returns to the same spot x%d"):format(topAnchor))
                end
                if stillRatio >= S.STILL_RATIO then
                    table.insert(reasons, ("motionless %d%% of the time"):format(math.floor(stillRatio * 100)))
                end

                -- The teleport count alone is never enough.
                if #reasons > 0 then
                    table.insert(reasons, 1, ("%d teleports"):format(teleports))
                    return name, table.concat(reasons, ", ")
                end
            end
        end
    end
end

function _0xa299._0xEXDStop()
    if _0xa299._0xEXD.conn then
        pcall(function() _0xa299._0xEXD.conn:Disconnect() end)
        _0xa299._0xEXD.conn = nil
    end
    _0xa299._0xEXD.players = {}
end

function _0xa299._0xEXDStart()
    _0xa299._0xEXDStop()
    _0xa299._0xEXD.conn = _0xa299._0x64b8.Heartbeat:Connect(function()
        local S = _0xa299._0xEXD
        if not S.enabled or not _0xa299._0x1915.farming then return end

        local now = tick()
        if now - S.lastSample < S.SAMPLE then return end
        S.lastSample = now

        if now - S.lastNpcScan >= S.NPC_RESCAN then
            S.lastNpcScan = now
            pcall(_0xa299._0xEXDScanNpcs)
        end

        pcall(_0xa299._0xEXDSample)

        local name, why = nil, nil
        pcall(function() name, why = _0xa299._0xEXDJudge() end)
        if name then
            S.enabled = false  -- one shot; the hop follows
            _0xa299._0x8545:Notify("Farm", "Exploiter found: " .. name .. " (" .. why .. "), server hopping", 5, "warning")
            task.spawn(function()
                pcall(function() _0xa299._0x6ce0() end)
                task.wait(0.5)
                pcall(function() _0xa299._0xb5ef() end)
            end)
        end
    end)
end

_0xa299._0x71bb.PlayerRemoving:Connect(function(plr)
    _0xa299._0xEXDReset(plr.Name)
