-- SERVER SHUTDOWN DETECTION
--
-- The previous version polled Notification.ShortMessageTemplate every
-- Heartbeat and could never fire. newNotification CLONES that template, parents
-- the clone, renames it Notif1..Notif6 and only then writes the text
-- (gamescript.txt:5866-5905) - the template itself is an empty prototype whose
-- text never changes. It was reading a blank label forever.
--
-- Two signals now, both event-driven instead of polled:
--   1. The server's own "Shutting Down" DataEvent (gamescript.txt:10468).
--      Earliest and most reliable - no text matching involved.
--   2. Any notification that mentions a shutdown, as a backstop in case the
--      event is not sent in every shutdown path.
---------------------------------------------------------------------
_0xa299._0x1915.shutdownConns = {}

function _0xa299._0xShutdownFire(source)
    -- Both signals can land for the same shutdown; only hop once.
    if _0xa299._0x1915.shutdownFired then return end
    if not _0xa299._0x1915.serverHopOnShutdown then return end
    if not _0xa299._0x1915.farming then return end
    _0xa299._0x1915.shutdownFired = true

    _0xa299._0x8545:Notify("Farm", "Server shutting down, server hopping", 4, "warning")
    task.spawn(function()
        pcall(function() _0xa299._0x6ce0() end)
        task.wait(0.5)
        pcall(function() _0xa299._0xb5ef() end)
    end)
end

function _0xa299._0xShutdownStop()
    for _, c in ipairs(_0xa299._0x1915.shutdownConns or {}) do
        pcall(function() c:Disconnect() end)
    end
    _0xa299._0x1915.shutdownConns = {}
end

function _0xa299._0xShutdownStart()
    _0xa299._0xShutdownStop()
    _0xa299._0x1915.shutdownFired = false

    -- 1. Direct server signal.
    pcall(function()
        local events = _0xa299._0xe08d:FindFirstChild("Events")
        local dataEvent = events and events:FindFirstChild("DataEvent")
        if not dataEvent then return end
        table.insert(_0xa299._0x1915.shutdownConns, dataEvent.OnClientEvent:Connect(function(action)
            if tostring(action) == "Shutting Down" then
                _0xa299._0xShutdownFire("event")
            end
        end))
    end)

    -- 2. Visible warning, as a backstop.
    pcall(function()
        local pg = _0xa299._0x396d:FindFirstChild("PlayerGui")
        local cg = pg and pg:FindFirstChild("ClientGui")
        local mf = cg and cg:FindFirstChild("Mainframe")
        local nf = mf and mf:FindFirstChild("Notification")
        if not nf then return end

        local function inspect(inst)
            -- Deferred because the clone is PARENTED before its name and text
            -- are written; reading on the ChildAdded frame gets a blank label.
            task.defer(function()
                pcall(function()
                    local msg = inst:FindFirstChild("Message")
                    if not (msg and msg:IsA("TextLabel")) then return end
                    -- Matching "shut" alone rather than requiring
                    -- automatic + shutdown + minute together, which was brittle
                    -- enough that any wording change would silently break it.
                    if msg.Text:lower():find("shut") then
                        _0xa299._0xShutdownFire("notification")
                    end
                end)
            end)
        end

        table.insert(_0xa299._0x1915.shutdownConns, nf.ChildAdded:Connect(inspect))
        -- Catch a warning already on screen when the toggle is flipped.
        for _, c in ipairs(nf:GetChildren()) do inspect(c) end
    end)
end

