---------------------------------------------------------------------
-- ANTI SCRAMBLED MIND
--
-- Scrambled Mind is ONLY a `ScrambledMind` attribute the server puts on your
-- character. Every bit of the scrambling happens in the game's own client
-- input handler, which re-reads that attribute on each key press - verified
-- still true on v1551, 11 read sites in the client LocalScript (10630-10674,
-- 11106, 14850-14856) swapping W<->S, A<->D, Q<->R, M1<->F and M2<->Q.
--
-- So clearing it on our client the moment it arrives makes every one of those
-- reads find nothing and the controls stay normal. Local only - client
-- attribute writes do not replicate - so the server-side genjutsu just runs
-- out, and if the server re-applies it we clear it again. The clear re-fires
-- the changed signal once, which then finds the attribute already gone, so
-- there is no loop.
---------------------------------------------------------------------
_0xa299._0xAntiScramble = false
do
    local ATTR = "ScrambledMind"
    local conns = {}

    local function clear(char)
        if char and char:GetAttribute(ATTR) then
            pcall(function() char:SetAttribute(ATTR, nil) end)
        end
    end

    local function watch(char)
        if conns.attr then
            pcall(function() conns.attr:Disconnect() end)
            conns.attr = nil
        end
        if not char then return end
        clear(char)   -- already scrambled when this started
        conns.attr = char:GetAttributeChangedSignal(ATTR):Connect(function()
            if _0xa299._0xAntiScramble then clear(char) end
        end)
    end

    _0xa299._0xGENJ:AddToggle("Anti Scrambled Mind", false, function(Value)
        _0xa299._0xAntiScramble = Value
        for k, c in pairs(conns) do
            pcall(function() c:Disconnect() end)
            conns[k] = nil
        end
        if Value then
            watch(_0xa299._0x396d.Character)
            conns.char = _0xa299._0x396d.CharacterAdded:Connect(watch)
            _0xa299._0x8545:Notify("Combat", "Anti Scrambled Mind enabled", 3, "check")
        else
            _0xa299._0x8545:Notify("Combat", "Anti Scrambled Mind disabled", 3, "info")
        end
    end, {Type = "info", Text = "Makes scrambled mind not invert your keys"})
end

---------------------------------------------------------------------
-- ANTI FOG ILLUSION
--
-- The whole effect is one client call. The server sends your client
-- "FogIllusion" and the game's handler does exactly this (client 18888):
--     require(Rep.Effects.FogIllusion.EffectsModule).StartVFX(p144, nil, nil, p145, p146)
-- and on "StopFogIllusion" calls StopVFX() and re-applies the location
-- ambience. Nothing else reads it - unlike Scrambled Mind there is no
-- attribute driving the visuals, so there is nothing to clear; killing that
-- one call is the whole feature.
--
-- require() is cached per client, so swapping StartVFX once covers every
-- future cast, and the original goes back on toggle off. It is a plain dot
-- call in the game's handler, so a bare no-op is a correct replacement
-- regardless of arity. This same swap was verified against another effect
-- module with an identical layout, so the shape is known-good.
--
-- Enabling also runs the module's OWN StopVFX once, so an illusion already
-- on screen is cleared by the game's teardown rather than by us guessing
-- which camera and GUI state to put back.
--
-- Deliberately does NOT touch the `FogIllusion` character attribute: the
-- visuals do not come from it, and Auto Genjutsu Release below uses it as
-- its trigger. Clearing it would quietly stop that feature firing.
---------------------------------------------------------------------
_0xa299._0xAntiFog = false
do
    local M, origStart

    local function resolve()
        if M then return true end
        pcall(function()
            M = require(_0xa299._0xe08d.Effects.FogIllusion.EffectsModule)
        end)
        if type(M) ~= "table" or type(M.StartVFX) ~= "function" then
            M = nil
            return false
        end
        origStart = M.StartVFX
        return true
    end

    _0xa299._0xGENJ:AddToggle("Anti Fog Illusion", false, function(Value)
        _0xa299._0xAntiFog = Value
        if Value then
            if not resolve() then
                _0xa299._0xAntiFog = false
                _0xa299._0x8545:Notify("Combat", "Could not hook Fog Illusion module", 5, "error")
                return
            end
            pcall(function() if setreadonly then setreadonly(M, false) end end)
            M.StartVFX = function() return nil end
            if type(M.StopVFX) == "function" then
                pcall(function() M.StopVFX() end)
            end
            _0xa299._0x8545:Notify("Combat", "Anti Fog Illusion enabled", 3, "check")
        else
            if M and origStart then
                pcall(function() if setreadonly then setreadonly(M, false) end end)
                M.StartVFX = origStart
            end
            _0xa299._0x8545:Notify("Combat", "Anti Fog Illusion disabled", 3, "info")
        end
    end, {Type = "info", Text = "Stops fog illusion taking over your camera and screen"})
end

---------------------------------------------------------------------
-- AUTO GENJUTSU RELEASE
--
-- Casts Genjutsu Release the moment you are caught. Every trigger is aimed at
-- YOU, so someone else being caught nearby never fires it:
--   Fog Illusion   - server sets a `FogIllusion` attribute on your character
--   Scrambled Mind - server sets a `ScrambledMind` attribute on your character
--   Feather        - server sends your client "FeatherGenjutsu", and
--                    "StopFeatherGenjutsu" when it ends
--
-- The cast goes through the game's OWN activateSkill(nil, "Genjutsu Release"),
-- the same form the game uses for Kotoamatsukami, so the animation, chakra
-- cost, cooldown check and startSkill arguments all stay consistent. Passing
-- "MouseButton1" there would cast the held weapon's M1 instead.
--
-- PORTING NOTE: PRIVATE hunts the game's client state (the `v` table, with
-- skillInUse / Settings) among activateSkill's upvalues. That no longer works
-- on v1551 - checked live, there is no such upvalue; upvalue 2 is GameManager
-- (hasSkill, Traits, Settings, Items, Skills) and 3 is the player data
-- (CurrentWeapon, Traits). The state is a script GLOBAL now, so it is read
-- through getsenv(ClientGui.LocalScript).v, which is the idiom used elsewhere
-- in this file and verified to expose skillInUse / Settings / Selected.
---------------------------------------------------------------------
_0xa299._0xAutoGenjutsu = false
do
    local SKILL = "Genjutsu Release"
    local AG = { fn = nil, gm = nil, dataIdx = nil, script = nil, select = nil,
                 featherUntil = 0, busy = false, conns = {}, charConns = {} }

    -- The game's client state. A script global, not an upvalue - see above.
    local function clientState()
        local v
        pcall(function()
            local env = getsenv(_0xa299._0x396d.PlayerGui.ClientGui.LocalScript)
            v = env and env.v
        end)
        return v
    end

    local function skillsModule()
        local sm
        pcall(function()
            local env = getsenv(_0xa299._0x396d.PlayerGui.ClientGui.LocalScript)
            sm = env and rawget(env, "skillsModule")
        end)
        return sm
    end

    -- activateSkill is a global in the game LocalScript's environment. The
    -- script restarts on respawn, so only accept the copy belonging to the
    -- LIVE script - an old one lingers in the GC and calling it does nothing.
    local function resolve()
        if AG.fn and AG.script and AG.script.Parent then return true end
        AG.fn, AG.gm, AG.dataIdx, AG.script, AG.select = nil, nil, nil, nil, nil
        pcall(function()
            for _, f in ipairs(getgc(false)) do
                if type(f) == "function" then
                    local named, name = pcall(debug.info, f, "n")
                    if named and name == "activateSkill" then
                        local env = getfenv(f)
                        local s = rawget(env, "script")
                        local fn = rawget(env, "activateSkill")
                        if fn and s and s:IsDescendantOf(_0xa299._0x396d) then
                            AG.fn, AG.script = fn, s
                            break
                        end
                    end
                end
            end
            if not AG.fn then return end
            for i, uv in ipairs(debug.getupvalues(AG.fn)) do
                if type(uv) == "table" then
                    if type(rawget(uv, "hasSkill")) == "function" then
                        AG.gm = uv
                    elseif rawget(uv, "CurrentWeapon") ~= nil and rawget(uv, "Traits") ~= nil then
                        AG.dataIdx = i
                    end
                elseif type(uv) == "function" then
                    local ok, n = pcall(debug.info, uv, "n")
                    if ok and n == "selectNewItem" then AG.select = uv end
                end
            end
        end)
        return AG.fn ~= nil
    end

    -- The game only casts while you are holding something (it checks
    -- Selected ~= "") and Genjutsu Release has no bypass for that. With empty
    -- hands, press the skill's own slot through the game's selectNewItem -
    -- how it is normally cast, and the game unselects it afterwards - else
    -- fall back to the held weapon.
    local function ensureSelected(skill)
        local st = clientState()
        if not st or st.Selected ~= "" or not AG.select or not AG.dataIdx then return end
        local ok, data = pcall(debug.getupvalue, AG.fn, AG.dataIdx)
        if not ok or type(data) ~= "table" then return end
        pcall(AG.select, data, skill)
        if st.Selected == "" and data.CurrentWeapon then
            pcall(AG.select, data, data.CurrentWeapon)
        end
    end

    -- Awakening sub-moves are NOT in UnlockedSkills, so hasSkill returns false
    -- for them; they are castable only while that awakening is active.
    local function fromAwakening(skill)
        local st, sk = clientState(), skillsModule()
        if not st or not sk then return false end
        local aw = st.Settings and st.Settings.Awakened and st.Settings.Awakened.Value
        local def = aw and aw ~= "" and sk[aw]
        if not def then return false end
        return def.MouseButton1 == skill or def.MouseButton2 == skill
            or def["C + M1"] == skill or def["C + M2"] == skill
    end

    -- Player data is a ref upvalue the game reassigns, so re-read it each
    -- time. If ownership cannot be checked, let the game decide.
    local function owns(skill)
        if fromAwakening(skill) then return true end
        if not AG.gm or not AG.dataIdx then return true end
        local ok, data = pcall(debug.getupvalue, AG.fn, AG.dataIdx)
        if not ok or type(data) ~= "table" then return true end
        local okh, has = pcall(AG.gm.hasSkill, AG.gm, data, skill)
        return not okh or (has and true or false)
    end

    -- Cooldowns[you][skill] is a NumberValue holding the server time the skill
    -- was LAST USED and it is never removed, so the entry existing means
    -- nothing - compare the elapsed time against the game's own getCooldown.
    local function onCooldown(skill)
        local all  = _0xa299._0xe08d:FindFirstChild("Cooldowns")
        local mine = all and all:FindFirstChild(_0xa299._0x396d.Name)
        local used = mine and mine:FindFirstChild(skill)
        if not used then return false end
        local cd = 30
        if AG.gm then
            local settings = _0xa299._0xe08d:FindFirstChild("Settings")
            local mySettings = settings and settings:FindFirstChild(_0xa299._0x396d.Name)
            local ok, v = pcall(AG.gm.getCooldown, AG.gm, _0xa299._0x396d.Character, skill, mySettings)
            if ok and type(v) == "number" then cd = v end
        end
        return workspace:GetServerTimeNow() - used.Value < cd + 0.25
    end

    local function caught()
        local c = _0xa299._0x396d.Character
        if not c then return false end
        if os.clock() < AG.featherUntil then return true end
        if c:GetAttribute("FogIllusion") then return true end
        -- With Anti Scrambled Mind on, Scrambled Mind is already neutralised;
        -- do not burn the 30 s cooldown on a genjutsu that is already handled.
        return c:GetAttribute("ScrambledMind") and not _0xa299._0xAntiScramble or false
    end

    local function release()
        if AG.busy or not _0xa299._0xAutoGenjutsu then return end
        AG.busy = true
        task.spawn(function()
            local deadline = os.clock() + 4
            while _0xa299._0xAutoGenjutsu and os.clock() < deadline and caught() do
                if not onCooldown(SKILL) and resolve() and owns(SKILL) then
                    ensureSelected(SKILL)
                    pcall(AG.fn, nil, SKILL)
                end
                task.wait(0.4)
            end
            AG.busy = false
        end)
    end

    local function watchCharacter(char)
        for _, c in ipairs(AG.charConns) do pcall(function() c:Disconnect() end) end
        AG.charConns = {}
        if not char then return end
        for _, attr in ipairs({ "FogIllusion", "ScrambledMind" }) do
            AG.charConns[#AG.charConns + 1] = char:GetAttributeChangedSignal(attr):Connect(function()
                if attr == "ScrambledMind" and _0xa299._0xAntiScramble then return end
                if char:GetAttribute(attr) then release() end
            end)
        end
        if caught() then release() end   -- already caught when this started
    end

    local function stop()
        for _, c in ipairs(AG.conns) do pcall(function() c:Disconnect() end) end
        for _, c in ipairs(AG.charConns) do pcall(function() c:Disconnect() end) end
        AG.conns, AG.charConns = {}, {}
        AG.featherUntil = 0
    end

    _0xa299._0xGENJ:AddToggle("Auto Genjutsu Release", false, function(Value)
        _0xa299._0xAutoGenjutsu = Value
            stop()
            if not Value then
                _0xa299._0x8545:Notify("Combat", "Auto Genjutsu Release disabled", 3, "info")
                return
            end

            local dataEvent = _0xa299._0xe08d:WaitForChild("Events"):WaitForChild("DataEvent")
            -- An extra listener; it runs alongside the game's own handler.
            AG.conns[#AG.conns + 1] = dataEvent.OnClientEvent:Connect(function(kind)
                if kind == "FeatherGenjutsu" then
                    AG.featherUntil = os.clock() + 15   -- cleared early by the stop event
                    release()
                elseif kind == "StopFeatherGenjutsu" then
                    AG.featherUntil = 0
                end
            end)
            AG.conns[#AG.conns + 1] = _0xa299._0x396d.CharacterAdded:Connect(watchCharacter)
            watchCharacter(_0xa299._0x396d.Character)

            if resolve() then
                if owns(SKILL) then
                    _0xa299._0x8545:Notify("Combat", "Auto Genjutsu Release enabled", 3, "check")
                else
                    _0xa299._0x8545:Notify("Combat",
                        "Enabled - but you do not own Genjutsu Release, so nothing will cast", 6, "warning")
                end
        else
            _0xa299._0x8545:Notify("Combat",
                "Enabled (game skill function not found yet)", 5, "warning")
        end
    end, {Type = "info", Text = "Breaks you out of genjutsu automatically"})
end

_0xa299._0x8545:Notify("Welcome", "Kyo Loaded", 5, "check")
